def uzunluk_metni(b: Optional[Dict[str, float]] = None) -> str:
    d = dict(b or uzunluk_beyani())
    if not d.get("kuruldu"):
        return ("  ÜÇÜNCÜ QUDİT KATMANI (uzunluk): KURULMADI -- kırmızı "
                "(ferman 2-Õ)")
    return "\n".join([
        "  ÜÇÜNCÜ QUDİT KATMANI -- UZUNLUK SÜPERPOZİSYONU (ferman 2-Õ)",
        "    aynı anda 1 … %d belirteçlik çıktı hâlleri taşınır;"
        % int(d["hadd"]),
        "    üst hudut vardır, ALT HUDUT YOKTUR.",
        "    nedensel cephe %d   son durma hükmü %d belirteç"
        % (int(d["cephe"]), int(d["hüküm"])),
        "    ÇIKTIDA ÜST HUDUT YOKTUR (ferman 2-Ó-B): her adımda durma"
        " genliği %.6e ile" % d.get("durma_genliği", 0.0),
        "    devam genliği %.6e tartılır; model uygun gördüğünde durur."
        % d.get("devam_genliği", 0.0),
        "    dağılım entropisi %.6f nat   tepe ihtimali %.6e"
        % (d["entropi"], d["tepe_ihtimali"]),
        "    hadde taşan kuyruk ihtimali %.6e   (ölçü kapatılabilir: %s)"
        % (d["kuyruk"], "açık" if d.get("açık") else "KAPALI"),
        "    Hüküm determinist Fubini-Study okumasıdır, zar atılmaz"
        " (ferman 2-Ĵ).",
    ])


class MahalliYazmac:

    def kok_indisi(self, ad: str) -> int:
        if ad not in self._kok:
            self._kok[ad] = len(self._kok)
            self.cartan = np.concatenate([self.cartan, np.zeros(1)])
        return int(self._kok[ad])

    def cartan_ekle(self, ad: str, aci: float) -> int:
        k = self.kok_indisi(str(ad))
        self.cartan[k] += float(aci)
        self.cartan[k] = (math.remainder(float(self.cartan[k]),
                                         2.0 * math.pi))
        _MAHALLI["kök"] = float(self.cartan.size)
        _MAHALLI["cartan_normu"] = float(np.abs(self.cartan).sum())
        return k

    def cartan_oku(self, ad: str) -> float:
        k = self._kok.get(str(ad))
        return 0.0 if k is None else float(self.cartan[int(k)])

    def kok_agirligi(self) -> np.ndarray:
        n = max(1, int(self.cartan.size))
        return np.arange(1, n + 1, dtype=float) / float(n)

    def seviye_fazi(self, taban: Optional[int] = None) -> np.ndarray:
        q = int(self.taban if taban is None else taban)
        v = np.zeros(q, float)
        if not self._kok:
            return v
        for ad, k in self._kok.items():
            v[int(k) % q] += float(self.cartan[int(k)])
        _MAHALLI["seviye_fazı"] = float(np.abs(v).sum())
        _MAHALLI["seviye_kökü"] = float(len(self._kok))
        return v

    def kuresel_faz(self) -> float:
        return float(np.dot(self.cartan, self.kok_agirligi()))

    def __init__(self, taban: int) -> None:
        self.qudit = int(ZIRH_QUDITI)
        self._kok: Dict[str, int] = {}
        self.cartan = np.zeros(0, float)
        self.taban = max(2, int(taban))
        self.yigin = 0
        self.pencere = 0
        self.hal = np.zeros((0, self.qudit, self.taban), complex)
        _MAHALLI["kuruldu"] = 1.0
        _MAHALLI["qudit"] = float(self.qudit)
        _MAHALLI["taban"] = float(self.taban)

    def hazirla(self, pencere: int, yigin: int) -> None:
        p = max(1, min(int(pencere), self.qudit))
        y = max(1, int(yigin))
        if y > self.yigin:
            gereken = int(y) * int(self.qudit) * int(self.taban) * 16
            from nefs.donanim import bellek_haddi
            had = bellek_haddi()
            assert had is None or gereken <= int(had), (
                "MAHALLÎ ZIRH ÖLÇÜLEN BELLEĞE SIĞMIYOR: %d qudit × %d "
                "seviye × 16 bayt × %d yığın = %.2f GB, ölçülen hadd "
                "%.2f GB (ferman 2-S, 2-I: bütçe ölçülür, sığmayan bütçe "
                "kurulmaz)"
                % (self.qudit, self.taban, y, gereken / 1e9,
                   float(had or 0) / 1e9))
            self.hal = np.zeros((y, self.qudit, self.taban), complex)
            self.hal[..., 0] = 1.0 / math.sqrt(float(self.qudit))
            self.yigin = y
            _MAHALLI["tahsis"] += 1.0
            _MAHALLI["bayt"] = float(self.hal.nbytes)
            _MAHALLI["seviye"] = float(self.taban)
        self.pencere = p
        _MAHALLI["pencere"] = float(p)
        _MAHALLI["yığın"] = float(self.yigin)
        _MAHALLI["seyirci"] = float(self.qudit - p)

    @property
    def genlik(self) -> np.ndarray:
        return np.linalg.norm(self.hal, axis=-1)

    @property
    def faz(self) -> np.ndarray:
        return np.angle(self.hal.sum(axis=-1))

    def koordinat(self) -> np.ndarray:
        return self._koordinat

    def yerlestir(self, basamak: np.ndarray, dolu: np.ndarray) -> None:
        b = np.asarray(basamak, np.int64)
        assert b.shape[0] <= self.yigin and b.shape[1] == self.pencere, (
            "aktif pencere zırhın içinde nefes alır: %r ≠ %r "
            "(ferman 2-Ğ)" % (b.shape, (self.yigin, self.pencere)))
        n = int(self.pencere)
        w = 2.0 * (b.astype(float) / float(self.taban - 1)) - 1.0
        self._koordinat = w
        agirlik = np.asarray(dolu, bool).astype(float)
        norm = np.maximum(np.linalg.norm(agirlik, axis=-1, keepdims=True),
                          1e-300)
        B = int(b.shape[0])
        seviye = np.mod(b, self.taban)
        self.hal[:B, :n, :] = 0.0
        satir = np.repeat(np.arange(B), n)
        sutun = np.tile(np.arange(n), B)
        self.hal[satir, sutun, seviye.reshape(-1)] = (
            (agirlik / norm).reshape(-1)
            * np.exp(1j * math.pi * w.reshape(-1)))

    def kapilari_vur(self, kontrol: np.ndarray, hedef: np.ndarray,
                     bag: np.ndarray) -> float:
        k = np.asarray(kontrol, np.int64).reshape(-1)
        h = np.asarray(hedef, np.int64)
        j = np.asarray(bag, float).reshape(-1)
        assert k.size == j.size, (
            "her kapının bir bağ kuvveti olmalı: %d kontrol, %d bağ"
            % (k.size, j.size))
        if not _MAHALLI["açık"] or k.size == 0:
            return 0.0
        h = h if h.ndim == 2 else np.broadcast_to(
            h.reshape(1, -1), (self.yigin, h.size))
        h = np.mod(h, max(1, int(self.pencere)))
        kk = np.clip(k, 0, self.qudit - 1)
        B = int(h.shape[0])
        kontrol_fazi = np.angle(self.hal[:B, kk, :].sum(axis=-1))
        kayma = j.reshape(1, -1) * kontrol_fazi
        satir = np.repeat(np.arange(B), h.shape[1])
        sutun = h.reshape(-1)
        donme = np.exp(1j * kayma.reshape(-1))
        np.multiply.at(self.hal, (satir, sutun), donme[:, None])
        dokunulan = np.unique(sutun)
        _MAHALLI["vuruş"] += float(k.size)
        _MAHALLI["dokunulan"] = float(dokunulan.size)
        _MAHALLI["faz_kayması"] = float(np.mean(np.abs(kayma)))
        return float(np.mean(np.abs(kayma)))

    def _seviye_operatoru(self, M: np.ndarray, cins: str) -> np.ndarray:
        A = np.zeros((self.taban, self.taban), float)
        S = np.asarray(M, float)
        k = int(min(self.taban, S.shape[0]))
        A[:k, :k] = S[:k, :k]
        nrm = float(np.linalg.norm(A))
        if nrm <= 0.0:
            return np.eye(self.taban, dtype=complex)
        A = A / nrm
        if cins == "uzay":
            w, V = np.linalg.eigh(0.5 * (A + A.T))
            _MAHALLI["aşkın_eigh"] = _MAHALLI.get("aşkın_eigh", 0.0) + 1.0
            _MAHALLI["aşkın_exp"] = _MAHALLI.get("aşkın_exp", 0.0) + 1.0
            return (V * np.exp(1j * w)) @ V.conj().T
        if cins == "kategori":
            w, V = np.linalg.eigh(1j * (0.5 * (A - A.T)))
            _MAHALLI["aşkın_eigh"] = _MAHALLI.get("aşkın_eigh", 0.0) + 1.0
            _MAHALLI["aşkın_exp"] = _MAHALLI.get("aşkın_exp", 0.0) + 1.0
            return (V * np.exp(-1j * w)) @ V.conj().T
        return A.astype(complex)

    def modlari_vur(self, izdusum: Dict[str, np.ndarray],
                    pay: Sequence[float]) -> Dict[str, float]:
        p = np.asarray(list(pay), float).reshape(-1)
        assert p.size == 3, (
            "dereceli devir üç bileşenlidir (𝒮_simetrik, 𝒜_yönlü, "
            "Ω_yırtık); %d verildi (ferman 2-Ā-B)" % p.size)
        assert self.yigin > 0 and self.pencere > 0, (
            "MODLAR BOŞ ZIRHA VURULAMAZ -- evvelâ hazırlanır (ferman 2-A)")
        p = np.maximum(p, 0.0)
        top = float(p.sum())
        assert top > 0.0, (
            "HODGE PAYLARI TAMAMEN SÖNDÜ -- üç bileşenin toplamı sıfır; "
            "bu, hendesenin ölçülmediğinin delilidir (ferman 5)")
        p = p / top
        n = int(self.pencere)
        sinir = np.cumsum(np.rint(p * float(n)).astype(np.int64))
        sinir[-1] = n
        evvel = float(np.linalg.norm(self.hal[:, :n, :]))
        adlar = ("uzay", "kategori", "operad")
        anahtar = ("Π_uzay", "Π_kategori", "Π_operad")
        sayim: Dict[str, float] = {}
        bas = 0
        for ad, ah, son in zip(adlar, anahtar, sinir.tolist()):
            son = int(min(max(son, bas), n))
            sayim["mod_%s" % ad] = float(son - bas)
            if son > bas:
                U = self._seviye_operatoru(izdusum[ah], ad)
                dilim = self.hal[:, bas:son, :]
                self.hal[:, bas:son, :] = dilim @ U.T
            bas = son
        sonra = self.hal[:, :n, :]
        nrm = np.linalg.norm(sonra, axis=-1, keepdims=True)
        canli = nrm > 0.0
        assert bool(canli.any()), (
            "DERECELİ DEVİR AKTİF PENCEREYİ TAMAMEN SÖNDÜRDÜ -- "
            "izdüşüm demeti yanlış kurulmuş (ferman 5)")
        self.hal[:, :n, :] = np.where(canli, sonra / np.where(canli, nrm,
                                                              1.0), sonra)
        sayim["mod_vuruş"] = float(n)
        sayim["mod_norm_evvel"] = evvel
        sayim["mod_norm_sonra"] = float(np.linalg.norm(self.hal[:, :n, :]))
        _MAHALLI.update(sayim)
        _MAHALLI["mod_çağrı"] = _MAHALLI.get("mod_çağrı", 0.0) + 1.0
        return sayim

    def genlik_sondur(self, hedef: np.ndarray, sonum) -> float:
        h = np.mod(np.asarray(hedef, np.int64).reshape(-1),
                   max(1, int(self.pencere)))
        c = np.asarray(sonum, float).reshape(-1)
        if h.size == 0:
            return 0.0
        c = np.resize(c, h.size)
        self.hal[:, h, :] = self.hal[:, h, :] * c[None, :, None]
        _MAHALLI["sönüm"] += float(h.size)
        return float(np.abs(1.0 - c).mean())

    def uzunluk_katmani(self, cephe: int, hadd: int = 0) -> np.ndarray:
        c = int(cephe) % self.qudit
        L = max(1, min(int(hadd) if int(hadd) > 0 else self.qudit,
                       self.qudit - c))
        dilim = self.hal[:, c:c + L, :]
        g = np.linalg.norm(dilim, axis=-1).mean(axis=0)
        f = np.angle(dilim.sum(axis=-1)).mean(axis=0)
        devam = np.clip(g / max(float(g.max()), 1e-300), 0.0, 1.0)
        dur = np.sqrt(np.maximum(1.0 - devam * devam, 0.0))
        us = np.concatenate([[0.0], np.cumsum(np.log(
            np.maximum(devam, 1e-300)))[:-1]])
        us = us + np.log(np.maximum(dur, 1e-300))
        us = us - float(us.max())
        dal = np.exp(us) * np.exp(1j * np.cumsum(f))
        nrm = float(np.linalg.norm(dal))
        assert nrm > 0.0, (
            "uzunluk katmanı tamamen söndü -- hiçbir çıktı boyu "
            "taşınmıyor (ferman 2-Õ)")
        self._uzunluk = dal / nrm
        self._uzunluk_cephesi = c
        P = np.abs(self._uzunluk) ** 2
        _UZUNLUK["kuruldu"] = 1.0
        _UZUNLUK["hadd"] = float(L)
        _UZUNLUK["cephe"] = float(c)
        _UZUNLUK["entropi"] = float(
            -np.sum(P * np.log(np.maximum(P, 1e-300))))
        _UZUNLUK["tepe_ihtimali"] = float(P.max())
        _UZUNLUK["kuyruk"] = float(
            1.0 - P.sum()) if P.sum() < 1.0 else 0.0
        return self._uzunluk

    def durma_hukmu(self, adim: int) -> bool:
        dal = getattr(self, "_uzunluk", None)
        assert dal is not None, (
            "uzunluk katmanı hiç açılmadı -- durma hükmü verecek bir "
            "hâl yok; üretim susmayan bir döngüye düşerdi (ferman "
            "2-Õ, 2-Ó-B)")
        if not _UZUNLUK.get("açık"):
            return True
        P = np.abs(dal) ** 2
        top = float(P.sum())
        assert top > 0.0, (
            "uzunluk katmanı tamamen söndü -- durma hükmü verilemez "
            "(ferman 2-Õ)")
        k = int(adim)
        if k >= P.size:
            return True
        dur = float(P[k])
        devam = float(P[k + 1:].sum())
        _UZUNLUK["durma_genliği"] = dur / top
        _UZUNLUK["devam_genliği"] = devam / top
        durdu = bool(dur > devam)
        if durdu:
            _UZUNLUK["hüküm"] = float(k + 1)
        return durdu

    def kok_seviyesi(self, ad: str) -> int:
        return int(self.kok_indisi(str(ad)) % int(self.taban))

    def sektor_yigini(self, ad: str) -> np.ndarray:
        assert self.yigin > 0 and self.pencere > 0, (
            "SEKTÖR AĞIRLIĞI BOŞ ZIRHTAN OKUNAMAZ -- evvelâ `hazirla` "
            "koşar (ferman 2-A, 2-Ö)")
        s = self.kok_seviyesi(ad)
        n = int(self.pencere)
        _MAHALLI["sektör_okuma"] = _MAHALLI.get("sektör_okuma", 0.0) + 1.0
        return np.sum(np.abs(self.hal[:, :n, s]) ** 2, axis=1)

    def sektor_agirligi(self, ad: str,
                        indis: Optional[np.ndarray] = None) -> complex:
        k = self.kok_indisi(str(ad))
        w = self.sektor_yigini(ad)
        agir = float(w.mean()) if w.size else 0.0
        return complex(agir * np.exp(1j * float(self.cartan[k])))

    def kulli_agirlik(self) -> float:
        assert self.yigin > 0 and self.pencere > 0, (
            "KÜLLÎ AĞIRLIK BOŞ ZIRHTAN OKUNAMAZ (ferman 2-A)")
        n = int(self.pencere)
        _MAHALLI["küllî_okuma"] = _MAHALLI.get("küllî_okuma", 0.0) + 1.0
        return float(np.sum(np.abs(self.hal[:, :n, :]) ** 2))

    def kok_dagilimi(self, ad: str) -> np.ndarray:
        s = self.kok_seviyesi(ad)
        n = int(self.pencere)
        p = np.abs(self.hal[:, :n, s]) ** 2
        top = p.sum(axis=1, keepdims=True)
        canli = top > 0.0
        return np.where(canli, p / np.where(canli, top, 1.0),
                        1.0 / float(max(1, n)))

    def kok_kapisi(self, ad: str, M: np.ndarray) -> int:
        assert self.yigin > 0 and self.pencere > 0, (
            "KÖK KAPISI BOŞ ZIRHA VURULAMAZ (ferman 2-A)")
        s = self.kok_seviyesi(ad)
        A = np.asarray(M, complex)
        assert A.ndim == 2 and A.shape[0] == A.shape[1], (
            "kök kapısı kare olmalı, %r verildi" % (A.shape,))
        n = int(self.pencere)
        g = int(min(A.shape[0], self.taban))
        bas = int(s)
        son = int(min(self.taban, bas + g))
        k = son - bas
        if k < 2:
            _MAHALLI["kök_düşen"] = _MAHALLI.get("kök_düşen", 0.0) + 1.0
            return 0
        self.hal[:, :n, bas:son] = (self.hal[:, :n, bas:son]
                                    @ A[:k, :k].T)
        _MAHALLI["kök_kapısı"] = _MAHALLI.get("kök_kapısı", 0.0) + 1.0
        return k

    def kok_donmesi(self, ad: str, aci: np.ndarray) -> int:
        assert self.yigin > 0 and self.pencere > 0, (
            "KÖK DÖNMESİ BOŞ ZIRHA VURULAMAZ (ferman 2-A)")
        a = np.asarray(aci, float).reshape(-1)
        if a.size == 0:
            return 0
        s = self.kok_seviyesi(ad)
        n = int(self.pencere)
        cift = int(min(a.size, (int(self.taban) - s) // 2))
        if cift < 1:
            _MAHALLI["kök_düşen"] = _MAHALLI.get("kök_düşen", 0.0) + 1.0
            return 0
        a = a[:cift]
        c, sn = np.cos(a), np.sin(a)
        u = self.hal[:, :n, s:s + 2 * cift:2]
        v = self.hal[:, :n, s + 1:s + 2 * cift:2]
        self.hal[:, :n, s:s + 2 * cift:2] = c * u - sn * v
        self.hal[:, :n, s + 1:s + 2 * cift:2] = sn * u + c * v
        _MAHALLI["kök_dönmesi"] = _MAHALLI.get("kök_dönmesi", 0.0) + 1.0
        _MAHALLI["aşkın_cos"] = _MAHALLI.get("aşkın_cos", 0.0) + 1.0
        _MAHALLI["aşkın_sin"] = _MAHALLI.get("aşkın_sin", 0.0) + 1.0
        return 2 * cift

    def senet_dilimi(self) -> np.ndarray:
        if self.yigin <= 0 or self.pencere <= 0:
            return np.zeros((0, 0), complex)
        n = int(self.pencere)
        _MAHALLI["senet_bandı"] = _MAHALLI.get("senet_bandı", 0.0) + 1.0
        _MAHALLI["senet_baytı"] = (_MAHALLI.get("senet_baytı", 0.0)
                                   + float(self.hal[:, :n, :].nbytes))
        return np.asarray(self.hal[:, :n, :], complex).copy()

    def beyan(self) -> Dict[str, float]:
        return mahalli_beyani()
# ==== BİTTİ: kuantum/mahalli_yazmac.py ====

# ==== BAŞLIYOR: kuantum/nqs.py ====
from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Dict, Optional, Tuple

import numpy as np

__all__ = ["NqsAyari", "ChebyshevKan", "chebyshev_t", "chebyshev_u",
           "gcl_dugumleri", "fct_katsayilari", "askin_beyani",
           "nqs_beyani", "nqs_metni",
           "TurGenligi", "turun_genligi", "tur_beyani", "tur_metni"]


@dataclass
class NqsAyari:

    dugum: int = 64
    derece: int = 12
    tohum: int = 0
    havuz_bayti: int = 4
    havuz_haddi: int = 1 << 20


_ASKIN = {"cos": 0, "arccos": 0, "sin": 0, "exp": 0}


def askin_beyani() -> Dict[str, int]:
    return dict(_ASKIN)


def chebyshev_t(u: np.ndarray, derece: int) -> np.ndarray:
    aci = np.arccos(np.clip(np.asarray(u, float), -1.0, 1.0))
    _ASKIN["arccos"] += 1
    j = np.arange(int(derece) + 1, dtype=float)
    _ASKIN["cos"] += 1
    return np.cos(j.reshape((-1,) + (1,) * aci.ndim) * aci[None, ...])


def chebyshev_u(u: np.ndarray, derece: int) -> np.ndarray:
    aci = np.arccos(np.clip(np.asarray(u, float), -1.0, 1.0))
    _ASKIN["arccos"] += 1
    j = np.arange(int(derece) + 1, dtype=float)
    pay = np.sin((j.reshape((-1,) + (1,) * aci.ndim) + 1.0)
                 * aci[None, ...])
    payda = np.sin(aci)[None, ...]
    _ASKIN["sin"] += 2
    tekil = np.abs(payda) < 1e-12
    bol = np.divide(pay, np.where(tekil, 1.0, payda))
    sinir = (j.reshape((-1,) + (1,) * aci.ndim) + 1.0) * np.where(
        np.cos(aci)[None, ...] >= 0.0, 1.0,
        (-1.0) ** j.reshape((-1,) + (1,) * aci.ndim))
    _ASKIN["cos"] += 1
    return np.where(tekil, sinir, bol)


def gcl_dugumleri(kac: int) -> np.ndarray:
    n = max(2, int(kac))
    j = np.arange(n, dtype=float)
    return np.cos(math.pi * j / (n - 1))


def fct_katsayilari(deger: np.ndarray, derece: int) -> np.ndarray:
    y = np.asarray(deger, float).reshape(-1)
    n = y.size
    u = gcl_dugumleri(n)
    T = chebyshev_t(u, int(derece))
    w = np.full(n, 2.0)
    w[0] = w[-1] = 1.0
    pay = (T * (y * w)[None, :]).sum(axis=1)
    payda = (T * T * w[None, :]).sum(axis=1)
    return pay / np.maximum(payda, 1e-300)


class ChebyshevKan:

    def __init__(self, taban: int, qudit: int,
                 ayar: Optional[NqsAyari] = None) -> None:
        self.ayar = ayar or NqsAyari()
        self.taban = max(2, int(taban))
        self.qudit = max(int(qudit), int(self.ayar.havuz_haddi))
        K = int(self.ayar.dugum)
        D = int(self.ayar.derece)
        r = np.random.default_rng(int(self.ayar.tohum))
        self.C = r.normal(scale=1.0 / math.sqrt(D + 1), size=(K, D + 1))
        self.S = r.normal(scale=1.0 / math.sqrt(D + 1), size=(K, D + 1))
        self.havuz_koordinat = r.normal(scale=1.0, size=self.qudit)
        assert self.havuz_koordinat.size == self.qudit, (
            "tohum havuzu qudit sayısınca olmalı (ferman 2-T)")
        self.havuz_fazi = r.uniform(-1.0, 1.0, size=K)
        self._son_z = 1.0
        self._cagri = 0
        self._asikin = 0

    @property
    def katsayi_adedi(self) -> int:
        return int(self.C.size + self.S.size)

    @property
    def parametre_adedi(self) -> int:
        return int(self.katsayi_adedi + self.havuz_koordinat.size
                   + self.havuz_fazi.size)

    def havuzu_buyut(self, n: int) -> None:
        n = int(n)
        if n <= self.havuz_koordinat.size:
            return
        r = np.random.default_rng(int(self.ayar.tohum) + 1)
        ek = r.normal(scale=1.0, size=n - self.havuz_koordinat.size)
        self.havuz_koordinat = np.concatenate([self.havuz_koordinat, ek])
        self.qudit = int(self.havuz_koordinat.size)

    def _vecih(self, basamak: np.ndarray) -> np.ndarray:
        b = np.asarray(basamak, np.int64)
        x = 2.0 * (b.astype(float) / float(self.taban - 1)) - 1.0
        n = x.shape[-1]
        self.havuzu_buyut(n)
        c = self.havuz_koordinat[:n]
        iz = (x * c[None, :]).sum(axis=-1) / float(n)
        u = iz[..., None] + self.havuz_fazi[None, :]
        return np.clip(u, -1.0, 1.0)

    def genlik(self, basamak: np.ndarray, parametre=None,
               yerel_faz=None) -> np.ndarray:
        u = self._vecih(basamak)
        D = int(self.ayar.derece)
        T = chebyshev_t(u, D)
        U = chebyshev_u(u, D)
        reel = np.einsum("kj,jnk->n", self.C, T, optimize=True)
        sanal = np.einsum("kj,jnk->n", self.S, U, optimize=True)
        if parametre is not None:
            k = parametre.kenet(basamak)
            reel = reel - np.asarray(k["enerji"], float).reshape(-1)
            sanal = sanal + np.asarray(k["faz"], float).reshape(-1)
        if yerel_faz is not None:
            y = np.asarray(yerel_faz, float).reshape(-1)
            assert y.size == sanal.size, (
                "mahallî yazmacın fazı konfigürasyon sayısınca olmalı: "
                "%d ≠ %d (ferman 2-Ş)" % (y.size, sanal.size))
            sanal = sanal + y
        reel = reel - float(reel.max())
        self._cagri += 1
        self._asikin += 2
        psi = np.exp(reel + 1j * sanal)
        _ASKIN["exp"] += 2
        z = float(np.linalg.norm(psi))
        self._son_z = z
        assert z > 0.0 and np.isfinite(z), (
            "NQS genliği tamamen söndü (Z=%r): kapalı form bir durum "
            "üretemedi, sessizce geçilemez (ferman 5)" % (z,))
        return psi / z

    def vektor(self) -> np.ndarray:
        return np.concatenate([self.C.reshape(-1), self.S.reshape(-1),
                               self.havuz_koordinat, self.havuz_fazi])

    def yukle(self, v: np.ndarray) -> None:
        v = np.asarray(v, float).reshape(-1)
        assert v.size == self.parametre_adedi, (
            "NQS parametre vektörü katsayı+havuz ebadında olmalı: "
            "%d ≠ %d" % (v.size, self.parametre_adedi))
        n1 = self.C.size
        n2 = n1 + self.S.size
        n3 = n2 + self.havuz_koordinat.size
        self.C = v[:n1].reshape(self.C.shape).copy()
        self.S = v[n1:n2].reshape(self.S.shape).copy()
        self.havuz_koordinat = v[n2:n3].copy()
        self.havuz_fazi = v[n3:].copy()

    def hazineye(self) -> Dict[str, np.ndarray]:
        return {"nqs.C": self.C.copy(), "nqs.S": self.S.copy(),
                "nqs.havuz_koordinat": self.havuz_koordinat.copy(),
                "nqs.havuz_fazı": self.havuz_fazi.copy()}

    def hazineden(self, agirlik) -> bool:
        if not agirlik:
            return False
        C = agirlik.get("nqs.C")
        S = agirlik.get("nqs.S")
        k = agirlik.get("nqs.havuz_koordinat")
        f = agirlik.get("nqs.havuz_fazı")
        if C is None or S is None or k is None or f is None:
            return False
        C = np.asarray(C, float)
        S = np.asarray(S, float)
        if C.shape != self.C.shape or S.shape != self.S.shape:
            return False
        self.C, self.S = C.copy(), S.copy()
        self.havuz_koordinat = np.asarray(k, float).reshape(-1).copy()
        self.havuz_fazi = np.asarray(f, float).reshape(-1).copy()
        return True

    def beyan(self) -> Dict[str, Any]:
        kat_bayt = self.katsayi_adedi * 8
        havuz_bayt = self.qudit * int(self.ayar.havuz_bayti)
        return {"düğüm": int(self.ayar.dugum),
                "derece": int(self.ayar.derece),
                "katsayı": int(self.katsayi_adedi),
                "katsayı_bayt": int(kat_bayt),
                "qudit": int(self.qudit),
                "havuz_bayt": int(havuz_bayt),
                "parametre": int(self.parametre_adedi),
                "çağrı": int(self._cagri),
                "aşkın_çağrı": int(self._asikin),
                "son_Z": float(self._son_z),
                "aşkın_döküm": askin_beyani(),
                "taban": int(self.taban)}


_TUR: Dict[str, float] = {
    "tur": 0.0, "kan_çağrısı": 0.0, "son_kan": 0.0, "konfigürasyon": 0.0,
    "kenetsiz": 0.0, "mahallîsiz": 0.0, "saniye": 0.0, "açık": 1.0}


@dataclass
class TurGenligi:

    hal: np.ndarray
    lif: Tuple[int, ...]
    yazmac: Any = None
    yigin_hali: Optional[np.ndarray] = None

    @property
    def yigin(self) -> np.ndarray:
        if self.yigin_hali is not None:
            return np.asarray(self.yigin_hali, complex)
        return np.asarray(self.hal, complex).reshape(1, -1)

    def sektor_araliklari(self):
        y = self.yazmac
        assert y is not None, (
            "sektör aralıkları yazmaçtan okunur; ikinci bir cetvel "
            "kurulmaz (ferman 1-M, 2-İ)")
        return [y.sektor(ad) for ad, _ in y.ayar.kulli_alanlar]


def turun_genligi(nefs, q=None) -> TurGenligi:
    import time as _t
    t0 = _t.perf_counter()
    kaynak = q if q is not None else nefs
    hal = getattr(kaynak, "_tur_genligi", None)
    assert hal is not None, (
        "İNTÂC KOŞMADAN TURUN GENLİĞİ İSTENDİ (ferman 2-A): silsile "
        "hazırlık → evrim → intâc → ölçümdür; KAN'ı burada ikinci defa "
        "çağırmak çift başlılıktır (ferman 1-M).")
    kan = getattr(nefs, "kan", None)
    assert kan is not None, (
        "TURUN GENLİĞİ KAN'DAN GELİR (ferman 2-T): ``nefs.kan`` yok.")
    y = getattr(q, "y", None) if q is not None else getattr(nefs, "y", None)
    assert y is not None, (
        "turun genliği yazmacın lif yapısını ister -- yazmaç yok")
    simdiki = int(getattr(kan, "_cagri", 0))
    _TUR["kan_çağrısı"] = float(simdiki - _TUR["son_kan"])
    _TUR["son_kan"] = float(simdiki)
    if getattr(nefs, "pq", None) is None:
        _TUR["kenetsiz"] += 1.0
    if getattr(nefs, "mahalli", None) is None:
        _TUR["mahallîsiz"] += 1.0
    H = np.asarray(hal, complex)
    H = H if H.ndim == 2 else H.reshape(1, -1)
    _TUR["tur"] += 1.0
    _TUR["konfigürasyon"] = float(H.shape[-1])
    _TUR["saniye"] += _t.perf_counter() - t0
    return TurGenligi(hal=H[0], lif=tuple(int(x) for x in y.ayar.lif),
                      yazmac=y, yigin_hali=H)


def tur_beyani() -> Dict[str, Any]:
    b = dict(_TUR)
    b["tur_başına_kan"] = int(b["kan_çağrısı"])
    return b


def tur_metni(b: Optional[Dict[str, Any]] = None) -> str:
    d = dict(b or tur_beyani())
    if not int(d.get("tur", 0)):
        return ("  TURUN GENLİĞİ: HİÇ ÜRETİLMEDİ -- kırmızı (ferman 2-A)")
    return "\n".join([
        "  TURUN GENLİĞİ -- KAN İLK VE SON DEFA (ferman 2-A, 2-T)",
        "    tur %d   TUR BAŞINA KAN ÇAĞRISI %d  (bir olmalı)"
        % (int(d["tur"]), int(d["tur_başına_kan"])),
        "    konfigürasyon %d   %.4f sn"
        % (int(d["konfigürasyon"]), float(d["saniye"])),
        "    TEK ÜRETİCİ İNTÂCTIR (ferman 1-M, 2-A): bu uzuv KAN'ı",
        "    çağırmaz, intâcın neticesini okur. Sayı KAN'ın kendi",
        "    sayacından gelir; iki çağrı olsa KIRMIZI yanar.",
        "    kenetsiz tur %d   mahallî fazsız tur %d  (ikisi de 0 olmalı)"
        % (int(d["kenetsiz"]), int(d["mahallîsiz"])),
    ])


def nqs_beyani(kan: Optional[ChebyshevKan]) -> Dict[str, Any]:
    if kan is None:
        return {"düğüm": 0, "derece": 0, "katsayı": 0, "qudit": 0,
                "parametre": 0, "katsayı_bayt": 0, "havuz_bayt": 0,
                "çağrı": 0, "aşkın_çağrı": 0, "son_Z": 0.0,
                "hüküm": "KAN-NQS KURULMADI"}
    return kan.beyan()


def nqs_metni(b: Optional[Dict[str, Any]] = None) -> str:
    d = dict(b or nqs_beyani(None))
    if "hüküm" in d:
        return "  KAN-NQS: %s" % d["hüküm"]
    return "\n".join([
        "  KAN-NQS GENLİĞİ (ferman 2-T: genlik açık dizi değil fonksiyon)",
        "    düğüm × derece : %d × %d   → %d katsayı   = %.1f KB"
        % (d["düğüm"], d["derece"], d["katsayı"],
           d["katsayı_bayt"] / 1e3),
        "    tohum havuzu   : %d qudit   = %.1f MB   (qudit başına 4 bayt)"
        % (d["qudit"], d["havuz_bayt"] / 1e6),
        "    parametre      : %d   (katsayı + havuz)" % d["parametre"],
        "    MERTEBE: genlik ÜRETİMİ O(1) -- katsayı adedi qudit"
        " sayısından bağımsızdır;",
        "    HAVUZ ise O(N)'dir. Toptan O(1) denmez (ferman 5).",
        "    T_j = cos(j·arccos u), U_j = sin((j+1)·arccos u)/sin(arccos u)",
        "    HAKİKÎ FONKSİYONLARIYLA hesaplanır; tekrarlama ikamesi"
        " YASAKTIR (ferman 2-U).",
        "    Aşkın çağrı dökümü: %s   (yasak kalktı, muhasebe kalkmadı)"
        % (d.get("aşkın_döküm", {}),),
        "    son Z (normalize edilen küme üstünde) : %.6e" % d["son_Z"],
        "    AÇIK DİZİ YOKTUR: q^N genlik hiçbir yerde tutulmaz.",
    ])
# ==== BİTTİ: kuantum/nqs.py ====

# ==== BAŞLIYOR: kuantum/parametre_yazmaci.py ====
from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

import numpy as np

__all__ = ["ParametreAyari", "ParametreYazmaci", "qudit_haddi",
           "parametre_beyani", "parametre_metni",
           "kenet_beyani", "kenet_metni"]


_KENET: Dict[str, float] = {"çağrı": 0.0, "kapısız_çağrı": 0.0,
                            "kapı": 0.0, "seyirci": 0.0,
                            "enerji": 0.0, "faz": 0.0,
                            "gerilim": 0.0, "gerilim_tepesi": 0.0,
                            "ayrı_rezonans": 0.0, "açık": 1.0,
                            "açı_kanadı": 0.0}


def kenet_beyani() -> Dict[str, float]:
    b = dict(_KENET)
    b["kapı_başına_enerji"] = (b["enerji"] / b["kapı"]) if b["kapı"] else 0.0
    b["seyirci_nispeti"] = ((b["seyirci"] / (b["seyirci"] + b["kapı"]))
                            if (b["seyirci"] + b["kapı"]) else 0.0)
    return b


def kenet_metni(b: Optional[Dict[str, float]] = None) -> str:
    d = dict(b or kenet_beyani())
    return "\n".join([
        "  ÇİFT YAZMAÇ KENETLENMESİ (ferman 2-V: seyirci qudit)",
        "    kenetleme çağrısı  : %d   kapısız %d   (açık: %s)"
        % (int(d["çağrı"]), int(d["kapısız_çağrı"]),
           "evet" if d["açık"] else "HAYIR -- kırmızı"),
        "    temas eden kapı    : %d   seyirci qudit %d   (%.4f seyirci)"
        % (int(d["kapı"]), int(d["seyirci"]), d["seyirci_nispeti"]),
        "    etkileşim enerjisi : %.6e   (kapı başına %.6e)"
        % (d["enerji"], d["kapı_başına_enerji"]),
        "    eklenen sürekli faz: %.6e   rad   (Z_m DEĞİL, U(1))"
        % d["faz"],
        "    REZONANS EŞLEMESİ (ferman 2-Z: bağlam basamağı lağvedildi)",
        "      ölçülen gerilim ortalaması %.6e   tepesi %.6e"
        % (d["gerilim"], d["gerilim_tepesi"]),
        "      kapıların kilitlendiği ayrı rezonans noktası: %d"
        % int(d["ayrı_rezonans"]),
        "      hedef elle yazılmadı: veri manifoldunun kendi geriliminin",
        "      tepesidir; her kodlamada yeniden tayin edilir.",
        "    Parametre veriyi matrisle ezmez: köşegen kontrollü faz",
        "    üsse skaler girer, yığın ekseni açılmaz (yığın boyu 1).",
    ])


@dataclass
class ParametreAyari:

    tohum: int = 0
    pay: float = 0.25
    qudit: int = 1 << 20
    qudit_bayti: int = 16


def qudit_haddi(bellek: Optional[int], pay: float = 0.25,
                qudit_bayti: int = 16) -> int:
    assert bellek is not None and int(bellek) > 0, (
        "qudit haddi ölçülen bellekten türer; bellek yoklanamadıysa "
        "bütçe uydurulmaz (ferman 5-B, 2-S)")
    return max(1, int((float(bellek) * float(pay))
                      // float(int(qudit_bayti))))


class ParametreYazmaci:

    def __init__(self, taban: int, yigin: int, bellek: Optional[int],
                 ayar: Optional[ParametreAyari] = None) -> None:
        self.ayar = ayar or ParametreAyari()
        self.taban = max(2, int(taban) if int(taban) >= 2 else 64)
        self.yigin = max(1, int(yigin))
        self.bellek = None if bellek is None else int(bellek)
        self.hadd = qudit_haddi(self.bellek, float(self.ayar.pay),
                                int(self.ayar.qudit_bayti))
        self.d = min(int(self.ayar.qudit), int(self.hadd))
        assert self.d >= 1, (
            "parametre yazmacına tek qudit bile sığmadı: ölçülen bellek "
            "%r, pay %.2f (ferman 2-S)" % (self.bellek, self.ayar.pay))
        r = np.random.default_rng(int(self.ayar.tohum))
        self.genlik = np.abs(r.normal(scale=1.0, size=self.d))
        self.genlik = self.genlik / max(float(np.linalg.norm(self.genlik)),
                                        1e-300)
        self.faz = r.uniform(-math.pi, math.pi, size=self.d)
        self._yer: Dict[str, Tuple[int, int]] = {}
        self._bas = 0

    @property
    def qudit(self) -> int:
        return int(self.d)

    @property
    def mahalli_serbestlik(self) -> int:
        return 2 * int(self.d)

    @property
    def genislik(self) -> int:
        return 1

    def __len__(self) -> int:
        return int(self.mahalli_serbestlik)

    def al(self, anahtar: str, n: int) -> np.ndarray:
        return self.aci(anahtar, int(n), 1.0)

    def buyukluk(self, anahtar: str, n: int) -> np.ndarray:
        return self.genlik[self.adres(anahtar, int(n))]

    def aci_adresi(self, anahtar: str, n: int) -> np.ndarray:
        return int(self.d) + self.adres(anahtar, int(n))

    def aci_katsayisi(self) -> float:
        return 1.0

    def adres(self, anahtar: str, n: int) -> np.ndarray:
        n = max(1, int(n))
        if anahtar not in self._yer:
            assert self._bas + n <= self.d, (
                "parametre yazmacı doldu: %r %d seviye istiyor, %d "
                "seviyeden %d kullanıldı. Çare daraltmak değil yazmacı "
                "büyütmektir (ferman 2-S)."
                % (anahtar, n, self.d, self._bas))
            self._yer[anahtar] = (self._bas, n)
            self._bas += n
        bas, kac = self._yer[anahtar]
        return bas + (np.arange(n, dtype=np.int64) % int(kac))

    def aci(self, anahtar: str, n: int, olcek: float = 1.0) -> np.ndarray:
        return float(olcek) * self.faz[self.adres(anahtar, n)]

    def temas_kapilari(self) -> Tuple[np.ndarray, np.ndarray]:
        if not self._yer:
            return (np.zeros(0, np.int64), np.zeros(0, float))
        kontrol = np.concatenate(
            [bas + np.arange(int(kac), dtype=np.int64)
             for (bas, kac) in self._yer.values()])
        _KENET["açı_kanadı"] = 1.0
        return kontrol, self.faz[kontrol]

    def temas_agirligi(self, kontrol: np.ndarray) -> np.ndarray:
        k = np.asarray(kontrol, np.int64).reshape(-1)
        return self.genlik[k] if k.size else np.zeros(0, float)

    @staticmethod
    def gerilim(koordinat: np.ndarray) -> np.ndarray:
        k = np.asarray(koordinat, float)
        ileri = np.abs(np.diff(k, axis=-1, append=k[..., -1:]))
        geri = np.abs(np.diff(k, axis=-1, prepend=k[..., :1]))
        return ileri + geri

    def rezonans(self, koordinat: np.ndarray, kac: int) -> np.ndarray:
        k = np.asarray(koordinat, float)
        n = int(k.shape[-1])
        g = self.gerilim(k)
        sira = np.argsort(-g, axis=-1)
        return sira[..., np.arange(int(kac)) % n]

    def kenet(self, basamak: np.ndarray) -> Dict[str, np.ndarray]:
        b = np.asarray(basamak, np.int64)
        n = int(b.shape[-1])
        kontrol, bag = self.temas_kapilari()
        if kontrol.size == 0 or not _KENET["açık"]:
            sifir = np.zeros(b.shape[:-1], float)
            _KENET["çağrı"] += 1.0
            if kontrol.size == 0:
                _KENET["kapısız_çağrı"] += 1.0
            return {"enerji": sifir, "faz": sifir}
        w = 2.0 * (b.astype(float) / float(max(1, self.taban - 1))) - 1.0
        duz = w.reshape(-1, n)
        gerilim = self.gerilim(duz)
        hedef = self.rezonans(duz, int(kontrol.size))
        w_t = np.take_along_axis(duz, hedef, axis=-1)
        teta = self.faz[kontrol]
        enerji = (-(w_t * (bag * teta)).sum(axis=-1)).reshape(b.shape[:-1])
        faz = ((w_t * teta).sum(axis=-1)).reshape(b.shape[:-1])
        _KENET["çağrı"] += 1.0
        _KENET["kapı"] = float(kontrol.size)
        _KENET["seyirci"] = float(max(0, self.d - kontrol.size))
        _KENET["enerji"] = float(np.mean(np.abs(enerji)))
        _KENET["faz"] = float(np.mean(np.abs(faz)))
        _KENET["gerilim"] = float(np.mean(gerilim))
        _KENET["gerilim_tepesi"] = float(np.max(gerilim))
        _KENET["ayrı_rezonans"] = float(np.unique(hedef).size)
        return {"enerji": np.asarray(enerji, float),
                "faz": np.asarray(faz, float)}

    def defter(self) -> Dict[str, Tuple[int, int]]:
        return dict(self._yer)

    def vektor(self) -> np.ndarray:
        return np.concatenate([self.genlik, self.faz])

    def yukle(self, v: np.ndarray) -> None:
        v = np.asarray(v, float).reshape(-1)
        assert v.size == 2 * self.d, (
            "parametre vektörü yazmaç ebadında olmalı: %d ≠ 2·%d"
            % (v.size, self.d))
        g = np.abs(v[:self.d])
        self.genlik = g / max(float(np.linalg.norm(g)), 1e-300)
        self.faz = np.remainder(v[self.d:] + math.pi,
                                2.0 * math.pi) - math.pi

    def hazineye(self) -> Dict[str, np.ndarray]:
        return {"parametre.genlik": self.genlik.copy(),
                "parametre.faz": self.faz.copy()}

    def hazineden(self, agirlik) -> bool:
        g = None if agirlik is None else agirlik.get("parametre.genlik")
        f = None if agirlik is None else agirlik.get("parametre.faz")
        if g is None or f is None:
            return False
        g = np.asarray(g, float).reshape(-1)
        f = np.asarray(f, float).reshape(-1)
        if g.size != self.d or f.size != self.d:
            return False
        self.genlik = g / max(float(np.linalg.norm(g)), 1e-300)
        self.faz = np.remainder(f + math.pi, 2.0 * math.pi) - math.pi
        return True

    def beyan(self) -> Dict[str, Any]:
        return {"qudit": int(self.d),
                "taban": int(self.taban),
                "mahallî_serbestlik": int(self.mahalli_serbestlik),
                "tahsis_edilen_qudit": int(self._bas),
                "defter": len(self._yer),
                "yığın": int(self.yigin),
                "qudit_bayt": int(self.d * int(self.ayar.qudit_bayti)),
                "qudit_haddi": int(self.hadd),
                "ölçülen_bellek": (0 if self.bellek is None
                                   else int(self.bellek)),
                "pay": float(self.ayar.pay)}


def parametre_beyani(p: Optional[ParametreYazmaci]) -> Dict[str, Any]:
    if p is None:
        return {"qudit": 0, "taban": 0,
                "mahallî_serbestlik": 0, "ölçülen_bellek": 0,
                "tahsis_edilen_qudit": 0, "qudit_haddi": 0,
                "defter": 0, "hüküm": "PARAMETRE YAZMACI KURULMADI"}
    return p.beyan()


def parametre_metni(b: Optional[Dict[str, Any]] = None) -> str:
    d = dict(b or parametre_beyani(None))
    if "hüküm" in d:
        return "  PARAMETRE YAZMACI: %s" % d["hüküm"]
    return "\n".join([
        "  PARAMETRE YAZMACI  %d qudit × taban %d   (kapasite %d^%d)"
        % (d["qudit"], d["taban"], d["taban"], d["qudit"]),
        "    mahallî serbestlik %d   tahsis %d qudit / %d kayıt"
        % (d["mahallî_serbestlik"], d["tahsis_edilen_qudit"],
           d["defter"]),
        "    mahallî bellek %.1f MB   ölçülen bellek %.1f MB   hadd %d"
        % (d["qudit_bayt"] / 1e6, d["ölçülen_bellek"] / 1e6,
           d["qudit_haddi"]),
    ])
# ==== BİTTİ: kuantum/parametre_yazmaci.py ====

# ==== BAŞLIYOR: kuantum/qcekirdek.py ====
from __future__ import annotations

import ctypes
import hashlib
import os
import subprocess
import tempfile
from typing import Any, Dict, List, Optional, Tuple

import numpy as np

__all__ = ["CekirdekAyari", "CEKIRDEK_C", "HAT_TIPI", "derle", "yoklama",
           "kutuphane",
           "Bant", "cekirdek_beyani", "rapor"]


KARO, CIFT, MATCHGATE = 0, 1, 2

HAT_TIPI = np.complex128

CEKIRDEK_C = r'''
/* MUCİT-AI -- KAPI BANDI ÇEKİRDEĞİ.
 * Durum ayrıştırılmış gerçek/sanal iki dizidir; bütün kapılar aynı
 * geçişte, aynı tamponlar üstünde koşar. Tahsis YOKTUR. */
#include <stddef.h>
#include <stdint.h>
#include <string.h>
#if defined(__AVX512F__)
#include <immintrin.h>
#endif

typedef struct {
    int32_t tip;      /* 0 = karo, 1 = cift            */
    int32_t a;        /* karo: on   | cift: bi (2^pi)  */
    int32_t b;        /* karo: n    | cift: bj (2^pj)  */
    int32_t c;        /* karo: ard  | cift: -          */
    int64_t ofset;    /* dizey tamponundaki başlangıç  */
} Kapi;

/* ---- KARO: (N, n, ard) bloğuna n×n dizey ---------------------- */
static void karo_vur(double *re, double *im, size_t B,
                     int on, int n, int ard,
                     const double *Mre, const double *Mim,
                     double *tre, double *tim)
{
    size_t blok = (size_t)B * (size_t)on;
    size_t adim = (size_t)n * (size_t)ard;
    for (size_t g = 0; g < blok; g++) {
        double *xr = re + g * adim, *xi = im + g * adim;
        /* Netice geçici tampona yazılır: kaynak okunmadan bozulmasın. */
        for (int i = 0; i < n; i++) {
            double *ar = tre + (size_t)i * ard, *ai = tim + (size_t)i * ard;
            for (int t = 0; t < ard; t++) { ar[t] = 0.0; ai[t] = 0.0; }
            for (int j = 0; j < n; j++) {
                const double mr = Mre[(size_t)i * n + j];
                const double mi = Mim[(size_t)i * n + j];
                const double *br = xr + (size_t)j * ard;
                const double *bi = xi + (size_t)j * ard;
                int t = 0;
#if defined(__AVX512F__)
                __m512d vmr = _mm512_set1_pd(mr), vmi = _mm512_set1_pd(mi);
                for (; t + 8 <= ard; t += 8) {
                    __m512d br8 = _mm512_loadu_pd(br + t);
                    __m512d bi8 = _mm512_loadu_pd(bi + t);
                    __m512d ar8 = _mm512_loadu_pd(ar + t);
                    __m512d ai8 = _mm512_loadu_pd(ai + t);
                    ar8 = _mm512_fmadd_pd(vmr, br8, ar8);
                    ar8 = _mm512_fnmadd_pd(vmi, bi8, ar8);
                    ai8 = _mm512_fmadd_pd(vmr, bi8, ai8);
                    ai8 = _mm512_fmadd_pd(vmi, br8, ai8);
                    _mm512_storeu_pd(ar + t, ar8);
                    _mm512_storeu_pd(ai + t, ai8);
                }
#endif
                for (; t < ard; t++) {
                    ar[t] += mr * br[t] - mi * bi[t];
                    ai[t] += mr * bi[t] + mi * br[t];
                }
            }
        }
        memcpy(xr, tre, adim * sizeof(double));
        memcpy(xi, tim, adim * sizeof(double));
    }
}

/* ---- ÇİFT: iki bit düzlemine 4×4 dizey, İÇ İÇE düzende --------
 *
 * **AYRIŞTIRMA YOK.** Çift kapı zaten dört ayrı adrese gider; iç içe
 * ``(re,im)`` düzeninde de aynı dörtlüdür. Ayrıştırmak durumu iki
 * kere daha dolaşmak olurdu ve kazanç yerine kayıp verirdi. */
static void cift_ic(double *psi, size_t B, size_t d,
                    int64_t bi, int64_t bj,
                    const double *Gre, const double *Gim)
{
    int64_t lo = bi < bj ? bi : bj;
    int64_t hi = bi < bj ? bj : bi;
    int64_t s[4];
    s[0] = 0; s[1] = bj; s[2] = bi; s[3] = bi + bj;
    for (size_t bt = 0; bt < B; bt++) {
        double *P = psi + bt * 2 * d;
        for (int64_t h = 0; h < (int64_t)d; h += 2 * hi) {
            for (int64_t l = 0; l < hi; l += 2 * lo) {
                for (int64_t t = 0; t < lo; t++) {
                    int64_t x = h + l + t;
                    double vr[4], vi[4];
                    for (int k = 0; k < 4; k++) {
                        vr[k] = P[2 * (x + s[k])];
                        vi[k] = P[2 * (x + s[k]) + 1];
                    }
                    for (int a = 0; a < 4; a++) {
                        double ar = 0.0, ai = 0.0;
                        for (int b = 0; b < 4; b++) {
                            const double gr = Gre[a * 4 + b];
                            const double gi = Gim[a * 4 + b];
                            ar += gr * vr[b] - gi * vi[b];
                            ai += gr * vi[b] + gi * vr[b];
                        }
                        P[2 * (x + s[a])] = ar;
                        P[2 * (x + s[a]) + 1] = ai;
                    }
                }
            }
        }
    }
}

/* ---- MATCHGATE: parite bloğunda, YARIM ÇARPIM ------------------
 *
 * Valiant-Terhal: ``G(A,B)`` pariteyi korur; ``A`` çift pariteli
 * ``{0,3}``, ``B`` tek pariteli ``{1,2}`` altuzayında ayrı döner.
 * Umumî 4×4'te öbek başına 16 karmaşık çarpım vardır; burada 8. */
static void cift_mg(double *psi, size_t B, size_t d,
                    int64_t bi, int64_t bj,
                    const double *Gre, const double *Gim)
{
    int64_t lo = bi < bj ? bi : bj;
    int64_t hi = bi < bj ? bj : bi;
    int64_t s[4];
    s[0] = 0; s[1] = bj; s[2] = bi; s[3] = bi + bj;
    /* A = G[{0,3}×{0,3}] , B = G[{1,2}×{1,2}] */
    const int ci[2] = {0, 3}, ti[2] = {1, 2};
    for (size_t bt = 0; bt < B; bt++) {
        double *P = psi + bt * 2 * d;
        for (int64_t h = 0; h < (int64_t)d; h += 2 * hi) {
            for (int64_t l = 0; l < hi; l += 2 * lo) {
                for (int64_t t = 0; t < lo; t++) {
                    int64_t x = h + l + t;
                    for (int blok = 0; blok < 2; blok++) {
                        const int *ix = blok ? ti : ci;
                        double vr[2], vi[2];
                        for (int k = 0; k < 2; k++) {
                            vr[k] = P[2 * (x + s[ix[k]])];
                            vi[k] = P[2 * (x + s[ix[k]]) + 1];
                        }
                        for (int a = 0; a < 2; a++) {
                            double ar = 0.0, ai = 0.0;
                            for (int b = 0; b < 2; b++) {
                                const double gr = Gre[ix[a] * 4 + ix[b]];
                                const double gi = Gim[ix[a] * 4 + ix[b]];
                                ar += gr * vr[b] - gi * vi[b];
                                ai += gr * vi[b] + gi * vr[b];
                            }
                            P[2 * (x + s[ix[a]])] = ar;
                            P[2 * (x + s[ix[a]]) + 1] = ai;
                        }
                    }
                }
            }
        }
    }
}

/* Çift kapı bandı: ardışık bütün çift kapılar TEK çağrıda.
 * ``tip == 2`` ise matchgate yolu (yarım çarpım). */
void mucit_cift_bant(double *psi, size_t B, size_t d,
                     const Kapi *bant, size_t kapi_sayisi,
                     const double *dre, const double *dim)
{
    for (size_t k = 0; k < kapi_sayisi; k++) {
        const Kapi *g = &bant[k];
        if (g->tip == 2)
            cift_mg(psi, B, d, (int64_t)g->a, (int64_t)g->b,
                    dre + g->ofset, dim + g->ofset);
        else
            cift_ic(psi, B, d, (int64_t)g->a, (int64_t)g->b,
                    dre + g->ofset, dim + g->ofset);
    }
}

/* ---- ÇİFT (ayrıştırılmış düzen) -- kıyas için duruyor ---------- */
static void cift_vur(double *re, double *im, size_t B, size_t d,
                     int64_t bi, int64_t bj,
                     const double *Gre, const double *Gim)
{
    int64_t lo = bi < bj ? bi : bj;
    int64_t hi = bi < bj ? bj : bi;
    /* Taban sırası: a = 2*bit_i + bit_j (uzak_cift ile bir). */
    int64_t s[4];
    s[0] = 0; s[1] = bj; s[2] = bi; s[3] = bi + bj;
    for (size_t bt = 0; bt < B; bt++) {
        double *R = re + bt * d, *I = im + bt * d;
        for (int64_t h = 0; h < (int64_t)d; h += 2 * hi) {
            for (int64_t l = 0; l < hi; l += 2 * lo) {
                for (int64_t t = 0; t < lo; t++) {
                    int64_t x = h + l + t;
                    double vr[4], vi[4];
                    for (int k = 0; k < 4; k++) {
                        vr[k] = R[x + s[k]];
                        vi[k] = I[x + s[k]];
                    }
                    for (int a = 0; a < 4; a++) {
                        double ar = 0.0, ai = 0.0;
                        for (int b = 0; b < 4; b++) {
                            const double gr = Gre[a * 4 + b];
                            const double gi = Gim[a * 4 + b];
                            ar += gr * vr[b] - gi * vi[b];
                            ai += gr * vi[b] + gi * vr[b];
                        }
                        R[x + s[a]] = ar;
                        I[x + s[a]] = ai;
                    }
                }
            }
        }
    }
}

/* ---- BANT: bütün kapılar TEK çağrıda -------------------------- */
void mucit_bant(double *re, double *im, size_t B, size_t d,
                const Kapi *bant, size_t kapi_sayisi,
                const double *dre, const double *dim,
                double *tre, double *tim)
{
    for (size_t k = 0; k < kapi_sayisi; k++) {
        const Kapi *g = &bant[k];
        if (g->tip == 0) {
            karo_vur(re, im, B, g->a, g->b, g->c,
                     dre + g->ofset, dim + g->ofset, tre, tim);
        } else {
            cift_vur(re, im, B, d, (int64_t)g->a, (int64_t)g->b,
                     dre + g->ofset, dim + g->ofset);
        }
    }
}

/* ---- AYRIŞTIR / BİRLEŞTİR: iç içe complex128 <-> iki reel dizi -- */
void mucit_ayristir(const double *psi, double *re, double *im, size_t n)
{
    size_t i = 0;
#if defined(__AVX512F__)
    const __m512i IDXR = _mm512_setr_epi64(0, 2, 4, 6, 8, 10, 12, 14);
    const __m512i IDXI = _mm512_setr_epi64(1, 3, 5, 7, 9, 11, 13, 15);
    for (; i + 8 <= n; i += 8) {
        __m512d a = _mm512_loadu_pd(psi + 2 * i);
        __m512d b = _mm512_loadu_pd(psi + 2 * i + 8);
        _mm512_storeu_pd(re + i, _mm512_permutex2var_pd(a, IDXR, b));
        _mm512_storeu_pd(im + i, _mm512_permutex2var_pd(a, IDXI, b));
    }
#endif
    for (; i < n; i++) { re[i] = psi[2 * i]; im[i] = psi[2 * i + 1]; }
}

void mucit_birlestir(double *psi, const double *re, const double *im,
                     size_t n)
{
    size_t i = 0;
#if defined(__AVX512F__)
    const __m512i LO = _mm512_setr_epi64(0, 8, 1, 9, 2, 10, 3, 11);
    const __m512i HI = _mm512_setr_epi64(4, 12, 5, 13, 6, 14, 7, 15);
    for (; i + 8 <= n; i += 8) {
        __m512d r = _mm512_loadu_pd(re + i);
        __m512d m = _mm512_loadu_pd(im + i);
        _mm512_storeu_pd(psi + 2 * i, _mm512_permutex2var_pd(r, LO, m));
        _mm512_storeu_pd(psi + 2 * i + 8, _mm512_permutex2var_pd(r, HI, m));
    }
#endif
    for (; i < n; i++) { psi[2 * i] = re[i]; psi[2 * i + 1] = im[i]; }
}
'''

from nefs.derleyici import DERLEME_DIZINI, ORTAK_BAYRAK

BAYRAK = ORTAK_BAYRAK + ["-mavx512f", "-mavx512bw", "-mavx512vl",
                         "-mfma", "-funroll-loops"]

_ONBELLEK: Dict[str, Any] = {}
_SAYAC: Dict[str, int] = {"kapı": 0, "boşaltma": 0, "karo": 0, "çift": 0,
                          "numpy_boşaltma": 0}


class CekirdekAyari:

    __slots__ = ("hat", "bant")

    def __init__(self, hat: str = "c", bant: int = 0) -> None:
        self.hat = str(hat)
        self.bant = int(bant)


def _ozet() -> str:
    from nefs.derleyici import ozet
    return ozet(CEKIRDEK_C, BAYRAK)


def derle() -> Dict[str, Any]:
    from nefs.derleyici import derle as _derle
    return _derle("qcekirdek", CEKIRDEK_C, BAYRAK)


class _Kapi(ctypes.Structure):
    _fields_ = [("tip", ctypes.c_int32), ("a", ctypes.c_int32),
                ("b", ctypes.c_int32), ("c", ctypes.c_int32),
                ("ofset", ctypes.c_int64)]


def kutuphane():
    if "lib" in _ONBELLEK:
        return _ONBELLEK["lib"]
    d = derle()
    lib = None
    if d["derlendi"] and os.path.exists(d["so"]):
        lib = ctypes.CDLL(d["so"])
        dp = ctypes.POINTER(ctypes.c_double)
        lib.mucit_bant.argtypes = [dp, dp, ctypes.c_size_t, ctypes.c_size_t,
                                   ctypes.POINTER(_Kapi), ctypes.c_size_t,
                                   dp, dp, dp, dp]
        lib.mucit_bant.restype = None
        lib.mucit_cift_bant.argtypes = [dp, ctypes.c_size_t, ctypes.c_size_t,
                                        ctypes.POINTER(_Kapi),
                                        ctypes.c_size_t, dp, dp]
        lib.mucit_cift_bant.restype = None
        lib.mucit_ayristir.argtypes = [dp, dp, dp, ctypes.c_size_t]
        lib.mucit_ayristir.restype = None
        lib.mucit_birlestir.argtypes = [dp, dp, dp, ctypes.c_size_t]
        lib.mucit_birlestir.restype = None
    _ONBELLEK["lib"] = lib
    return lib


def yoklama() -> Dict[str, Any]:
    c = _ONBELLEK.get("yoklama")
    if c is not None:
        return c
    d = derle()
    o = {"derlendi": bool(d["derlendi"]), "bayrak": d.get("bayrak"),
         "derleyici": d.get("derleyici")}
    if not d["derlendi"]:
        o.update({"koşuyor": False,
                  "sebep": (d.get("derleyici_çıktısı") or "derlenemedi")[:200]})
        _ONBELLEK["yoklama"] = o
        return o
    _kopya = dict(_SAYAC)
    try:
        B, d_ = 2, 16
        r = np.random.default_rng(0)
        psi = (r.normal(size=(B, d_)) + 1j * r.normal(size=(B, d_)))
        M = np.eye(4, dtype=complex)
        b = Bant(B, d_, (4, 4))
        b.karo(0, M)
        v = psi.copy()
        b.bosalt(v)
        o["koşuyor"] = bool(np.max(np.abs(v - psi)) < 1e-12)
        o["sebep"] = "tamam" if o["koşuyor"] else "kimlik kapısı durumu bozdu"
    except Exception as e:
        o.update({"koşuyor": False, "sebep": "%s: %s"
                  % (type(e).__name__, e)})
    _SAYAC.clear()
    _SAYAC.update(_kopya)
    _ONBELLEK["yoklama"] = o
    return o


class Bant:

    __slots__ = ("B", "d", "lif", "bant", "hat", "_kapi", "_dizey",
                 "_re", "_im", "_tre", "_tim", "_tampon")

    def __init__(self, B: int, d: int, lif: Tuple[int, ...],
                 hat: str = "c", bant: int = 0) -> None:
        self.B = int(B)
        self.d = int(d)
        self.lif = tuple(int(x) for x in lif)
        self.hat = str(hat)
        self.bant = int(bant) if int(bant) > 0 else 256
        self._kapi: List[Tuple[int, int, int, int, int]] = []
        self._dizey: List[np.ndarray] = []
        n = self.B * self.d
        self._re = np.zeros(n, np.float64)
        self._im = np.zeros(n, np.float64)
        enb = max(self.lif) if self.lif else 1
        enb_ard = self.d // enb if enb else 1
        self._tre = np.zeros(enb * max(1, enb_ard), np.float64)
        self._tim = np.zeros(enb * max(1, enb_ard), np.float64)
        self._tampon = None

    def _bolum(self, k: int) -> Tuple[int, int]:
        on, ard = 1, 1
        for x in self.lif[:k]:
            on *= int(x)
        for x in self.lif[k + 1:]:
            ard *= int(x)
        return on, ard

    def karo(self, k: int, M) -> None:
        n = int(self.lif[int(k)])
        on, ard = self._bolum(int(k))
        A = np.ascontiguousarray(np.asarray(M, complex).reshape(n, n))
        self._kapi.append((KARO, on, n, ard, len(self._dizey)))
        self._dizey.append(A.reshape(-1))
        _SAYAC["kapı"] += 1
        _SAYAC["karo"] += 1

    def cift(self, bi: int, bj: int, G) -> None:
        from nefs.matchgate import matchgate_mi
        A = np.ascontiguousarray(np.asarray(G, complex).reshape(4, 4))
        mg = bool(matchgate_mi(A)[0])
        self._kapi.append((MATCHGATE if mg else CIFT,
                           int(bi), int(bj), 0, len(self._dizey)))
        self._dizey.append(A.reshape(-1))
        _SAYAC["kapı"] += 1
        _SAYAC["çift"] += 1
        if mg:
            _SAYAC["matchgate"] = _SAYAC.get("matchgate", 0) + 1

    def dolu(self) -> bool:
        return len(self._kapi) >= self.bant

    def bos_mu(self) -> bool:
        return not self._kapi

    def bosalt(self, psi: np.ndarray) -> None:
        if not self._kapi:
            return
        kapilar, dizeyler = self._kapi, self._dizey
        self._kapi, self._dizey = [], []
        _SAYAC["boşaltma"] += 1
        lib = kutuphane() if self.hat == "c" else None
        if lib is None or not yoklama().get("koşuyor"):
            _SAYAC["numpy_boşaltma"] += 1
            self._numpy_bosalt(psi, kapilar, dizeyler)
            return
        assert psi.dtype == np.complex128, (
            "C hattı complex128 ister, %r verildi" % psi.dtype)
        assert psi.flags["C_CONTIGUOUS"], "durum ardışık olmalı"
        dp = ctypes.POINTER(ctypes.c_double)
        p_psi = psi.view(np.float64).ctypes.data_as(dp)
        i = 0
        n_kapi = len(kapilar)
        while i < n_kapi:
            tip = kapilar[i][0]
            if tip == KARO:
                _, on, n, ard, j = kapilar[i]
                self._karo_blas(psi, on, n, ard, dizeyler[j])
                i += 1
                continue
            j0 = i
            while i < n_kapi and kapilar[i][0] in (CIFT, MATCHGATE):
                i += 1
            oberk = kapilar[j0:i]
            duz = np.concatenate([dizeyler[g[4]] for g in oberk])
            dre = np.ascontiguousarray(duz.real)
            dim = np.ascontiguousarray(duz.imag)
            dizi = (_Kapi * len(oberk))()
            for m, (t, a, b, c, _j) in enumerate(oberk):
                dizi[m] = _Kapi(int(t), int(a), int(b), int(c), 16 * m)
            lib.mucit_cift_bant(p_psi, ctypes.c_size_t(self.B),
                                ctypes.c_size_t(self.d), dizi,
                                ctypes.c_size_t(len(oberk)),
                                dre.ctypes.data_as(dp),
                                dim.ctypes.data_as(dp))
            _SAYAC["cift_bant"] = _SAYAC.get("cift_bant", 0) + 1

    def _karo_blas(self, psi, on: int, n: int, ard: int, M) -> None:
        Mx = np.asarray(M).reshape(n, n)
        X = psi.reshape(self.B * on, n, ard)
        if ard == 1:
            Y = X.reshape(-1, n) @ Mx.T
        else:
            Y = np.matmul(Mx, X)
        psi[...] = Y.reshape(self.B, self.d)

    def _numpy_bosalt(self, psi, kapilar, dizeyler) -> None:
        B, d = self.B, self.d
        for tip, a, b, c, j in kapilar:
            M = dizeyler[j]
            if tip == KARO:
                on, n, ard = a, b, c
                X = psi.reshape(B * on, n, ard)
                Mx = M.reshape(n, n)
                if ard == 1:
                    Y = X.reshape(-1, n) @ Mx.T
                else:
                    Y = np.matmul(Mx, X)
                psi[...] = Y.reshape(B, d)
            else:
                bi, bj = a, b
                G = M.reshape(4, 4)
                idx = np.arange(d)
                taban = idx[((idx & bi) == 0) & ((idx & bj) == 0)]
                s = (0, bj, bi, bi + bj)
                V = np.stack([psi[:, taban + k] for k in s], axis=0)
                Y = np.einsum('ab,bxy->axy', G, V)
                for k in range(4):
                    psi[:, taban + s[k]] = Y[k]


def cekirdek_beyani() -> Dict[str, Any]:
    y = yoklama()
    kapi = int(_SAYAC["kapı"])
    bos = int(_SAYAC["boşaltma"])
    return {
        "hat": "c" if y.get("koşuyor") else "numpy",
        "derlendi": bool(y.get("derlendi")),
        "koşuyor": bool(y.get("koşuyor")),
        "sebep": y.get("sebep"),
        "kapı": kapi, "karo": int(_SAYAC["karo"]),
        "çift": int(_SAYAC["çift"]),
        "boşaltma": bos,
        "numpy_boşaltma": int(_SAYAC["numpy_boşaltma"]),
        "bant": 256,
        "matchgate": int(_SAYAC.get("matchgate", 0)),
        "cift_bant": int(_SAYAC.get("cift_bant", 0)),
        "bant_basina_kapi": (float(kapi) / max(1, bos)) if kapi else 0.0,
        "kıyas": ("kapı yok" if not kapi else
                  "%d kapı %d boşaltmada; ardışık çift kapılar %d C "
                  "çağrısında toplandı"
                  % (kapi, bos, int(_SAYAC.get("cift_bant", 0)))),
    }


def rapor(tohum: int = 0) -> str:
    import time
    r = np.random.default_rng(int(tohum))
    B, lif = 128, (16, 16, 16)
    d = int(np.prod(lif))
    psi0 = (r.normal(size=(B, d)) + 1j * r.normal(size=(B, d)))
    psi0 /= np.linalg.norm(psi0, axis=1, keepdims=True)

    def uni(n):
        M = r.normal(size=(n, n)) + 1j * r.normal(size=(n, n))
        q, _ = np.linalg.qr(M)
        return q

    prog = []
    for _ in range(120):
        if r.random() < 0.75:
            k = int(r.integers(0, 3))
            prog.append(("karo", k, uni(lif[k])))
        else:
            p = r.choice(12, size=2, replace=False)
            prog.append(("cift", int(1 << p[0]), int(1 << p[1]), uni(4)))

    def kos(hat):
        b = Bant(B, d, lif, hat=hat)
        v = np.ascontiguousarray(psi0.copy())
        for g in prog:
            if g[0] == "karo":
                b.karo(g[1], g[2])
            else:
                b.cift(g[1], g[2], g[3])
        t0 = time.perf_counter()
        b.bosalt(v)
        return v, time.perf_counter() - t0

    vc, tc = kos("c")
    vn, tn = kos("numpy")
    y = yoklama()
    _, tc = kos("c")
    _, tn = kos("numpy")
    fark = float(np.max(np.abs(vc - vn)))
    norm = float(np.max(np.abs(np.sum(np.abs(vc) ** 2, axis=1) - 1.0)))
    return "\n".join([
        "=== KAPI BANDI ÇEKİRDEĞİ ===", "",
        "  derlendi: %s   koşuyor: %s   (%s)"
        % (y["derlendi"], y["koşuyor"], y["sebep"]),
        "  bayrak  : %s" % y.get("bayrak"),
        "",
        "  B=%d  d=%d  lif=%s  kapı=%d  (karo %d, çift %d)"
        % (B, d, lif, len(prog),
           sum(1 for g in prog if g[0] == "karo"),
           sum(1 for g in prog if g[0] == "cift")),
        "",
        "  C hattı    : %.6f sn" % tc,
        "  numpy hattı: %.6f sn" % tn,
        "  → %.2f× %s" % (tn / max(tc, 1e-12),
                          "hızlı" if tc < tn else "YAVAŞ (ölçü kırmızı)"),
        "",
        "  İKİ HAT BİREBİR AYNI MI: azamî fark %.3e" % fark,
        "  üniterlik (norm hatası)  : %.3e" % norm,
        "",
        "  Gönderim: karo → BLAS (kapı başına 1 zgemm), ardışık çift",
        "  kapıları → tek C çağrısı. Sıra harfiyyen korunur.",
    ])
# ==== BİTTİ: kuantum/qcekirdek.py ====

# ==== BAŞLIYOR: kuantum/qegitim.py ====
from __future__ import annotations

import time
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np

from nefs.musahede import gorev_dizisi, gorevleri_getir
from ogrenme.optimize import as_gek_adimi, ayrik_mertebede_sicra

from nefs import melekeler as mertebe
from nefs.melekeler import QNefs
from nefs.zihin_durumu import QAyar, QYazmac

__all__ = ["ornekler", "ornek_bol", "belirtecleri_kodla",
           "adayin_tuttugu",
           "egit", "degerlendir"]


def ornek_bol(o) -> Tuple[List[int], int, str, int]:
    if len(o) >= 4:
        return list(o[0]), int(o[1]), str(o[2]), int(o[3])
    if len(o) == 3:
        return list(o[0]), int(o[1]), str(o[2]), -1
    return list(o[0]), int(o[1]), "sözlü", -1


def belirtecleri_kodla(belirtecler: Sequence[int], kubit: int = 4,
                       sozluk: int = 16, usul: str = "kategorik"
                       ) -> np.ndarray:
    if usul in ("sürekli", "lie"):
        from matematik.sonsuz_mertebeler_teorisi import kodla, KIP_TUTARLI, KIP_LIE
        ne = KIP_TUTARLI if usul == "sürekli" else KIP_LIE
        X = np.atleast_2d(np.asarray(belirtecler, float))
        cikti = [np.asarray(kodla(x, ne=ne, boyut=int(sozluk))).reshape(-1)
                 for x in X]
        g = max(c.size for c in cikti)
        return np.stack([np.pad(np.real(c), (0, g - c.size)) for c in cikti])
    if usul != "kategorik":
        raise ValueError("kodlama usulü bilinmiyor: %r" % (usul,))

    taban = int(kubit) if int(kubit) >= 2 else int(sozluk)
    t = np.asarray(belirtecler, int).reshape(-1)
    out = np.zeros((t.size, taban))
    dolu = t >= 0
    out[np.arange(t.size)[dolu], t[dolu] % taban] = 1.0
    return out


def ornekler(gorevler: Sequence, azami: int = 24, pencere: int = 8,
             sozluk: int = 0, tohum: int = 0, taban: int = 16,
             basamak: int = 0) -> List[Tuple[List[int], int, str, int]]:
    from nefs.belirtec import basamak_sayisi, tip_vektoru
    from nefs.musahede import soyutlama_oku
    from nefs.belirtec import belirtecle

    rng = np.random.default_rng(tohum)
    tb = max(2, int(taban))
    bs = int(basamak) if int(basamak) > 0 else basamak_sayisi(
        int(sozluk) if int(sozluk) > 0 else tb, tb)
    P = max(1, int(pencere))
    cikti: List[Tuple[List[int], int, str, int]] = []

    def _zorla(bag_bas, hed_bas, cins: str) -> None:
        akis = list(bag_bas)
        for i, h in enumerate(hed_bas):
            pen = akis[-P:]
            cikti.append(([int(x) for x in pen], int(h), cins, int(i % bs)))
            akis.append(int(h))

    for g in gorevler:
        dizi, hedef = gorev_dizisi(g, hedef_indis=0)
        assert len(dizi) > 0, "görev %r BOŞ dizi verdi" % getattr(g, "ad", "")
        bag_bas = tip_vektoru(list(dizi), tb, bs)
        hed_bas = tip_vektoru(list(hedef), tb, bs)
        _zorla(bag_bas, hed_bas, "arc")
        soz = soyutlama_oku(getattr(g, "ad", "") or "")
        if soz:
            soz_bas = tip_vektoru(belirtecle(soz), tb, bs)
            _zorla(bag_bas, soz_bas, "arc_sözlü")
        if len(cikti) >= azami:
            break
    if len(cikti) > int(azami):
        se = rng.choice(len(cikti), size=int(azami), replace=False)
        cikti = [cikti[int(i)] for i in sorted(se)]
    return cikti


def adayin_tuttugu(nefs: QNefs, veri: Sequence[Tuple[List[int], int]],
                   p: Optional[np.ndarray] = None, sozluk: int = 16,
                   lam_mizan: float = 0.25, lam_top: float = 0.1,
                   ne: str = "uygunluk", o=None,
                   cevap_isteniyor: bool = True, baglam=None):
    def kos(bag):
        E = belirtecleri_kodla(bag, nefs.ayar.veri_lifi,
                               nefs.ayar.veri_lifi)
        q = nefs.idrak_et(E)
        return q.beyan(0), q.olcumler()

    def mizan(olc, ister=True):
        ceza = 0.0
        ceza += 1.0 * float(olc.get("tenakuz", 0.0))
        ceza += 1.0 * float(olc.get("nakz", 0.0))
        ceza += 1.0 * (1.0 - float(olc.get("tasdik", 0.0)))
        if ister:
            ceza += 0.5 * float(olc.get("sukut", 0.0))
        ceza += 0.5 * float(olc.get("P_Şek", 0.0))
        return ceza

    if ne == "koş":
        return kos(baglam)
    if ne == "mizan":
        return mizan(o, cevap_isteniyor)
    if ne not in ("uygunluk", "hedef", "ikisi"):
        raise ValueError("aday ölçüsünün kipi bilinmiyor: %r" % (ne,))

    if p is not None:
        nefs.yukle(p)
    if not len(veri):
        return (0.0, 0.0) if ne == "ikisi" else 0.0

    top = 0.0
    ceza = 0.0
    hedef_top = 0.0
    for bag, hedef, _cins, _makam in (ornek_bol(o) for o in veri):
        P, olc = kos(bag)
        top -= float(np.log(P[hedef % len(P)] + 1e-12))
        ceza += lam_mizan * mizan(olc)
        ceza -= lam_top * float(olc.get("entropi", 0.0))
        y = np.zeros_like(P)
        y[hedef % len(P)] = 1.0
        hedef_top += float(np.sum((P - y) ** 2))
    V = (top + ceza) / len(veri)
    H = hedef_top / len(veri)
    if ne == "uygunluk":
        return V
    if ne == "hedef":
        return H
    return V, H


def egit(nefs: QNefs, veri: Sequence[Tuple[List[int], int]],
         cevrim: int = 4, r: int = 2, n_ornek: int = 8, izgara: int = 16,
         sozluk: int = 16, ayrik: bool = True, lam_hedef: float = 0.5,
         gama_azami: float = 0.3, tohum: int = 0,
         gunluk: Optional[List[str]] = None) -> Dict[str, object]:
    adayin_tuttugu(nefs, (), sozluk=sozluk, ne="koş", baglam=[0] * 4)
    p = nefs.vektor()
    V0 = adayin_tuttugu(nefs, veri, p, sozluk)
    kayit: List[float] = [V0]
    t0 = time.perf_counter()
    D = tuple(mertebe.DINAMIK)
    gama = 0.0
    tunel: List[float] = []

    for c in range(cevrim):
        _, o = adayin_tuttugu(nefs, (), sozluk=sozluk, ne="koş", baglam=veri[0][0])
        tikanik = float(o.get("tenakuz", 0.0))
        sikisti = c > 0 and kayit[-1] >= kayit[-2] - 1e-9
        if sikisti and tikanik > 0.5:
            gama = min(gama_azami, gama + 0.1)
        elif not sikisti:
            gama = 0.0
        tunel.append(gama)
        if gama > 0.0:
            p = p + gama * np.random.default_rng(tohum + 100 + c).normal(
                scale=0.3, size=len(p))

        p_yeni, tani = as_gek_adimi(
            lambda q: adayin_tuttugu(nefs, veri, q, sozluk), p,
            yaricap=0.5, r=r, izgara=izgara, n_ornek=n_ornek,
            hedef_ceza=lambda q: adayin_tuttugu(nefs, veri[:3], q, sozluk, ne="hedef"),
            lam_hedef=lam_hedef, tohum=tohum + c)
        V_yeni = adayin_tuttugu(nefs, veri, p_yeni, sozluk)
        if V_yeni < kayit[-1]:
            p, V = p_yeni, V_yeni
        else:
            V = kayit[-1]
        kayit.append(V)
        nefs.yukle(p)

        if ayrik:
            _, o = adayin_tuttugu(nefs, (), sozluk=sozluk, ne="koş", baglam=veri[0][0])
            tik = {m: float(o.get("tenakuz", 0.0)) * (1.0 + i * 0.05)
                   for i, m in enumerate(D)}
            adres = ayrik_mertebede_sicra(tikaniklik=tik, mevcut=D, ne="adres")
            aday = list(D)
            aday[int(np.argmax([tik[m] for m in aday]))] = adres

            def E_ayrik(vek: Tuple[int, ...]) -> float:
                mertebe.DINAMIK = tuple(vek)
                return adayin_tuttugu(nefs, veri[:2], p, sozluk)

            D_yeni, _ = ayrik_mertebede_sicra(enerji=E_ayrik, D0=aday, adim=6,
                                        tohum=tohum + c)
            mertebe.DINAMIK = tuple(D_yeni)
            D = tuple(D_yeni)

        if gunluk is not None:
            gunluk.append("çevrim %d: V=%.4f  aktif_özdeğer=%.3f  Γ=%.2f  "
                          "hedef_ceza=%.3f  D=%s"
                          % (c, V, tani["özdeğer_oranı"], gama,
                             tani.get("hedef_cezası", float("nan")),
                             list(D)[:4]))

    nefs.yukle(p)
    return {"V_ilk": V0, "V_son": kayit[-1], "seyir": kayit,
            "süre_sn": time.perf_counter() - t0, "dinamik": D,
            "parametre": len(nefs), "tünel": tunel,
            "tünel_açıldı": float(sum(1 for g in tunel if g > 0.0))}


def _degerlendir_mudrike(nefs, gorevler: Sequence, azami: int,
                         derinlik: int) -> Dict[str, object]:
    from nefs.kulli_kayip import suz as _mudrike

    deneme = cozulen = konusan = yanlis = sukut = 0
    hucre: List[float] = []
    sebepler: Dict[str, int] = {}
    for g in gorevler:
        if deneme >= azami:
            break
        if not getattr(g, "sinama", None) or not getattr(g, "egitim", None):
            continue
        deneme += 1
        r = _mudrike(g, derinlik=derinlik, dalga=True, nefs=nefs)
        if r["sükût"]:
            sukut += 1
            sebepler[r["sebep"]] = sebepler.get(r["sebep"], 0) + 1
            hucre.append(0.0)
            continue
        konusan += 1
        tam = True
        oran = []
        for (a, b), c in zip(g.sinama, r["cevap"]):
            if c is None or c.shape != b.shape:
                tam = False
                oran.append(0.0)
                continue
            e = float(np.mean(c == b))
            oran.append(e)
            if e < 1.0:
                tam = False
        hucre.append(float(np.mean(oran)) if oran else 0.0)
        cozulen += tam
        yanlis += (not tam)
    return {"deneme": deneme, "tam_çözülen": cozulen,
            "konuşan": konusan, "yanlış_cevap": yanlis,
            "sükût": sukut, "atlanan_uzun": 0,
            "sükût_sebepleri": sebepler,
            "ilk_belirteç_isabeti": cozulen,
            "isabet_konuşunca": (cozulen / konusan) if konusan else 0.0,
            "ortalama_hücre_isabeti":
                float(np.mean(hucre)) if hucre else 0.0}


def degerlendir(nefs: QNefs, gorevler: Sequence, azami: int = 8,
                pencere: int = 8, sozluk: int = 16,
                azami_uret: int = 0, mudrike_ile: bool = False,
                derinlik: int = 2) -> Dict[str, object]:
    from nefs.belirtec import basamak_sayisi as _basamak, tip_vektoru as _tip

    if mudrike_ile:
        return _degerlendir_mudrike(nefs, gorevler, azami, derinlik)
    cozulen = isabet = deneme = atlanan = 0
    hucre: List[float] = []
    sukut_sayisi = 0
    for g in gorevler:
        if deneme >= azami:
            break
        dizi, hedef = gorev_dizisi(g, hedef_indis=0)
        assert len(hedef) > 0, "görev %r BOŞ hedef verdi" % getattr(g, "ad", "")
        deneme += 1
        tb = int(nefs.ayar.veri_lifi)
        bs = _basamak(sozluk, tb)
        baglam = [int(x) for x in _tip(dizi, tb, bs)]
        h = [int(x) for x in _tip(hedef, tb, bs)]
        if 0 < azami_uret < len(h):
            atlanan += 1
            deneme -= 1
            continue
        from nefs.soyle import _uret
        uretilen, _bedel, _sukutlar, _budanan = _uret(
            nefs, baglam, int(pencere), int(tb))
        duz = 1.0 / float(tb)
        kesinlik = float(np.clip(
            (float(np.exp(-_bedel / max(len(uretilen), 1))) - duz)
            / max(1.0 - duz, 1e-300), 0.0, 1.0))
        if (float(np.mean(_sukutlar)) if _sukutlar else 1.0) > kesinlik:
            sukut_sayisi += 1
        n = min(len(h), len(uretilen))
        dogru = sum(1 for i in range(n) if h[i] == uretilen[i])
        hucre.append(dogru / max(n, 1))
        if uretilen[:len(h)] == h:
            cozulen += 1
        if n and uretilen[0] == h[0]:
            isabet += 1
    return {"deneme": deneme, "tam_çözülen": cozulen,
            "atlanan_uzun": atlanan,
            "ölçüt_boş": bool(deneme == 0),
            "ilk_belirteç_isabeti": isabet, "sükût": sukut_sayisi,
            "ortalama_hücre_isabeti":
                float(np.mean(hucre)) if hucre else 0.0}
# ==== BİTTİ: kuantum/qegitim.py ====

# ==== BAŞLIYOR: kuantum/qudit.py ====
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional, Sequence, Tuple

import numpy as np

__all__ = ["QuditAyari", "agirlik", "durum", "durum_yigin", "suz", "dallanma",
           "metrik", "dogal_adim", "blok", "ortusme", "kronecker",
           "TddAyari", "kanonik_adres", "esit_mi", "rapor",
           "cartan_seviye_fazlari"]


def cartan_seviye_fazlari(theta_cartan: float, d: int, B: int = 1) -> np.ndarray:
    seviye_fazi = theta_cartan * np.arange(d, dtype=float) / float(max(1, d))
    return np.tile(seviye_fazi[None, :], (max(1, int(B)), 1))


@dataclass
class QuditAyari:

    d: int = 4096
    kan: int = 4
    derece: int = 8
    qsvt: int = 16
    yon: int = 8
    duzenli: float = 1e-6
    tip: object = np.float64
    tohum: int = 0

    @property
    def katsayi_sayisi(self) -> int:
        return 2 * int(self.kan) * (int(self.derece) + 1) + int(self.yon)


def agirlik(d: int, teta: Optional[np.ndarray] = None) -> np.ndarray:
    d = int(d)
    if d < 2:
        raise ValueError("qudit seviyesi en az 2 olmalı, %d verildi" % d)
    if teta is None:
        teta = np.ones(min(8, d - 1), float)
    teta = np.asarray(teta, float).reshape(-1)
    r = teta.size
    if not 1 <= r <= d - 1:
        raise ValueError("Cartan yönü 1…d−1 arası olmalı, %d verildi" % r)

    kuyruk = np.zeros(d + 1)
    kuyruk[:r] = teta
    kuyruk = np.cumsum(kuyruk[::-1])[::-1]
    m = np.arange(d)
    w = kuyruk[m].copy()
    ic = m[1:] <= r
    w[1:][ic] -= m[1:][ic] * teta[m[1:][ic] - 1]
    enb = float(np.max(np.abs(w)))
    return w / enb if enb > 1e-300 else w


def _cheb(u: np.ndarray, derece: int, ikinci: bool = False) -> np.ndarray:
    u = np.asarray(u, float).reshape(-1)
    n = int(derece) + 1
    out = np.empty((n, u.size), float)
    out[0] = 1.0
    if n > 1:
        out[1] = (2.0 * u) if ikinci else u
    for j in range(2, n):
        out[j] = 2.0 * u * out[j - 1] - out[j - 2]
    return out


def durum(c: np.ndarray, s: np.ndarray, teta: Optional[np.ndarray] = None,
          d: int = 0, ayar: Optional[QuditAyari] = None) -> np.ndarray:
    a = ayar or QuditAyari()
    d = int(d or a.d)
    c = np.asarray(c, float)
    s = np.asarray(s, float)
    if c.shape != s.shape:
        raise ValueError("c ve s aynı şekilde olmalı: %s vs %s"
                         % (c.shape, s.shape))
    K, n = c.shape
    w = agirlik(d, teta)
    T = _cheb(w, n - 1, ikinci=False)
    U = _cheb(w, n - 1, ikinci=True)
    reel = (c @ T).sum(axis=0)
    sanal = (s @ U).sum(axis=0)
    reel = reel - float(np.max(reel))
    psi = np.exp(reel) * np.exp(1j * sanal)
    nrm = float(np.linalg.norm(psi))
    return psi / nrm if nrm > 1e-300 else psi


def _bicimle(xp, x):
    if xp is np:
        return np.asarray(x)
    if hasattr(xp, "asarray"):
        return xp.asarray(x)
    return xp.tensor(x)


def kronecker(psi, A, B, C, xp=None) -> np.ndarray:
    xp = xp or np
    a = _bicimle(xp, A)
    b = _bicimle(xp, B)
    c = _bicimle(xp, C)
    na, nb, nc = a.shape[0], b.shape[0], c.shape[0]
    P = _bicimle(xp, psi)
    tek = (P.ndim == 1)
    if tek:
        P = P.reshape(1, -1)
    Bn = P.shape[0]
    T = P.reshape(Bn, na, nb, nc)
    T = xp.einsum("bijk,xi->bxjk", T, a)
    T = xp.einsum("bxjk,yj->bxyk", T, b)
    T = xp.einsum("bxyk,zk->bxyz", T, c)
    out = T.reshape(Bn, na * nb * nc)
    return out.reshape(-1) if tek else out


_LIE_CHEBYSHEV_CUDA = r"""
extern "C" __global__
void lie_chebyshev_fused(
        const float* __restrict__ W,      // (B, d) Cartan ağırlıkları
        const float* __restrict__ cs,     // (n,)   T-serisi katsayıları
        const float* __restrict__ ss,     // (n,)   U-serisi katsayıları
        float2* __restrict__ out,         // (B, d) netice
        const int B, const int d, const int n)
{
    extern __shared__ float sm[];         // SRAM: d float
    const int b = blockIdx.x;
    if (b >= B) return;

    // --- durumu SRAM'e bir kere çek
    for (int i = threadIdx.x; i < d; i += blockDim.x)
        sm[i] = W[b * d + i];
    __syncthreads();

    for (int i = threadIdx.x; i < d; i += blockDim.x) {
        const float x = sm[i];
        const float ikix = 2.0f * x;

        // Clenshaw -- T serisi
        float b1 = 0.0f, b2 = 0.0f, t;
        for (int j = n - 1; j >= 1; --j) { t = cs[j] + ikix * b1 - b2; b2 = b1; b1 = t; }
        const float reel = cs[0] + x * b1 - b2;

        // Clenshaw -- U serisi (kapanış farklı: a0 + 2x b1 - b2)
        b1 = 0.0f; b2 = 0.0f;
        for (int j = n - 1; j >= 1; --j) { t = ss[j] + ikix * b1 - b2; b2 = b1; b1 = t; }
        const float sanal = ss[0] + ikix * b1 - b2;

        const float e = __expf(reel);
        out[b * d + i] = make_float2(e * __cosf(sanal), e * __sinf(sanal));
    }
}
"""


def _gpu_lie_chebyshev(W: np.ndarray, cs: np.ndarray, ss: np.ndarray,
                       ne: str = "oto"):
    W = np.asarray(W, np.float32)
    cs = np.asarray(cs, np.float32).reshape(-1)
    ss = np.asarray(ss, np.float32).reshape(-1)
    B, d = W.shape
    n = cs.size

    if ne in ("oto", "cupy"):
        try:
            import cupy as cp
            mod = cp.RawModule(code=_LIE_CHEBYSHEV_CUDA,
                               options=("-use_fast_math",))
            fn = mod.get_function("lie_chebyshev_fused")
            Wg = cp.asarray(W)
            csg, ssg = cp.asarray(cs), cp.asarray(ss)
            out = cp.empty((B, d), cp.complex64)
            iplik = min(256, max(32, d))
            fn((B,), (iplik,),
               (Wg, csg, ssg, out, np.int32(B), np.int32(d), np.int32(n)),
               shared_mem=4 * d)
            return out
        except Exception:
            if ne == "cupy":
                raise

    if ne in ("oto", "torch"):
        try:
            import torch
            aygit = "cuda" if torch.cuda.is_available() else "cpu"
            Wt = torch.as_tensor(W, device=aygit)
            cst = torch.as_tensor(cs, device=aygit)
            sst = torch.as_tensor(ss, device=aygit)
            ikix = 2.0 * Wt
            b1 = torch.zeros_like(Wt); b2 = torch.zeros_like(Wt)
            for j in range(n - 1, 0, -1):
                b1, b2 = cst[j] + ikix * b1 - b2, b1
            reel = cst[0] + Wt * b1 - b2
            b1 = torch.zeros_like(Wt); b2 = torch.zeros_like(Wt)
            for j in range(n - 1, 0, -1):
                b1, b2 = sst[j] + ikix * b1 - b2, b1
            sanal = sst[0] + ikix * b1 - b2
            e = torch.exp(reel - reel.amax(dim=1, keepdim=True))
            psi = torch.complex(e * torch.cos(sanal), e * torch.sin(sanal))
            psi = psi / torch.linalg.vector_norm(psi, dim=1, keepdim=True)
            return psi
        except Exception:
            if ne == "torch":
                raise

    return None


def durum_yigin(c: np.ndarray, s: np.ndarray, TETA: np.ndarray,
                d: int = 0, ayar: Optional[QuditAyari] = None,
                tip=None, cekirdek: str = "numpy",
                cartan_acisi: Optional[float] = None) -> np.ndarray:
    a = ayar or QuditAyari()
    d = int(d or a.d)
    if cekirdek != "numpy":
        W0 = np.atleast_2d(np.asarray(TETA, np.float32))
        Wg = np.stack([agirlik(d, W0[i]) for i in range(W0.shape[0])])
        cs0 = np.asarray(c, float).sum(axis=0)
        ss0 = np.asarray(s, float).sum(axis=0)
        psi_gpu = _gpu_lie_chebyshev(Wg, cs0, ss0, ne=cekirdek)
        if psi_gpu is not None:
            return psi_gpu
    tip = np.dtype(tip or getattr(a, "tip", np.float64))
    ctip = np.complex64 if tip == np.float32 else np.complex128
    c = np.asarray(c, tip)
    s = np.asarray(s, tip)
    TETA = np.atleast_2d(np.asarray(TETA, tip))
    B, rr = TETA.shape
    K, n = c.shape

    kuy = np.zeros((B, d + 1), tip)
    kuy[:, :rr] = TETA
    kuy = np.cumsum(kuy[:, ::-1], axis=1)[:, ::-1]
    m = np.arange(d)
    W = kuy[:, m].copy()
    ic = m[1:] <= rr
    W[:, 1:][:, ic] -= (m[1:][ic] * TETA[:, m[1:][ic] - 1]).astype(tip)
    enb = np.max(np.abs(W), axis=1, keepdims=True)
    W = W / np.maximum(enb, tip.type(1e-30))

    cs = c.sum(axis=0).astype(tip)
    ss = s.sum(axis=0).astype(tip)
    iki = (2.0 * W).astype(tip)

    b1 = np.zeros_like(W); b2 = np.zeros_like(W)
    for j in range(n - 1, 0, -1):
        b1, b2 = cs[j] + iki * b1 - b2, b1
    reel = cs[0] + W * b1 - b2

    b1 = np.zeros_like(W); b2 = np.zeros_like(W)
    for j in range(n - 1, 0, -1):
        b1, b2 = ss[j] + iki * b1 - b2, b1
    sanal = ss[0] + iki * b1 - b2
    if cartan_acisi is not None:
        sanal = sanal + cartan_seviye_fazlari(float(cartan_acisi), d, B)
    reel = reel - reel.max(axis=1, keepdims=True)
    e = np.exp(reel)
    psi = (e * np.cos(sanal)).astype(ctip)
    psi += 1j * (e * np.sin(sanal)).astype(ctip)
    nrm = np.linalg.norm(psi, axis=1, keepdims=True)
    return psi / np.maximum(nrm, tip.type(1e-30))


def ortusme(a: np.ndarray, b: np.ndarray) -> float:
    a = np.asarray(a).reshape(-1)
    b = np.asarray(b).reshape(-1)
    return float(np.abs(np.vdot(a, b)))


@dataclass
class TddAyari:

    tolerans: float = 1e-9
    cekirdek: int = 16


def kanonik_adres(psi, cekirdek: int = 16,
                  ayar: Optional[TddAyari] = None) -> Dict[str, Any]:
    a = ayar or TddAyari()
    v = np.asarray(psi, complex).reshape(-1)
    assert v.size >= 1, "adres için en az bir genlik lâzım"
    k = max(1, min(int(cekirdek), v.size))
    c = v[:k]
    tol = float(a.tolerans)
    j = int(np.argmax(np.abs(c) > tol)) if np.any(np.abs(c) > tol) else -1
    if j < 0:
        anahtar: Tuple = ("0", k)
    else:
        w = c / c[j]
        basamak = max(1, int(round(-np.log10(max(tol, 1e-15)))))
        anahtar = (k, j) + tuple(np.round(w, basamak).tolist())
    return {"adres": hash(anahtar), "anahtar": anahtar,
            "çekirdek": k, "boy": int(v.size),
            "bayt": int(c.nbytes)}


def esit_mi(a: Dict[str, Any], b: Dict[str, Any]) -> bool:
    return a["adres"] == b["adres"] and a["anahtar"] == b["anahtar"]


def suz(delta, psi: np.ndarray, ayar: Optional[QuditAyari] = None,
        lam_azami: float = 0.0, keskinlik: float = 8.0,
        ne: str = "harmonik") -> np.ndarray:
    a = ayar or QuditAyari()
    N = int(a.qsvt)
    if callable(delta):
        vur = delta
        if lam_azami <= 0:
            raise ValueError("işlev verilince lam_azami açıkça lâzım")
    else:
        D = np.asarray(delta)
        vur = lambda v: D @ v
        if lam_azami <= 0:
            lam_azami = float(np.max(np.sum(np.abs(D), axis=1))) or 1.0

    j = np.arange(N + 1)
    dugum = np.cos(np.pi * (j + 0.5) / (N + 1))
    lam = (dugum + 1.0) * 0.5 * lam_azami
    f = np.exp(-float(keskinlik) * lam / max(lam_azami, 1e-300))
    kat = np.empty(N + 1)
    for k in range(N + 1):
        kat[k] = (2.0 / (N + 1)) * np.sum(
            f * np.cos(np.pi * k * (j + 0.5) / (N + 1)))
    kat[0] *= 0.5
    if ne == "katsayi":
        return kat
    if ne != "harmonik":
        raise ValueError("süzme kipi bilinmiyor: %r" % (ne,))

    def A(v):
        return (2.0 / lam_azami) * vur(v) - v

    v = np.asarray(psi)
    b1 = np.zeros_like(v)
    b2 = np.zeros_like(v)
    for k in range(N, 0, -1):
        b1, b2 = 2.0 * A(b1) - b2 + kat[k] * v, b1
    out = A(b1) - b2 + kat[0] * v
    nrm = float(np.linalg.norm(out))
    return out / nrm if nrm > 1e-300 else out


def dallanma(tepe: Sequence[int], ne: str = "sayim"):
    lam = [int(x) for x in tepe]
    n = len(lam)
    if any(lam[i] < lam[i + 1] for i in range(n - 1)):
        raise ValueError("en yüksek ağırlık azalan olmalı: %r" % (lam,))

    if ne == "weyl":
        pay = payda = 1.0
        for i in range(n):
            for j in range(i + 1, n):
                pay *= (lam[i] - lam[j] + j - i)
                payda *= (j - i)
        return int(round(pay / payda))

    def satirlar(ust: List[int]) -> List[List[int]]:
        k = len(ust) - 1
        if k == 0:
            return [[]]
        out: List[List[int]] = []

        def yur(i: int, kismi: List[int]):
            if i == k:
                out.append(list(kismi))
                return
            for v in range(ust[i + 1], ust[i] + 1):
                kismi.append(v)
                yur(i + 1, kismi)
                kismi.pop()

        yur(0, [])
        return out

    oruntuler: List[List[List[int]]] = []

    def derinlestir(ust: List[int], yigin: List[List[int]]):
        if len(ust) == 1:
            oruntuler.append([list(x) for x in yigin])
            return
        for alt in satirlar(ust):
            derinlestir(alt, yigin + [alt])

    derinlestir(lam, [lam])
    if ne == "sayim":
        return len(oruntuler)
    if ne == "oruntu":
        return oruntuler
    raise ValueError("dallanma kipi bilinmiyor: %r" % (ne,))


def metrik(psi_uret: Callable[[np.ndarray], np.ndarray], teta: np.ndarray,
           h: float = 1e-4) -> np.ndarray:
    teta = np.asarray(teta, float).reshape(-1)
    psi = psi_uret(teta)
    d = teta.size
    dpsi = np.empty((d, psi.size), complex)
    for i in range(d):
        e = np.zeros(d)
        e[i] = h
        dpsi[i] = (psi_uret(teta + e) - psi_uret(teta - e)) / (2.0 * h)
    ic = dpsi.conj() @ dpsi.T
    v = dpsi.conj() @ psi
    return np.real(ic - np.outer(v, v.conj()))


def dogal_adim(g: np.ndarray, grad: np.ndarray, eta: float = 0.1,
               duzenli: float = 1e-6, tur: int = 64) -> np.ndarray:
    g = np.asarray(g, float)
    b = -float(eta) * np.asarray(grad, float).reshape(-1)
    n = b.size
    olcek = float(np.trace(g)) / max(n, 1)
    tau = float(duzenli) * max(olcek, 1e-30)
    A = lambda v: g @ v + tau * v
    x = np.zeros(n)
    r = b - A(x)
    p = r.copy()
    rr = float(r @ r)
    for _ in range(int(tur)):
        if rr < 1e-30:
            break
        Ap = A(p)
        al = rr / max(float(p @ Ap), 1e-300)
        x += al * p
        r -= al * Ap
        rr_yeni = float(r @ r)
        p = r + (rr_yeni / max(rr, 1e-300)) * p
        rr = rr_yeni
    return x


BLOKLAR: Tuple[Tuple[str, int, int], ...] = (
    ("sentaks", 0, 512),
    ("onto-fizik", 512, 2560),
    ("mantık", 2560, 4096),
)


def blok(psi: np.ndarray, ad: Optional[str] = None,
         ne: str = "izdusum") -> object:
    psi = np.asarray(psi).reshape(-1)
    d = psi.size
    olcek = d / float(BLOKLAR[-1][2])
    dilim = {a: (int(b * olcek), min(d, int(c * olcek)))
             for a, b, c in BLOKLAR}
    if ne == "agirlik":
        return {a: float(np.sum(np.abs(psi[i:j]) ** 2))
                for a, (i, j) in dilim.items()}
    if ne == "izdusum":
        if ad not in dilim:
            raise ValueError("blok bilinmiyor: %r" % (ad,))
        i, j = dilim[ad]
        out = np.zeros_like(psi)
        out[i:j] = psi[i:j]
        n = float(np.linalg.norm(out))
        return out / n if n > 1e-300 else out
    raise ValueError("blok kipi bilinmiyor: %r" % (ne,))


def rapor(ayar: Optional[QuditAyari] = None) -> str:
    import time

    a = ayar or QuditAyari()
    r = np.random.default_rng(a.tohum)
    c = r.normal(scale=0.3, size=(a.kan, a.derece + 1))
    s = r.normal(scale=0.3, size=(a.kan, a.derece + 1))
    teta = r.normal(size=a.d - 1)

    s_ = ["=== QUDİT ÇEKİRDEĞİ -- SVD yok, MPS yok, ikili yok ===", ""]

    t0 = time.perf_counter()
    psi = durum(c, s, teta, ayar=a)
    t_durum = time.perf_counter() - t0
    s_ += ["  1. LIE-CHEBYSHEV KAN-QUDIT DURUMU",
           "    d              : %d" % a.d,
           "    saklanan katsayı: %d  (genlik SAKLANMIYOR, üretiliyor)"
           % a.katsayi_sayisi,
           "    açık dizi olsaydı: %d karmaşık sayı (%.1f×)"
           % (a.d, a.d / max(a.katsayi_sayisi, 1)),
           "    üretim süresi  : %.4f ms" % (1e3 * t_durum),
           "    norm           : %.12f" % float(np.linalg.norm(psi)),
           "    faz ±1'e kilitli mi: %s"
           % ("EVET -- KUSUR" if np.allclose(np.abs(np.angle(psi) % np.pi), 0,
                                             atol=1e-9) else "hayır (sürekli)")]

    n = 64
    W = r.random((n, n)); W = (W + W.T) * 0.5
    np.fill_diagonal(W, 0.0)
    D = np.diag(W.sum(axis=1)) - W
    D = D / np.max(np.sum(np.abs(D), axis=1))
    v = r.normal(size=n) + 1j * r.normal(size=n)
    v /= np.linalg.norm(v)
    t0 = time.perf_counter()
    hv = suz(D, v, ayar=a, keskinlik=12.0)
    t_suz = time.perf_counter() - t0
    h = np.ones(n) / np.sqrt(n)
    tam = h * (h @ v)
    tam = tam / max(float(np.linalg.norm(tam)), 1e-300)
    kalinti = float(np.linalg.norm(D @ hv)) / max(
        float(np.linalg.norm(hv)), 1e-300)
    s_ += ["", "  2. QSVT HODGE SÜZGECİ (derece %d)" % a.qsvt,
           "    süre           : %.4f ms" % (1e3 * t_suz),
           "    harmonikle örtüşme: %.6f  (1,0 = tam söndürme)"
           % ortusme(hv, tam),
           "    ‖Δ·süzülmüş‖/‖·‖ : %.3e  (0 = çelişki tamamen söndü)"
           % kalinti,
           "    ayrıştırma kullandı mı: HAYIR (yalnız Δ@v; özayrışım"
           " sadece bu satırın ŞAHİDİ için)"]

    s_ += ["", "  3. GELFAND-TSETLİN DALLANMASI (χ budaması YOK)"]
    for lam in ((2, 1, 0), (3, 1, 0), (2, 2, 1, 0)):
        say = dallanma(lam, ne="sayim")
        wy = dallanma(lam, ne="weyl")
        s_.append("    λ=%-12s örüntü %4d   Weyl %4d   %s"
                  % (str(lam), say, wy,
                     "UYUŞTU" if say == wy else "AYRIŞTI -- KIRMIZI"))

    dk = 12
    tk = r.normal(size=dk) * 0.2

    def uret(t):
        return durum(c, s, np.concatenate([t, np.zeros(a.d - 1 - dk)]),
                     ayar=a)

    t0 = time.perf_counter()
    g = metrik(uret, tk)
    t_met = time.perf_counter() - t0
    grad = r.normal(size=dk)
    adim = dogal_adim(g, grad, eta=0.1, duzenli=a.duzenli)
    duz = -0.1 * grad
    s_ += ["", "  4. FUBINI-STUDY DOĞAL GRADYAN (ters ALINMADI, CG)",
           "    metrik süresi  : %.2f ms  (%d×%d)" % (1e3 * t_met, dk, dk),
           "    g simetrik mi  : %s"
           % ("evet" if np.allclose(g, g.T, atol=1e-8) else "HAYIR"),
           "    ‖doğal adım‖   : %.6f" % float(np.linalg.norm(adim)),
           "    ‖düz adım‖     : %.6f" % float(np.linalg.norm(duz)),
           "    aralarındaki açı: %.1f°"
           % float(np.degrees(np.arccos(np.clip(
               (adim @ duz) / max(np.linalg.norm(adim) * np.linalg.norm(duz),
                                  1e-300), -1, 1)))),
           "    (açı 0 olsaydı metrik hiçbir şey yapmıyor demekti)"]

    s_ += ["", "  HIZ -- eski hat 11 belirteç/sn idi (ölçüldü, ~8500 SVD)"]
    for tip, ad in ((np.float64, "float64"), (np.float32, "float32")):
        for dd, BB in ((16, 4096), (256, 4096), (4096, 256)):
            ay = QuditAyari(d=dd, kan=a.kan, derece=a.derece, yon=a.yon,
                            tip=tip)
            TT = r.normal(size=(BB, a.yon))
            durum_yigin(c, s, TT, ayar=ay)
            t0 = time.perf_counter()
            durum_yigin(c, s, TT, ayar=ay)
            dt = time.perf_counter() - t0
            hiz = BB / max(dt, 1e-12)
            s_.append("    %-8s d=%-5d B=%-5d %10.0f belirteç/sn"
                      "   hedefin %.2f'i   eski hattın %.0f katı"
                      % (ad, dd, BB, hiz, hiz / 1e6, hiz / 11.0))
    s_.append("    (LAPACK çağrısı: SIFIR. SVD yok, QR yok, özayrışım yok.)")

    ag = blok(psi, ne="agirlik")
    s_ += ["", "  BLOKLAR (süperseçim sektörleri)"]
    for k, v_ in ag.items():
        s_.append("    %-12s ağırlık %.6f" % (k, v_))
    return "\n".join(s_)
# ==== BİTTİ: kuantum/qudit.py ====

# ==== BAŞLIYOR: kuantum/qyazmac.py ====
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence, Tuple

import math

import numpy as np

from nefs.matchgate import matchgate_mi

__all__ = ["QuditAyar", "QuditYazmac", "Iz", "KULLI_SEKTOR_TABANI",
           "sektor_beyani", "sektor_metni", "senet_beyani"]

KULLI_SEKTOR_TABANI: int = 64

_SEKTOR_SAYAC: Dict[str, float] = {
    "dönme": 0.0, "faz_vuruşu": 0.0, "kenet": 0.0, "örüntü": 0.0,
    "küllî_faz_yazması": 0.0, "kapı_dizeyi": 0.0,
    "küllî_iç_çarpım": 0.0, "açık": 1.0}


def sektor_beyani() -> Dict[str, float]:
    return dict(_SEKTOR_SAYAC)


def sektor_metni(b=None) -> str:
    d = dict(b or sektor_beyani())
    top = (d["dönme"] + d["faz_vuruşu"] + d["kenet"] + d["örüntü"])
    if not top:
        return ("  SEKTÖR AMELİYELERİ: HİÇ KOŞMADI -- kırmızı "
                "(ferman 2-Ö)")
    return "\n".join([
        "  SEKTÖR AMELİYELERİ -- YUVA YOK, CARTAN KÖKÜ VAR (ferman 2-Ö)",
        "    Meleke tamsayı yuva aramaz; sektörün zâtî Cartan",
        "    jeneratörüne kilitlenir. Düşen kapı riyazî olarak",
        "    imkânsızdır: arada bekçi yoktur.",
        "    dönme %d   faz vuruşu %d   kenet %d   örüntü %d"
        % (int(d["dönme"]), int(d["faz_vuruşu"]), int(d["kenet"]),
           int(d["örüntü"])),
        "    BEDEL SAYILIR (ferman 5): küllî faz yazması %d ·"
        " küllî iç çarpım %d · sektör kapı dizeyi %d"
        % (int(d["küllî_faz_yazması"]), int(d.get("küllî_iç_çarpım", 0)),
           int(d["kapı_dizeyi"])),
        "    İkisi de yazmacın TAMAMINI tarar. Kenet defterinde altı",
        "    kenet aynı hâli okur ve defter uygulanmadığı için norm",
        "    değişmez: ağırlık BİR KEZ ölçülüp altısına verilir, yâni",
        "    iç çarpım kenet başına değil DEFTER başınadır (ferman 3).",
        "    Sayı büyükse yavaşlamanın yeri burasıdır.   (ölçü %s)"
        % ("açık" if d.get("açık") else "KAPALI"),
    ])

_SENET_SAYAC: Dict[str, float] = {"yazma": 0.0, "bayt": 0.0,
                                  "mahallî": 0.0, "mahallî_bayt": 0.0}


def senet_beyani() -> Dict[str, float]:
    b = dict(_SENET_SAYAC)
    b["bayt_başına"] = (b["bayt"] / b["yazma"]) if b["yazma"] else 0.0
    return b


_CEYREK = np.array([1.0 + 0.0j, 0.0 + 1.0j, -1.0 + 0.0j, 0.0 - 1.0j])

SENET_ACIK: List[bool] = [False]


class Iz:

    def __init__(self) -> None:
        self.kapi = 0
        self.kesme = 0.0
        self.defter: List[Tuple[str, str]] = []
        self.senet_acik = bool(SENET_ACIK[0])
        self.senet: List[Tuple[str, Tuple[int, ...], np.ndarray]] = []
        self.baglanti: List[Tuple[int, int, float, Any]] = []
        self.mahalli_senet: List[np.ndarray] = []
        self.mahalli_bag: List[Tuple[int, float, int, np.ndarray]] = []
        self.derinlik = 0
        self.uretecsiz = 0
        self.bag_reddi = 0
        self.son_senet = -1

    def not_dus(self, meleke: str, mesaj: str = "") -> None:
        self.defter.append((str(meleke), str(mesaj)))

    def senedi_ac(self) -> None:
        self.senet_acik = True
        self.senet = []
        self.baglanti = []
        self.uretecsiz = 0
        self.mahalli_senet: List[np.ndarray] = []
        self.mahalli_bag = []

    def mahalli_bag_yaz(self, par: int, olcek: float, seviye: int,
                        aci: np.ndarray) -> int:
        if not self.senet_acik:
            return -1
        self.mahalli_bag.append((int(par), float(olcek), int(seviye),
                                 np.asarray(aci, float).copy()))
        _SENET_SAYAC["mahallî_bağ"] = _SENET_SAYAC.get(
            "mahallî_bağ", 0.0) + 1.0
        return len(self.mahalli_bag) - 1

    def mahalli_yaz(self, mahalli) -> int:
        if not self.senet_acik or mahalli is None:
            return -1
        dilim = mahalli.senet_dilimi()
        if dilim.size == 0:
            return -1
        self.mahalli_senet.append(dilim)
        _SENET_SAYAC["mahallî"] += 1.0
        _SENET_SAYAC["mahallî_bayt"] += float(dilim.nbytes)
        return len(self.mahalli_senet) - 1

    def senedi_kapat(self) -> None:
        self.senet_acik = False

    def kapi_yaz(self, tur: str, yuvalar, G) -> int:
        if not self.senet_acik:
            return -1
        _SENET_SAYAC["yazma"] += 1.0
        A = np.asarray(G)
        _SENET_SAYAC["bayt"] += float(A.nbytes)
        self.senet.append((str(tur),
                           tuple(int(y) for y in np.atleast_1d(yuvalar)),
                           A.copy()))
        self.son_senet = len(self.senet) - 1
        return self.son_senet

    def bag_yaz(self, senet_no: int, parametre: int, olcek: float,
                turev=None) -> None:
        if not self.senet_acik or int(senet_no) < 0:
            if self.senet_acik:
                self.bag_reddi += 1
            return
        if turev is None:
            self.uretecsiz += 1
            return
        self.baglanti.append((int(senet_no), int(parametre), float(olcek),
                              turev))


@dataclass
class QuditAyar:

    d: int = 4096
    lif: Tuple[int, ...] = (16, 16, 16)
    yigin: int = 1
    kulli_alanlar: Tuple[Tuple[str, int], ...] = (
        ("makam", 3), ("mizan", 4), ("tenakuz", 2), ("tasdik", 2),
        ("sukut", 1), ("nakz", 2), ("kelam", 4), ("kaide", 12),
        ("orak", 1), ("gaye", 2), ("tertip", 4),
    )
    yerel_yuva: int = 1
    tip: object = np.complex128
    tohum: int = 0
    motor: str = "sürekli"
    faz_mertebesi: int = 16
    hat: str = "c"
    hat_bandi: int = 0

    def __post_init__(self):
        if int(np.prod(self.lif)) != int(self.d):
            raise ValueError("lifler çarpımı d'ye eşit olmalı: %s ≠ %d"
                             % (self.lif, self.d))


class QuditYazmac:

    def __init__(self, ayar: Optional[QuditAyar] = None,
                 veri_lifi: int = 4,
                 n: Optional[int] = None, bag: Optional[int] = None,
                 tohum: int = 0, tip=None, obek: Optional[int] = None,
                 yigin: Optional[int] = None) -> None:
        if ayar is None and n is not None:
            k = int(np.ceil(np.log2(max(int(n), 2))))
            k = int(min(max(k, 1), 20))
            ayar = QuditAyar(d=1 << k, lif=(1 << k,), tohum=int(tohum),
                             yigin=int(yigin or 1))
            veri_lifi = k
        self.ayar = ayar or QuditAyar()
        a = self.ayar
        self._veri_lifi = int(veri_lifi)
        ns, carp = 0, 1
        for _x in tuple(a.lif):
            if carp >= int(veri_lifi):
                break
            carp *= int(_x)
            ns += 1
        self._n_satir = max(1, ns)
        self._yuva_onbellek: Dict[int, Tuple[int, int]] = {}
        self._ikinin_kuvveti = all(
            (int(x) & (int(x) - 1)) == 0 for x in tuple(self.ayar.lif))
        self._bolum_onbellek: Dict[int, Tuple[int, int]] = {}
        self._gecerli_onbellek: Dict[int, bool] = {}
        self._adres_np: Optional[Tuple[np.ndarray, np.ndarray,
                                       np.ndarray]] = None
        self._veri_yuvasi = max(1, int(a.lif[0]).bit_length() - 1)
        self._satir_yuva = self._veri_yuvasi + int(self.ayar.yerel_yuva)
        self._dusen_kapi = 0
        self._kontrollu_kapi = 0
        self._matchgate_kapi = 0
        r = np.random.default_rng(int(a.tohum))
        self.B = int(a.yigin)
        self.d = int(a.d)
        self._seviye = int(round(math.log2(self.d)))
        assert 2 ** self._seviye == self.d, (
            "bit düzlemi ikinin kuvvetini ister: d=%d" % self.d)
        self._bekleyen: Dict[int, np.ndarray] = {}
        from .qcekirdek import Bant
        self._bant = Bant(int(a.yigin), int(a.d), tuple(a.lif),
                          hat=str(a.hat), bant=int(a.hat_bandi))
        self._faz_bekleyen: Optional[np.ndarray] = None
        self._faz_toplam = np.zeros((int(a.yigin), int(a.d)), float)
        self._faz_indirilen = 0
        self.cephe = 0
        self._psi = np.full((self.B, self.d), 1.0 / np.sqrt(self.d),
                            dtype=a.tip)
        self._sadakat_log = 0.0
        self._kapi = 0
        self.iz = Iz()
        self.bag = 0
        self._sektor: Dict[str, Tuple[int, int]] = {}
        self._sektor_vurusu = 0
        bas = 0
        for ad, _pay in a.kulli_alanlar:
            gen = int(KULLI_SEKTOR_TABANI)
            assert int(_pay) <= gen, (
                "'%s' sektörü %d yuva ister, sabit taban %d'ten büyük "
                "olamaz (ferman 90)" % (ad, int(_pay), gen))
            assert bas + gen <= self.d, (
                "yazmaç küllî sektörlere yetmiyor: '%s' sektörü [%d,%d) "
                "ister, d=%d -- ölçülen bir sayıdır, sessizce küçültülemez "
                "(ferman 5)" % (ad, bas, bas + gen, self.d))
            self._sektor[ad] = (bas, bas + gen)
            bas += gen

    @property
    def n(self) -> int:
        return self._n_satir * (self._veri_lifi
                                + int(self.ayar.yerel_yuva)) + self.d

    @property
    def A(self) -> np.ndarray:
        return self.lifli

    def tekil_yogunluklar(self, yuvalar: Sequence[int]) -> np.ndarray:
        idx = [int(y) for y in np.asarray(yuvalar, np.intp).reshape(-1)]
        if not idx:
            return np.zeros((self.B, 0, 2, 2))
        lif = tuple(self.ayar.lif)
        T = self.lifli
        out = np.zeros((self.B, len(idx), 2, 2), complex)
        for m, y in enumerate(idx):
            k, alt = self._lif_no(y)
            if not (0 <= k < len(lif)):
                out[:, m] = np.eye(2) * 0.5
                continue
            n = lif[k]
            b = 1 << int(alt)
            if b >= n:
                out[:, m] = np.eye(2) * 0.5
                continue
            X = np.moveaxis(T, k + 1, -1).reshape(self.B, -1, n)
            m0 = np.array([x for x in range(n) if not (x & b)])
            m1 = m0 | b
            a0, a1 = X[:, :, m0], X[:, :, m1]
            out[:, m, 0, 0] = np.sum(np.abs(a0) ** 2, axis=(1, 2))
            out[:, m, 1, 1] = np.sum(np.abs(a1) ** 2, axis=(1, 2))
            c = np.sum(a0 * a1.conj(), axis=(1, 2))
            out[:, m, 0, 1] = c
            out[:, m, 1, 0] = c.conj()
        iz = out[:, :, 0, 0] + out[:, :, 1, 1]
        return out / np.maximum(iz[:, :, None, None].real, 1e-300)

    def yuva_yogunluklari(self, yuvalar=None) -> np.ndarray:
        if yuvalar is None:
            yuvalar = list(range(min(8, self.d)))
        return self.tekil_yogunluklar(yuvalar)

    def blok_dagilimi(self, bas: int, kac: int) -> np.ndarray:
        k, alt = self._lif_no(int(bas))
        k = min(int(k), len(self.ayar.lif) - 1)
        n = self.ayar.lif[k]
        X = np.moveaxis(self.lifli, k + 1, -1).reshape(self.B, -1, n)
        p = np.sum(np.abs(X) ** 2, axis=1)
        m = min(1 << int(kac), n)
        parca = np.array_split(np.arange(n), m)
        P = np.stack([p[:, i].sum(axis=1) for i in parca], axis=1)
        return P / np.maximum(P.sum(axis=1, keepdims=True), 1e-300)

    def olcumler_yigin(self) -> Dict[str, np.ndarray]:
        o = self.olcumler()
        return {k: np.atleast_1d(np.asarray(v, float))
                for k, v in o.items()}

    def makam_derece_vektoru(self) -> np.ndarray:
        n = int(self._mahalli_zorunlu().pencere)
        return np.linspace(0.0, 1.0, max(2, n))

    def makam_dagilimi(self) -> np.ndarray:
        return self._mahalli_zorunlu().kok_dagilimi("makam")

    @property
    def lifli(self) -> np.ndarray:
        return self.psi.reshape((self.B,) + tuple(self.ayar.lif))

    def norm(self) -> np.ndarray:
        return np.sum(np.abs(self.psi) ** 2, axis=1)

    def normalize(self) -> np.ndarray:
        n = np.sqrt(np.maximum(self.norm(), 1e-300))
        self.iz.kapi_yaz("ölçek", (), n.reshape(-1, 1).copy())
        self.psi = self.psi / n[:, None]
        return n

    def norm_hatasi(self) -> float:
        return float(np.max(np.abs(self.norm() - 1.0)))

    def sadakat(self) -> float:
        return 1.0

    def sadakat_kapi_basina(self, kapi: int = 1) -> float:
        return 1.0

    def ic_carpim(self, other=None) -> np.ndarray:
        o = self.psi if other is None else np.asarray(other)
        return np.sum(np.conj(self.psi) * o, axis=1)

    def supurme(self, *a, **k) -> None:
        self.iz.not_dus("süpürme", "quditte süpürme yok -- işlem yok")

    def takas(self, *a, **k) -> None:
        self.iz.not_dus("takas", "quditte takas yok -- işlem yok")

    def genlik(self, idx) -> np.ndarray:
        return self.psi[:, int(idx)]

    def deger(self, idx) -> np.ndarray:
        return self.genlik(idx)

    def parametre(self) -> int:
        return int(self.d * 2)

    def bayt(self) -> int:
        return int(self.psi.nbytes)

    def superpozisyona_sok(self) -> None:
        self.superpozisyon()

    def harman_kur(self, *a, **k) -> None:
        self.iz.not_dus("harman_kur", "qudit lif üniterleri kullanılır")

    def tek_kapi(self, G, yuvalar) -> None:
        for y in np.atleast_1d(np.asarray(yuvalar)).reshape(-1):
            self.tek(int(y), G)

    def tek_kapi_yuva(self, yuva: int, G) -> None:
        self.tek(int(yuva), G)

    def cift_kapi(self, G, ofset: int = 0, alt=None, ust=None) -> None:
        self.cift(int(ofset), G)

    def cift_kapi_yuva(self, i: int, j: int, G) -> None:
        self.uzak_cift(int(i), int(j), G)

    def tek_kapi_yigin(self, yuvalar, G) -> None:
        self.tek_yigin(yuvalar, G)

    def cift_kapi_yigin(self, sol_yuvalar, G) -> None:
        G = np.asarray(G)
        m = len(list(sol_yuvalar))
        if G.ndim == 2:
            G = np.broadcast_to(G, (m,) + G.shape)
        for y, g in zip(sol_yuvalar, G):
            self.cift(int(y), g)

    def sadakat_log(self) -> float:
        return float(self._sadakat_log)

    def lif_kapisi(self, k: int, G: np.ndarray) -> None:
        raise NotImplementedError(
            "``lif_kapisi`` imha edildi: n×n kapı graf motoruna geçmez. "
            "Bit düzlemi kapılarını kullanın (``tek``, ``cift``, "
            "``bit_kapisi``). Lif %d, kapı %r." % (k, np.shape(G)))

    def _bit(self, k: int, alt: int) -> int:
        _on, ard = self._bolum(int(k))
        return int(math.log2(ard)) + int(alt)

    def _mahalli_zorunlu(self):
        m = getattr(self, "mahalli", None)
        assert m is not None, (
            "SEKTÖR MAHALLÎ YAZMAÇTAN OKUNUR -- bu yazmaca mahallî zırh "
            "bağlanmamış. Sektör bir bellek dilimi değil, Lie cebrinin "
            "zâtî süperseçim (DHR) yüküdür (ferman 2-Ö, 2-İ, 3-D #90).")
        assert int(getattr(m, "pencere", 0)) > 0, (
            "SEKTÖR OKUNDU FAKAT AKTİF PENCERE SIFIR -- `kodla` mahallî "
            "zırha tohum ekmeden sektör tartılamaz (ferman 2-A)")
        return m

    def sektor_agirligi(self, ad: str) -> np.ndarray:
        w = self._mahalli_zorunlu().sektor_yigini(str(ad))
        _SEKTOR_SAYAC["mahallî_okuma"] = _SEKTOR_SAYAC.get(
            "mahallî_okuma", 0.0) + 1.0
        return np.resize(np.asarray(w, float), self.B)


    def _eksen(self, k: int, alt: int) -> int:
        lif = tuple(self.ayar.lif)
        if not (0 <= int(k) < len(lif)):
            return 0
        n = int(lif[int(k)])
        if (1 << int(alt)) >= n:
            return 0
        return self._seviye - self._bit(int(k), int(alt))

    def _duzlem(self, T: np.ndarray, eksen: int, bit: int) -> np.ndarray:
        return T[(slice(None),) * eksen + (int(bit),)]

    def _bit_gorunumu(self) -> np.ndarray:
        T = self.psi.reshape((self.B,) + (2,) * self._seviye)
        assert np.shares_memory(T, self.psi), (
            "bit görünümü kopya çıktı -- kapı duruma vurmazdı")
        return T


    @property
    def psi(self) -> np.ndarray:
        if (self._bekleyen or self._faz_bekleyen is not None
                or not self._bant.bos_mu()):
            self._bosalt()
        return self._psi

    @psi.setter
    def psi(self, v) -> None:
        self._bekleyen.clear()
        self._faz_bekleyen = None
        self._psi = np.asarray(v)
        if self.iz.senet_acik:
            self.iz.kapi_yaz("durum", (),
                             np.asarray(self._psi, complex).copy())

    @property
    def psi_tensor(self) -> np.ndarray:
        return self.psi.reshape((self.B,) + tuple(self.ayar.lif))

    @psi_tensor.setter
    def psi_tensor(self, v) -> None:
        self.psi = np.asarray(v).reshape(self.B, self.d)

    def _karolari_banda(self) -> None:
        if not self._bekleyen:
            return
        bekleyen, self._bekleyen = self._bekleyen, {}
        for k in sorted(bekleyen):
            self._bant.karo(int(k), bekleyen[k])

    def _bosalt(self) -> None:
        self._karolari_banda()
        if not self._bant.bos_mu():
            self._psi = np.ascontiguousarray(self._psi)
            self._bant.bosalt(self._psi)
        self._faz_indir()

    def _faz_indir(self) -> None:
        t = self._faz_bekleyen
        if t is None:
            return
        self._faz_bekleyen = None
        if not np.any(t):
            return
        if self.iz.senet_acik:
            self.iz.kapi_yaz("faz", (),
                             np.broadcast_to(t, (self.B, self.d)).copy())
        self._psi = (self._psi * np.exp(-1j * t)).astype(self._psi.dtype)
        self._faz_toplam = self._faz_toplam + t
        self._faz_indirilen += 1

    def faz_birikimi(self) -> np.ndarray:
        return self._faz_toplam.copy()

    def faz_borcu(self) -> Dict[str, float]:
        a = np.abs(np.asarray(self._faz_toplam, float).reshape(-1))
        return {"toplam_faz_ortalama": float(np.mean(a)) if a.size else 0.0,
                "toplam_faz_azamî": float(a.max()) if a.size else 0.0,
                "indirme": float(self._faz_indirilen)}

    def _karo_indir(self, k: int, M: np.ndarray) -> None:
        n = int(self.ayar.lif[int(k)])
        on, ard = self._bolum(int(k))
        M = np.asarray(M, complex)
        if M.ndim == 3:
            X = self._psi.reshape(self.B, on, n, ard)
            Y = np.einsum("bij,bojd->boid", M, X, optimize=True)
            self._psi = np.ascontiguousarray(
                Y.reshape(self.B, self.d), dtype=self._psi.dtype)
            return
        X = self._psi.reshape(self.B * on, n, ard)
        if ard == 1:
            Y = X.reshape(-1, n) @ M.T
        else:
            Y = np.matmul(M, X)
        self._psi = np.ascontiguousarray(
            Y.reshape(self.B, self.d), dtype=self._psi.dtype)

    def _karo_vur(self, k: int, M: np.ndarray) -> None:
        self._faz_indir()
        M = np.asarray(M, complex)
        self.iz.kapi_yaz("karo", (int(k),), M)
        self._kapi += 1
        self.iz.kapi += 1
        if M.ndim == 3:
            self._bosalt()
            self._karo_indir(int(k), M)
            return
        eski = self._bekleyen.get(int(k))
        self._bekleyen[int(k)] = M if eski is None else M @ eski

    def _bit_kapisi_lifli(self, k: int, alt: int, G: np.ndarray,
                          bag=None) -> None:
        if self._eksen(k, alt) <= 0:
            self._dusen_kapi += 1
            if bag:
                self.iz.uretecsiz += len(bag)
            return
        n = int(self.ayar.lif[int(k)])
        self._karo_vur(k, self._gomulu(n, int(alt), G))
        if not bag or not self.iz.senet_acik:
            return
        for (par, olcek, dG) in bag:
            self.iz.bag_yaz(self.iz.son_senet, int(par), float(olcek),
                            ("bit", int(k), int(alt),
                             np.asarray(dG, complex).reshape(2, 2)))

    def _cift_kapisi_lifli(self, ki: int, ai: int, kj: int, aj: int,
                           G: np.ndarray, baglar=None) -> None:
        ei = self._eksen(ki, ai)
        ej = self._eksen(kj, aj)
        if ei <= 0 or ej <= 0 or ei == ej:
            self._dusen_kapi += 1
            if baglar:
                self.iz.uretecsiz += len(baglar)
            return
        G = np.asarray(G, complex).reshape(4, 4)
        if int(ki) == int(kj):
            n = int(self.ayar.lif[int(ki)])
            bi, bj = 1 << int(ai), 1 << int(aj)
            M = np.eye(n, dtype=complex)
            for x in range(n):
                if (x & bi) or (x & bj):
                    continue
                idx = [x, x | bj, x | bi, x | bi | bj]
                for a in range(4):
                    for b in range(4):
                        M[idx[a], idx[b]] = G[a, b]
            self._karo_vur(int(ki), M)
            if baglar:
                no = self.iz.son_senet
                n2 = int(self.ayar.lif[int(ki)])
                for (par, olcek, dG) in baglar:
                    dM = np.zeros((n2, n2), complex)
                    dG4 = np.asarray(dG, complex).reshape(4, 4)
                    for x in range(n2):
                        if (x & bi) or (x & bj):
                            continue
                        ix = [x, x | bj, x | bi, x | bi | bj]
                        for a in range(4):
                            for b in range(4):
                                dM[ix[a], ix[b]] = dG4[a, b]
                    self.iz.bag_yaz(no, int(par), float(olcek),
                                    ("karo4", int(ki), dM))
            return
        self._faz_indir()
        self._karolari_banda()
        bi = 1 << int(self._seviye - ei)
        bj = 1 << int(self._seviye - ej)
        if matchgate_mi(G)[0]:
            self._matchgate_kapi += 1
        _no = self.iz.kapi_yaz("bant", (int(bi), int(bj)), G)
        if baglar:
            for (par, olcek, dG) in baglar:
                self.iz.bag_yaz(_no, int(par), float(olcek),
                                ("bant4", int(bi), int(bj),
                                 np.asarray(dG, complex).reshape(4, 4)))
        self._bant.cift(bi, bj, G)
        self._kapi += 1
        self.iz.kapi += 1

    def bit_kapisi(self, k: int, alt: int, G: np.ndarray, bag=None) -> None:
        self._bit_kapisi(k, alt, G, bag)

    def _bit_kapisi(self, k: int, alt: int, G: np.ndarray,
                    bag=None) -> None:
        self._bit_kapisi_lifli(k, alt, G, bag)

    def faz(self, teta) -> None:
        t = np.asarray(teta, float)
        if t.ndim == 1 and t.size != self.d:
            from .qudit import agirlik
            t = np.asarray(agirlik(self.d, t.reshape(-1)), float)
        t = np.atleast_2d(t)
        assert t.shape[-1] == self.d, (
            "faz açısı yazmaç ebadında olmalı: %s ≠ %d"
            % (t.shape, self.d))
        t = np.broadcast_to(t, (self.B, self.d)).copy()
        if self._bekleyen:
            self._bosalt()
        self._faz_bekleyen = (t if self._faz_bekleyen is None
                              else self._faz_bekleyen + t)
        self._kapi += 1

    def sektor_kapisi(self, ad: str, M: np.ndarray) -> None:
        m = self._mahalli_zorunlu()
        M = np.asarray(M)
        assert M.ndim == 2 and M.shape[0] == M.shape[1], (
            "sektör kapısı kare olmalı, %s verildi" % (M.shape,))
        self.iz.mahalli_yaz(m)
        vuran = int(m.kok_kapisi(str(ad), M))
        if vuran <= 0:
            self._dusen_kapi += 1
            _SEKTOR_SAYAC["düşen"] = _SEKTOR_SAYAC.get("düşen", 0.0) + 1.0
            return
        _SEKTOR_SAYAC["kapı_dizeyi"] += 1.0
        self._kapi += 1

    def sektor_faz_vur(self, ad: str, aci, bag=None) -> int:
        m = getattr(self, "mahalli", None)
        if m is not None:
            m.cartan_ekle(str(ad), float(np.mean(
                np.asarray(aci, float).reshape(-1))))
        i, j = self.sektor(ad)
        a = np.asarray(aci, float).reshape(-1)
        gen = int(j - i)
        if a.size != gen:
            a = np.resize(a, gen) if a.size else np.zeros(gen, float)
        t = np.zeros(self.d, float)
        t[i:j] = a
        self.faz(t)
        self._sektor_vurusu += 1
        _SEKTOR_SAYAC["faz_vuruşu"] += 1.0
        _SEKTOR_SAYAC["küllî_faz_yazması"] += 1.0
        if bag:
            self._faz_bagla(np.arange(i, j, dtype=np.int64), bag)
        return gen

    def _genlik_agirligi(self) -> float:
        _SEKTOR_SAYAC["küllî_iç_çarpım"] = _SEKTOR_SAYAC.get(
            "küllî_iç_çarpım", 0.0) + 1.0
        return float(self._mahalli_zorunlu().kulli_agirlik())

    def sektor_donmesi(self, ad: str, teta, bag=None) -> int:
        m = self._mahalli_zorunlu()
        a = np.asarray(teta, float).reshape(-1)
        if a.size == 0:
            a = np.zeros(1, float)
        vuran = int(m.kok_donmesi(str(ad), a))
        if vuran <= 0:
            self._dusen_kapi += 1
            _SEKTOR_SAYAC["düşen"] = _SEKTOR_SAYAC.get("düşen", 0.0) + 1.0
            return 0
        self.iz.mahalli_yaz(m)
        self._kapi += 1
        self._sektor_vurusu += 1
        _SEKTOR_SAYAC["dönme"] += 1.0
        m.cartan_ekle(str(ad), float(np.mean(a)))
        if bag and self.iz.senet_acik:
            sev = int(m.kok_seviyesi(ad))
            for (par, olcek, pay) in ([bag] if isinstance(bag, tuple)
                                      else list(bag)):
                p = np.asarray(pay, float).reshape(-1)
                agir = (a * np.resize(p, a.size)) if p.size else a
                self.iz.mahalli_bag_yaz(int(par), float(olcek), sev, agir)
            _SEKTOR_SAYAC["mahallî_bağ"] = _SEKTOR_SAYAC.get(
                "mahallî_bağ", 0.0) + 1.0
        return vuran

    def sektor_cifti(self, kontrol: str, hedef: str,
                     bag: float = 1.0, degil: bool = False,
                     aci=None, senet=None, defter=None,
                     agirlik=None) -> float:
        i0, j0 = self.sektor(kontrol)
        i1, j1 = self.sektor(hedef)
        top = (float(agirlik) if agirlik is not None
               else self._genlik_agirligi())
        assert top > 0.0, (
            "yazmaç tamamen söndü -- kenetlenecek genlik yok (ferman 5)")
        m = self._mahalli_zorunlu()
        w_kontrol = float(m.sektor_yigini(str(kontrol)).sum() / top)
        w_kontrol = min(1.0, max(0.0, w_kontrol))
        if degil:
            w_kontrol = 1.0 - w_kontrol
        w_hedef = np.asarray(m.kok_dagilimi(str(hedef)),
                             float).mean(axis=0)
        pay = float(w_hedef.sum())
        teta = float(m.cartan_oku(str(kontrol)))
        gen = int(w_hedef.size)
        if aci is None:
            a = np.full(gen, teta, float)
        else:
            a = np.asarray(aci, float).reshape(-1)
            a = np.resize(a, gen) if a.size else np.zeros(gen, float)
        etki = float(bag) * float(np.mean(a)) * w_kontrol
        t = np.zeros(self.d, float)
        if pay > 0.0:
            dal = -float(bag) * w_kontrol * a * (w_hedef / pay) * gen
            u = int(min(self.d, i1 + dal.size))
            t[i1:u] = dal[:u - i1]
        if defter is None:
            self.faz(t)
        else:
            defter += t
        if defter is None:
            _SEKTOR_SAYAC["küllî_faz_yazması"] += 1.0
        self._sektor_vurusu += 1
        _SEKTOR_SAYAC["kenet"] += 1.0
        self._kenet_vurusu = getattr(self, "_kenet_vurusu", 0) + 1
        if senet and defter is None:
            self._faz_bagla(np.arange(i1, j1, dtype=np.int64), senet)
        elif senet:
            self._bekleyen_bag = getattr(self, "_bekleyen_bag", [])
            self._bekleyen_bag.append(
                (np.arange(i1, j1, dtype=np.int64), list(senet)))
        if m is not None:
            m.cartan_ekle("kenet.%s%s×%s"
                          % ("¬" if degil else "", kontrol, hedef), etki)
        return etki

    def sektor_kenetleri(self, kenetler) -> float:
        k = list(kenetler)
        if not k:
            return 0.0
        defter = np.zeros(self.d, float)
        self._bekleyen_bag = []
        agirlik = self._genlik_agirligi()
        etki = 0.0
        for z in k:
            etki += self.sektor_cifti(
                str(z[0]), str(z[1]),
                bag=float(z[2]) if len(z) > 2 and z[2] is not None else 1.0,
                degil=bool(z[3]) if len(z) > 3 else False,
                aci=z[4] if len(z) > 4 else None,
                senet=z[5] if len(z) > 5 else None,
                defter=defter, agirlik=agirlik)
        self.faz(defter)
        _SEKTOR_SAYAC["küllî_faz_yazması"] += 1.0
        for dizin, senet in self._bekleyen_bag:
            self._faz_bagla(dizin, senet)
        self._bekleyen_bag = []
        return float(etki)

    def sektor_oruntusu(self, oruntu, kok: str = "") -> float:
        d = dict(oruntu or {})
        if not d:
            return 0.0
        top = self._genlik_agirligi()
        assert top > 0.0, (
            "yazmaç tamamen söndü -- örüntü tartılamaz (ferman 5)")
        carpim = 1.0
        parca: List[str] = []
        mh = self._mahalli_zorunlu()
        for sek in sorted(d):
            w = float(mh.sektor_yigini(str(sek)).sum() / top)
            w = min(1.0, max(0.0, w))
            bit = int(d[sek]) & 1
            carpim *= (w if bit else (1.0 - w))
            parca.append(("" if bit else "¬") + str(sek))
        ad = kok or ("yasak." + "∧".join(parca))
        mh.cartan_ekle(ad, float(carpim) * math.pi)
        self._oruntu_vurusu = getattr(self, "_oruntu_vurusu", 0) + 1
        self._sektor_vurusu += 1
        _SEKTOR_SAYAC["örüntü"] += 1.0
        return float(carpim)

    def sektor_faz_bagi(self, ad: str, par, olcek: float,
                        pay=None) -> List[Tuple[int, float, np.ndarray]]:
        i, j = self.sektor(ad)
        gen = int(j - i)
        pid = np.asarray(par, np.int64).reshape(-1)
        p = (np.ones(gen) if pay is None
             else np.resize(np.asarray(pay, float).reshape(-1), gen))
        bag = []
        for k in range(min(gen, pid.size)):
            v = np.zeros(gen, float)
            v[k] = float(p[k])
            bag.append((int(pid[k]), float(olcek), v))
        return bag

    def sektor(self, ad: str) -> Tuple[int, int]:
        if ad not in self._sektor:
            raise ValueError("küllî alan bilinmiyor: %r" % (ad,))
        return self._sektor[ad]

    def alan_degeri(self, ad: str):
        v = self.sektor_agirligi(ad)
        return float(v[0]) if self.B == 1 else v

    def olcumler(self) -> Dict[str, float]:
        mh = self._mahalli_zorunlu()
        out: Dict[str, float] = {}
        for ad in self._sektor:
            v = np.resize(np.asarray(mh.sektor_yigini(ad), float), self.B)
            out[ad] = float(v[0]) if self.B == 1 else v
        e = self.dolasiklik_entropisi()
        out["entropi"] = float(e["entropi"])
        out["norm_hatası"] = self.norm_hatasi()
        return out

    def dolasiklik_entropisi(self, kesit: int = 1) -> Dict[str, float]:
        lif = tuple(self.ayar.lif)
        kesit = int(np.clip(kesit, 1, len(lif) - 1))
        sol = int(np.prod(lif[:kesit]))
        sag = int(np.prod(lif[kesit:]))
        M = self.psi.reshape(self.B, sol, sag)
        rho = np.einsum("bij,bkj->bik", M, M.conj())
        iz = np.einsum("bii->b", rho).real
        rho = rho / np.maximum(iz, 1e-300)[:, None, None]
        w = np.linalg.eigvalsh(rho)
        w = np.clip(w.real, 1e-300, None)
        S = -np.sum(w * np.log(w), axis=1)
        return {"entropi": float(np.mean(S)),
                "entropi_yigin": S,
                "schmidt": float(min(sol, sag)),
                "kesit": kesit}

    def cephe_hali(self) -> np.ndarray:
        mh = self._mahalli_zorunlu()
        c = int(np.clip(int(self.cephe), 0, int(mh.pencere) - 1))
        n_v = int(self.ayar.lif[0])
        q = int(min(n_v, int(mh.taban)))
        H = np.zeros((self.B, n_v), complex)
        dilim = np.asarray(mh.hal[:, c, :q], complex)
        H[:dilim.shape[0], :q] = dilim[:self.B]
        G = getattr(self, "_cephe_genligi", None)
        assert G is not None, (
            "CEPHE HÂLİ SIRF MAHALLÎ OKUNAMAZ -- hibrit yazmaç ikisi "
            "beraberdir: donanım kanadı mahallî zırh, idrak kanadı KAN "
            "genliği (ferman 2-Ş, 2-Ê). İntâc koşmadan hâl istenmiş.")
        A = np.asarray(G, complex)
        k = int(min(n_v, A.shape[-1]))
        carpan = np.ones((self.B, n_v), complex)
        carpan[:A.shape[0], :k] = A[:self.B, :k]
        H = H * carpan
        _SEKTOR_SAYAC["hibrit_hal"] = _SEKTOR_SAYAC.get(
            "hibrit_hal", 0.0) + 1.0
        nrm = np.linalg.norm(H, axis=-1, keepdims=True)
        canli = nrm > 0.0
        assert bool(canli.any()), (
            "NEDENSEL CEPHE TAMAMEN SÖNDÜ -- hedef qudit %d, pencere %d; "
            "hâl okunamaz (ferman 2-Ê, 2-Ï, 5)" % (c, int(mh.pencere)))
        _SEKTOR_SAYAC["cephe_hali"] = _SEKTOR_SAYAC.get(
            "cephe_hali", 0.0) + 1.0
        return np.where(canli, H / np.where(canli, nrm, 1.0), H)

    def beyan(self, sozluk: int = 0) -> np.ndarray:
        taban = int(sozluk) if int(sozluk) >= 2 else int(self.ayar.lif[0])
        assert taban == int(self.ayar.lif[0]), (
            "beyan basamak eksenini okur: taban %d, lif[0] %d -- ikisi "
            "aynı eksen olmalı (ferman 1-M)" % (taban, int(self.ayar.lif[0])))
        mh = self._mahalli_zorunlu()
        c = int(np.clip(int(self.cephe), 0, int(mh.pencere) - 1))
        q = int(min(taban, int(mh.taban)))
        p = np.abs(np.asarray(mh.hal[:, c, :q], complex)) ** 2
        top = p.sum(axis=1, keepdims=True)
        canli = top > 0.0
        p = np.where(canli, p / np.where(canli, top, 1.0),
                     1.0 / float(max(1, q)))
        _SEKTOR_SAYAC["cephe_okuma"] = _SEKTOR_SAYAC.get(
            "cephe_okuma", 0.0) + 1.0
        if q == taban:
            return np.resize(p, (self.B, taban))
        cik = np.zeros((p.shape[0], taban), float)
        cik[:, :q] = p
        return np.resize(cik, (self.B, taban))

    def beyan_vecihle(self, sozluk: int, vecihler) -> np.ndarray:
        duz = self.beyan(int(sozluk))
        vs = list(vecihler or ())
        if not vs:
            return duz
        taban = int(sozluk) if int(sozluk) >= 2 else int(self.ayar.lif[0])
        top = np.zeros(taban, float)
        agir = 0.0
        for v in vs:
            u = np.asarray(v.gor(self.psi[0]), complex).reshape(-1)
            if u.size != self.d or not np.all(np.isfinite(u)):
                continue
            p = (np.abs(u[:taban]) ** 2)
            s = float(p.sum())
            if s <= 0.0:
                continue
            top += (p / s) * float(v.agirlik)
            agir += float(v.agirlik)
        if agir <= 0.0:
            return duz
        return (top / agir).reshape(1, taban)

    def povm(self, ad: str) -> Tuple[float, float]:
        mh = self._mahalli_zorunlu()
        s0 = mh.kok_seviyesi(ad)
        n = int(mh.pencere)
        v = np.asarray(mh.hal[:, :n, s0], complex)
        yari = int(n) // 2 or 1
        z = float(np.mean(np.sum(np.abs(v[:, :yari]) ** 2, axis=1)
                          - np.sum(np.abs(v[:, yari:]) ** 2, axis=1)))
        x = float(np.mean(2.0 * np.real(
            np.sum(v[:, :yari] * v[:, yari:yari * 2].conj(), axis=1))))
        return z, x


    def superpozisyon(self) -> None:
        self.psi = np.full((self.B, self.d), 1.0 / np.sqrt(self.d),
                           dtype=self.ayar.tip)


    def _lif_no(self, yuva: int) -> Tuple[int, int]:
        y = int(yuva)
        c = self._yuva_onbellek.get(y)
        if c is not None:
            return c
        ns = self._n_satir
        satir_yuva = self._satir_yuva
        if y < ns * satir_yuva:
            c = (y // satir_yuva, y % satir_yuva)
        else:
            o = y - ns * satir_yuva
            c = (len(self.ayar.lif), o)
            for k in range(ns, len(self.ayar.lif)):
                w = int(self.ayar.lif[k]).bit_length() - 1
                if o < w:
                    c = (k, o)
                    break
                o -= w
        self._yuva_onbellek[y] = c
        return c

    def gecerli(self, yuva: int) -> bool:
        y = int(yuva)
        c = self._gecerli_onbellek.get(y)
        if c is not None:
            return c
        k, alt = self._lif_no(y)
        lif = tuple(self.ayar.lif)
        c = bool(0 <= k < len(lif) and (1 << int(alt)) < int(lif[k]))
        self._gecerli_onbellek[y] = c
        return c

    def _adres_dizileri(self):
        if self._adres_np is None:
            ns = self._n_satir
            satir_yuva = self._veri_lifi + int(self.ayar.yerel_yuva)
            lif = tuple(self.ayar.lif)
            n = ns * satir_yuva + sum(
                int(x).bit_length() - 1 for x in lif[ns:])
            k = np.empty(n, np.int64)
            alt = np.empty(n, np.int64)
            gec = np.empty(n, bool)
            for y in range(n):
                kk, aa = self._lif_no(y)
                k[y] = kk
                alt[y] = aa
                gec[y] = self.gecerli(y)
            self._adres_np = (gec, k, alt)
        return self._adres_np

    def gecerli_toplu(self, yuvalar) -> np.ndarray:
        y = np.asarray(yuvalar, np.int64).reshape(-1)
        gec, _k, _a = self._adres_dizileri()
        icinde = (y >= 0) & (y < gec.size)
        out = np.zeros(y.size, bool)
        out[icinde] = gec[y[icinde]]
        return out

    def lif_no_toplu(self, yuvalar) -> Tuple[np.ndarray, np.ndarray]:
        y = np.asarray(yuvalar, np.int64).reshape(-1)
        gec, k, a = self._adres_dizileri()
        icinde = (y >= 0) & (y < gec.size)
        kk = np.full(y.size, -1, np.int64)
        aa = np.full(y.size, -1, np.int64)
        kk[icinde] = k[y[icinde]]
        aa[icinde] = a[y[icinde]]
        return kk, aa

    def veri(self, i: int, j: int) -> int:
        return int(i) * self._satir_yuva + int(j)

    def adres_beyani(self) -> Dict[str, int]:
        yuva = int(self._seviye)
        sigan = yuva // max(1, int(self._satir_yuva))
        kulli_bas = self._n_satir * self._satir_yuva
        gecersiz = sum(1 for y in range(kulli_bas,
                                        kulli_bas + int(self.d))
                       if not self.gecerli(y))
        return {"yuva_bütçesi": yuva,
                "satır_yuvası": int(self._satir_yuva),
                "yazmacın_saydığı_satır": int(self._n_satir),
                "yuvaya_sığan_satır": int(sigan),
                "küllî_taban": int(kulli_bas),
                "küllî_geçersiz_yuva": int(gecersiz),
                "küllî_yuva_adedi": int(self.d)}

    @property
    def n_satir(self) -> int:
        return int(self._n_satir)

    @property
    def veri_yuvasi(self) -> int:
        return int(self._veri_yuvasi)

    def veri_izgara(self, sutun=None, satir=None) -> np.ndarray:
        i = (np.arange(self._n_satir) if satir is None
             else np.asarray(satir, np.int64).reshape(-1))
        j = (np.arange(self._veri_yuvasi) if sutun is None
             else np.asarray(sutun, np.int64).reshape(-1))
        return (i[:, None] * self._satir_yuva + j[None, :]).reshape(-1)

    def yerel(self, i: int) -> int:
        return self.veri(i, self._veri_yuvasi)

    def kulli(self, ad: str, j: int = 0) -> int:
        i, _ = self.sektor(ad)
        return self._n_satir * self._satir_yuva + i + int(j)

    def yereller(self) -> List[int]:
        return [self.yerel(i) for i in range(self._n_satir)]

    def bolge_var(self, ad: str) -> bool:
        return ad in self._sektor

    def not_dus(self, meleke: str, mesaj: str = "") -> None:
        self.iz.not_dus(meleke, mesaj)

    def kanonikle(self) -> None:
        self.iz.not_dus("kanonikle", "quditte kanoniklik yok -- işlem yok")

    def _gomulu(self, n: int, alt: int, G: np.ndarray) -> np.ndarray:
        G = np.asarray(G, complex)
        dilimli = G.ndim == 3
        if dilimli:
            assert G.shape == (self.B, 2, 2), (
                "dilimli kapı yığın ebadında olmalı: %s ≠ (%d, 2, 2) -- "
                "parametre seviyeleri yığın ekseninde durur (ferman 2-R)"
                % (G.shape, self.B))
            M = np.broadcast_to(np.eye(n, dtype=complex),
                                (self.B, n, n)).copy()
        else:
            G = G.reshape(2, 2)
            M = np.eye(n, dtype=complex)
        b = 1 << int(alt)
        if b >= n:
            return M
        for x in range(n):
            if x & b:
                continue
            y = x | b
            if dilimli:
                M[:, x, x] = G[:, 0, 0]; M[:, x, y] = G[:, 0, 1]
                M[:, y, x] = G[:, 1, 0]; M[:, y, y] = G[:, 1, 1]
            else:
                M[x, x] = G[0, 0]; M[x, y] = G[0, 1]
                M[y, x] = G[1, 0]; M[y, y] = G[1, 1]
        return M

    def kontrollu_tek(self, yuva: int, G_dilim: np.ndarray) -> None:
        if not self.gecerli(yuva):
            self._dusen_kapi += 1
            return
        k, alt = self._lif_no(yuva)
        if self._eksen(k, alt) <= 0:
            self._dusen_kapi += 1
            return
        n = int(self.ayar.lif[int(k)])
        self._karo_vur(int(k), self._gomulu(n, int(alt), G_dilim))
        self._kontrollu_kapi += 1

    def tek(self, yuva: int, G: np.ndarray, bag=None) -> None:
        if not self.gecerli(yuva):
            self._dusen_kapi += 1
            if bag is not None:
                self.iz.uretecsiz += 1
            return
        k, alt = self._lif_no(yuva)
        self.bit_kapisi(k, alt, G)
        if bag is None or not self.iz.senet_acik:
            return
        for (par, olcek, dG) in ([bag] if isinstance(bag, tuple)
                                 else list(bag)):
            self.iz.bag_yaz(self.iz.son_senet, int(par), float(olcek),
                            ("bit", int(k), int(alt),
                             np.asarray(dG, complex).reshape(2, 2)))

    def tek_yigin(self, yuvalar: Sequence[int], G, baglar=None) -> None:
        G = np.asarray(G)
        if G.ndim == 2:
            G = np.broadcast_to(G, (len(yuvalar), 2, 2))
        yv = np.asarray([int(y) for y in yuvalar], np.int64)
        if self.iz.senet_acik:
            gec0 = self.gecerli_toplu(yv)
            kk0, aa0 = self.lif_no_toplu(yv)
            self._dusen_kapi += int((~gec0).sum())
            B = list(baglar) if baglar is not None else None
            if B is not None:
                assert len(B) == yv.size, (
                    "her yuvanın kendi bağı olmalı: %d yuva, %d bağ "
                    "(ferman 1-C/b)" % (yv.size, len(B)))
            for idx in np.flatnonzero(gec0):
                self.bit_kapisi(int(kk0[idx]), int(aa0[idx]),
                                np.asarray(G[int(idx)], complex).reshape(2, 2))
                if B is None or B[int(idx)] is None:
                    continue
                par, olcek, dG = B[int(idx)]
                self.iz.bag_yaz(
                    self.iz.son_senet, int(par), float(olcek),
                    ("bit", int(kk0[idx]), int(aa0[idx]),
                     np.asarray(dG, complex).reshape(2, 2)))
            return
        sira: List[Tuple[int, int]] = []
        birik: Dict[Tuple[int, int], np.ndarray] = {}
        gec = self.gecerli_toplu(yv)
        kk, aa = self.lif_no_toplu(yv)
        self._dusen_kapi += int((~gec).sum())
        for idx in np.flatnonzero(gec):
            g = G[int(idx)]
            anahtar = (int(kk[idx]), int(aa[idx]))
            g2 = np.asarray(g, complex).reshape(2, 2)
            if anahtar in birik:
                birik[anahtar] = g2 @ birik[anahtar]
            else:
                birik[anahtar] = g2
                sira.append(anahtar)
        for anahtar in sira:
            self.bit_kapisi(anahtar[0], anahtar[1], birik[anahtar])

    def cift(self, yuva: int, G: np.ndarray, baglar=None) -> None:
        self.uzak_cift(int(yuva), int(yuva) + 1, G, baglar=baglar)

    def _bolum(self, k: int) -> Tuple[int, int]:
        c = self._bolum_onbellek.get(int(k))
        if c is not None:
            return c
        lif = tuple(self.ayar.lif)
        on = 1
        for x in lif[:k]:
            on *= int(x)
        ard = 1
        for x in lif[k + 1:]:
            ard *= int(x)
        c = (on, ard)
        self._bolum_onbellek[int(k)] = c
        return c

    def cift_bit_kapisi(self, ki: int, ai: int, kj: int, aj: int,
                        G: np.ndarray, baglar=None) -> None:
        self._cift_kapisi_lifli(ki, ai, kj, aj, G, baglar=baglar)

    def uzak_cift(self, i: int, j: int, G: np.ndarray,
                  baglar=None) -> None:
        if not (self.gecerli(i) and self.gecerli(j)):
            self._dusen_kapi += 1
            if baglar:
                self.iz.uretecsiz += len(baglar)
            return
        G = np.asarray(G, complex).reshape(4, 4)
        ki, ai = self._lif_no(int(i))
        kj, aj = self._lif_no(int(j))
        lif = tuple(self.ayar.lif)
        if self._ikinin_kuvveti:
            self.cift_bit_kapisi(ki, ai, kj, aj, G, baglar=baglar)
            return
        if ki == kj:
            n = lif[ki]
            bi, bj = 1 << ai, 1 << aj
            if bi >= n or bj >= n or bi == bj:
                if baglar:
                    self.iz.uretecsiz += len(baglar)
                return
            M = np.eye(n, dtype=complex)
            for x in range(n):
                if (x & bi) or (x & bj):
                    continue
                idx = [x, x | bj, x | bi, x | bi | bj]
                for a in range(4):
                    for b in range(4):
                        M[idx[a], idx[b]] = G[a, b]
            self.lif_kapisi(ki, M)
            return
        ni, nj = lif[ki], lif[kj]
        bi, bj = 1 << ai, 1 << aj
        if bi >= ni or bj >= nj:
            if baglar:
                self.iz.uretecsiz += len(baglar)
            return
        T = self.lifli
        T = np.moveaxis(T, (ki + 1, kj + 1), (-2, -1))
        sekil = T.shape
        F = T.reshape(-1, ni, nj)
        Mi = np.eye(ni, dtype=complex)
        Mj = np.eye(nj, dtype=complex)
        for x in range(ni):
            if x & bi:
                continue
            for y in range(nj):
                if y & bj:
                    continue
                idx = [(x, y), (x, y | bj), (x | bi, y), (x | bi, y | bj)]
                v = np.stack([F[:, a, b] for a, b in idx], axis=1)
                v = v @ G.T
                for m, (a, b) in enumerate(idx):
                    F[:, a, b] = v[:, m]
        T = F.reshape(sekil)
        self.iz.kapi_yaz("çift_lif", (int(ki), int(kj), int(bi), int(bj)), G)
        self.psi = np.moveaxis(T, (-2, -1), (ki + 1, kj + 1)).reshape(
            self.B, self.d)
        self._kapi += 1
        self.iz.kapi += 1

    def mpo_uygula(self, W, D: int = 2, bas: int = 0, son=None,
                   sol_sinir=None, sag_sinir=None) -> float:
        if not isinstance(W, dict) or not W:
            return 0.0
        lif = tuple(self.ayar.lif)
        sira: List[Tuple[int, int]] = []
        birik: Dict[Tuple[int, int], np.ndarray] = {}
        for yuva, Wk in W.items():
            Wk = np.asarray(Wk)
            k, alt = self._lif_no(int(yuva))
            if Wk.ndim == 4:
                G = Wk[0, :, :, 0]
            elif Wk.ndim == 2 and Wk.shape == (2, 2):
                G = Wk
            else:
                continue
            if not self.gecerli(int(yuva)):
                self._dusen_kapi += 1
                continue
            G = np.asarray(G, complex).reshape(2, 2)
            if not np.any(G):
                continue
            if (abs(G[0, 0] - 1.0) < 1e-12 and abs(G[1, 1] - 1.0) < 1e-12
                    and abs(G[0, 1]) < 1e-12 and abs(G[1, 0]) < 1e-12):
                continue
            anahtar = (int(k), int(alt))
            g2 = np.asarray(G, complex).reshape(2, 2)
            if anahtar in birik:
                birik[anahtar] = g2 @ birik[anahtar]
            else:
                birik[anahtar] = g2
                sira.append(anahtar)
        for anahtar in sira:
            self.bit_kapisi(anahtar[0], anahtar[1], birik[anahtar])
        self.normalize()
        return 0.0

    def mpo_uygula_hizli(self, *a, **k) -> float:
        return self.mpo_uygula(*a, **k)

    def _mpo_adresleri(self, alan: str, kac: int, duraklar, j: int
                       ) -> np.ndarray:
        if duraklar is not None:
            d = np.asarray(list(duraklar), np.int64).reshape(-1)
            assert d.size, "durak listesi boş verilemez -- adres yoksa faz "\
                           "kime vurulacak (ferman 5)"
            assert int(d.min()) >= 0 and int(d.max()) < self.d, (
                "durak adresi yazmacın dışında: [%d, %d] ⊄ [0, %d)"
                % (int(d.min()), int(d.max()), self.d))
            return d
        i, jj = self.sektor(alan)
        kat = int(dict(self.ayar.kulli_alanlar).get(alan, 1))
        boy = max(1, (jj - i) // max(1, kat))
        bas = i + (int(j) % max(1, kat)) * boy
        son = min(jj, bas + boy)
        d = np.arange(bas, son, dtype=np.int64)
        return d if d.size else np.arange(i, jj, dtype=np.int64)

    def _faz_bagla(self, dizin: np.ndarray, baglar) -> None:
        if not self.iz.senet_acik or not baglar:
            return
        self._faz_indir()
        no = self.iz.son_senet
        if no < 0 or str(self.iz.senet[no][0]) != "faz":
            self.iz.uretecsiz += len(baglar)
            return
        q = np.asarray(self.iz.senet[no][2], np.int64)
        q = q[0] if q.ndim == 2 else q
        vur = np.power(1j, q[dizin])
        for (par, olcek, pay) in baglar:
            deger = 1j * np.asarray(pay, float) * vur
            self.iz.bag_yaz(no, int(par), float(olcek),
                            ("köşegen", dizin.copy(), deger))

    def _mpo(self, alan: str, acilar, duraklar, j: int, par, olcek: float,
             bol: bool, egim=None, bag=None) -> float:
        if alan not in self._sektor:
            return 0.0
        a = np.asarray(acilar if acilar is not None else [0.0],
                       float).reshape(-1)
        dizin = self._mpo_adresleri(alan, a.size, duraklar, int(j))
        sira = np.arange(dizin.size) % a.size
        bolen = float(dizin.size) if bol else 1.0
        t = np.zeros(self.d, float)
        np.add.at(t, dizin, -a[sira] / bolen)
        self.faz(t)
        if bag is not None:
            self._faz_bagla(dizin, list(bag))
            return 0.0
        if par is None:
            return 0.0
        pid = np.asarray(par, np.int64).reshape(-1)
        assert pid.size == a.size, (
            "her açının kendi parametresi olmalı: %d açı, %d parametre "
            "(ferman 1-C/b: isim yazmak bağlamak değildir)"
            % (a.size, pid.size))
        e = (np.ones(a.size, float) if egim is None
             else np.asarray(egim, float).reshape(-1))
        assert e.size == a.size, (
            "eğim tarifi açı sayısınca olmalı: %d ≠ %d" % (e.size, a.size))
        self._faz_bagla(
            dizin, [(int(pid[k]), float(olcek),
                     np.where(sira == k, e[sira] / bolen, 0.0))
                    for k in range(a.size)])
        return 0.0

    def mpo_topla(self, alan: str, acilar=None, duraklar=None, j: int = 0,
                  par=None, olcek: float = 1.0, egim=None, bag=None
                  ) -> float:
        return self._mpo(alan, acilar, duraklar, j, par, olcek, False,
                         egim, bag)

    def mpo_dagit(self, alan: str, acilar=None, duraklar=None, j: int = 0,
                  par=None, olcek: float = 1.0, egim=None, bag=None
                  ) -> float:
        return self._mpo(alan, acilar, duraklar, j, par, olcek, True,
                         egim, bag)

    def rapor(self) -> str:
        o = self.olcumler()
        s = ["=== QUDİT YAZMACI (MPS'in yerine) ===", "",
             "  d              : %d  (%.1f KB, TAM tutulur)"
             % (self.d, self.d * 16 / 1024),
             "  lifler         : %s" % (self.ayar.lif,),
             "  yığın          : %d" % self.B,
             "  norm hatası    : %.3e" % self.norm_hatasi(),
             "  entropi (kesit): %.6f" % o["entropi"],
             "  vurulan kapı   : %d" % self._kapi,
             "  sadakat log    : %.1f  (kesme yok → tam sıfır)"
             % self.sadakat_log(),
             "", "  SEKTÖRLER (eski küllî alanların yerine):"]
        for ad, (i, j) in self._sektor.items():
            s.append("    %-9s [%4d–%4d]  ağırlık %.6f"
                     % (ad, i, j, float(np.ravel(o[ad])[0])))
        return "\n".join(s)
# ==== BİTTİ: kuantum/qyazmac.py ====

# ==== BAŞLIYOR: kuantum/stabilizer.py ====
from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

import numpy as np

__all__ = ["StabilizerDurum", "StabilizerRank", "bgs_haddi"]

ALFA = 0.228


def bgs_haddi(t: int) -> float:
    return float(2.0 ** (ALFA * t))


@dataclass
class StabilizerDurum:
    n: int
    D: np.ndarray
    J: np.ndarray

    @staticmethod
    def arti(n: int) -> "StabilizerDurum":
        return StabilizerDurum(n, np.zeros(n, np.int64),
                               np.zeros((n, n), np.int64))

    def kopya(self) -> "StabilizerDurum":
        return StabilizerDurum(self.n, self.D.copy(), self.J.copy())

    def z(self, a: int) -> None:
        self.D[a] = (self.D[a] + 2) % 4

    def s(self, a: int) -> None:
        self.D[a] = (self.D[a] + 1) % 4

    def cz(self, a: int, b: int) -> None:
        i, j = (a, b) if a < b else (b, a)
        self.J[i, j] ^= 1

    def faz(self, Y: np.ndarray) -> np.ndarray:
        Y = np.atleast_2d(np.asarray(Y, np.int64))
        dogrusal = Y @ self.D
        ikili = np.einsum("bi,ij,bj->b", Y, self.J, Y, optimize=True)
        return (dogrusal + 2 * ikili) % 4

    def genlik(self, Y: np.ndarray) -> np.ndarray:
        q = self.faz(Y)
        return (1j ** q) * (2.0 ** (-0.5 * self.n))


class StabilizerRank:

    def __init__(self, n: int) -> None:
        self.n = int(n)
        self.terimler: List[Tuple[complex, StabilizerDurum]] = [
            (1.0 + 0j, StabilizerDurum.arti(n))]
        self.t_sayisi = 0
        self.budama_hatasi = 0.0

    def __len__(self) -> int:
        return len(self.terimler)

    def genlik(self, Y: np.ndarray) -> np.ndarray:
        Y = np.atleast_2d(np.asarray(Y, np.int64))
        top = np.zeros(len(Y), complex)
        for c, f in self.terimler:
            top = top + c * f.genlik(Y)
        return top

    def z(self, a: int) -> None:
        for _, f in self.terimler:
            f.z(a)

    def s(self, a: int) -> None:
        for _, f in self.terimler:
            f.s(a)

    def cz(self, a: int, b: int) -> None:
        for _, f in self.terimler:
            f.cz(a, b)

    def t(self, a: int) -> None:
        e = np.exp(1j * math.pi / 4)
        beta = (e - 1.0) / (1j - 1.0)
        alfa = 1.0 - beta
        yeni: List[Tuple[complex, StabilizerDurum]] = []
        for c, f in self.terimler:
            g = f.kopya()
            g.s(a)
            yeni.append((c * alfa, f))
            yeni.append((c * beta, g))
        self.terimler = yeni
        self.t_sayisi += 1

    def budama(self, chi: int, Y_olcum: Optional[np.ndarray] = None
               ) -> float:
        if len(self.terimler) <= chi:
            return 0.0
        sira = sorted(range(len(self.terimler)),
                      key=lambda i: -abs(self.terimler[i][0]))
        tut = sira[:chi]
        at = sira[chi:]
        atilan = float(sum(abs(self.terimler[i][0]) ** 2 for i in at))
        self.terimler = [self.terimler[i] for i in tut]
        self.budama_hatasi += atilan
        return atilan

    def seyreklestir(self, k: int, tohum: int = 0) -> Dict[str, float]:
        rng = np.random.default_rng(tohum)
        c = np.array([t[0] for t in self.terimler], complex)
        l1 = float(np.abs(c).sum())
        if l1 <= 0.0 or k <= 0:
            return {"k": float(k), "l1": l1, "had": float("inf")}
        p = np.abs(c) / l1
        sec = rng.choice(len(c), size=int(k), replace=True, p=p)
        yeni: Dict[int, complex] = {}
        for j in sec:
            faz = c[j] / abs(c[j])
            yeni[int(j)] = yeni.get(int(j), 0j) + (l1 / k) * faz
        self.terimler = [(v, self.terimler[j][1]) for j, v in yeni.items()]
        return {"k": float(k), "l1": l1, "had": float(l1 * l1 / k),
                "ayrık_terim": float(len(self.terimler))}

    def durum(self) -> Dict[str, float]:
        return {"kübit": float(self.n), "rank": float(len(self.terimler)),
                "t_kapısı": float(self.t_sayisi),
                "bgs_haddi": bgs_haddi(self.t_sayisi),
                "budama_hatası": self.budama_hatasi,
                "bellek_bayt": float(sum(f.D.nbytes + f.J.nbytes
                                         for _, f in self.terimler)),
                "açık_dizi_bayt_log2": float(self.n + 4)}


def _gosterim() -> str:
    rng = np.random.default_rng(0)
    n = 14
    Y = rng.integers(0, 2, size=(400, n))
    s = ["=== Stabilizer rank: dolaşıklık BEDAVA, magic PAHALI ==="]

    S = StabilizerRank(n)
    for _ in range(60):
        a, b = rng.choice(n, 2, replace=False)
        S.cz(int(a), int(b))
        S.s(int(rng.integers(n)))
    g = S.genlik(Y)
    s += ["",
          "1) 60 Clifford kapısı (CZ + S) sonrası:",
          "   rank = %d   bellek = %d bayt   açık dizi olsaydı = 2^%d karmaşık"
          % (len(S), int(S.durum()["bellek_bayt"]), n),
          "   |genlik| hepsi eşit mi (Clifford yörüngesi şartı): sapma %.2e"
          % float(np.abs(np.abs(g) - 2.0 ** (-n / 2)).max()),
          "   norm² (400 örnekten kestirim × 2^n): %.6f"
          % float((np.abs(g) ** 2).mean() * 2 ** n)]

    s += ["", "2) T kapısı eklendikçe rank (tam ayrışım, budama yok):",
          "   t   rank      BGS haddi 2^0,228t   tam devre 2^t"]
    S2 = StabilizerRank(n)
    for t in range(1, 13):
        S2.t(int(rng.integers(n)))
        if t in (1, 2, 4, 6, 8, 10, 12):
            s.append("   %-3d %-9d %-19.2f %d"
                     % (t, len(S2), bgs_haddi(t), 2 ** t))

    s += ["", "3) Budama: rank χ'ya inince genlik hatası",
          "   χ    tutulan   atılan ağırlık   ‖Δgenlik‖/‖genlik‖"]
    tam = None
    for chi in (4096, 64, 16, 8, 4, 2, 1):
        S3 = StabilizerRank(n)
        rng2 = np.random.default_rng(5)
        for _ in range(12):
            S3.t(int(rng2.integers(n)))
        at = S3.budama(chi)
        gg = S3.genlik(Y)
        if tam is None:
            tam = gg
            s.append("   %-4d %-9d %-16.3e %s" % (chi, len(S3), at, "(esas)"))
        else:
            s.append("   %-4d %-9d %-16.3e %.3e"
                     % (chi, len(S3), at,
                        float(np.linalg.norm(gg - tam)
                              / (np.linalg.norm(tam) + 1e-300))))

    s += ["", "4) Bravyi–Gosset rastgele seyrekleştirmesi (aynı devre):",
          "   k     ayrık terim   ‖Δgenlik‖²/‖genlik‖²   nazarî had ‖c‖₁²/k"]
    r: Dict[str, float] = {"l1": float("nan")}
    for k in (16, 64, 256, 1024, 4096, 16384):
        S4 = StabilizerRank(n)
        rng3 = np.random.default_rng(5)
        for _ in range(12):
            S4.t(int(rng3.integers(n)))
        r = S4.seyreklestir(k, tohum=1)
        gg = S4.genlik(Y)
        hata = float(np.linalg.norm(gg - tam) ** 2
                     / (np.linalg.norm(tam) ** 2 + 1e-300))
        s.append("   %-5d %-13d %-22.3e %.3e"
                 % (k, int(r["ayrık_terim"]), hata, r["had"]))
    s.append("   (‖c‖₁ = %.3f; had ℓ₂'ye değil ℓ₁'e bağlıdır)" % r["l1"])

    s += ["",
          "Hüküm: Clifford kapıları rankı HİÇ büyütmüyor (60 kapı → rank 1);",
          "rank yalnız T ile büyüyor. Bu, MPS'in tam tersidir: orada 60",
          "dolaştırıcı kapı χ'yı patlatırdı. Bedel, temsil edilen sınıfın",
          "dar olmasıdır -- H yoktur ve olduğu iddia edilmiyor."]
    return "\n".join(s)
# ==== BİTTİ: kuantum/stabilizer.py ====

# ==== BAŞLIYOR: kuantum/surekli.py ====

from __future__ import annotations

import math
from typing import Dict, Optional, Tuple

import numpy as np

__all__ = [
    "yok_et", "yarat", "sayi", "konum", "momentum",
    "yer_degistirme", "sikistirma", "isik_bolucu", "kerr", "kubik_faz",
    "kesirsel_fourier", "tutarli_durum", "vakum", "fock",
    "foton_dagilimi", "kuadratur_belirsizligi",
    "komutator_sapmasi", "uniterlik_sapmasi", "kesme_hatasi",
]

HBAR = 1.0


def expm(A: np.ndarray) -> np.ndarray:
    A = np.asarray(A, complex)
    H = 1j * A
    sapma = float(np.abs(H - H.conj().T).max())
    if sapma > 1e-9 * max(1.0, float(np.abs(H).max())):
        raise ValueError("üreteç ters-Hermityen değil (sapma %.3e)" % sapma)
    H = 0.5 * (H + H.conj().T)
    lam, V = np.linalg.eigh(H)
    return (V * np.exp(-1j * lam)) @ V.conj().T


def yok_et(N: int) -> np.ndarray:
    return np.diag(np.sqrt(np.arange(1, N)), 1).astype(complex)


def yarat(N: int) -> np.ndarray:
    return yok_et(N).conj().T


def sayi(N: int) -> np.ndarray:
    return np.diag(np.arange(N)).astype(complex)


def konum(N: int, hbar: float = HBAR) -> np.ndarray:
    a = yok_et(N)
    return math.sqrt(hbar / 2.0) * (a + a.conj().T)


def momentum(N: int, hbar: float = HBAR) -> np.ndarray:
    a = yok_et(N)
    return -1j * math.sqrt(hbar / 2.0) * (a - a.conj().T)


def komutator_sapmasi(N: int) -> Dict[str, object]:
    a = yok_et(N)
    C = a @ a.conj().T - a.conj().T @ a - np.eye(N)
    return {
        "boyut": N,
        "alt_blok_azamî_sapma": float(np.abs(C[:N - 1, :N - 1]).max()),
        "son_köşegen": complex(C[N - 1, N - 1]),
        "beklenen_son_köşegen": complex(-N),
        "not": "kesme hatası son satırda toplanır; alt blok temizdir",
    }


def yer_degistirme(alpha: complex, N: int) -> np.ndarray:
    a = yok_et(N)
    return expm(alpha * a.conj().T - np.conj(alpha) * a)


def sikistirma(z: complex, N: int) -> np.ndarray:
    a = yok_et(N)
    return expm(0.5 * (np.conj(z) * (a @ a)
                       - z * (a.conj().T @ a.conj().T)))


def isik_bolucu(theta: float, phi: float, N: int) -> np.ndarray:
    a = yok_et(N)
    I = np.eye(N, dtype=complex)
    a1, a2 = np.kron(a, I), np.kron(I, a)
    G = (np.exp(1j * phi) * (a1.conj().T @ a2)
         - np.exp(-1j * phi) * (a1 @ a2.conj().T))
    return expm(theta * G)


def kesirsel_fourier(a_kuvvet: float, N: int) -> np.ndarray:
    n = np.arange(N)
    return np.diag(np.exp(-1j * a_kuvvet * (math.pi / 2) * (n + 0.5)))


def kerr(kappa: float, N: int) -> np.ndarray:
    n = np.arange(N)
    return np.diag(np.exp(1j * kappa * n * n))


def kubik_faz(gamma: float, N: int, hbar: float = HBAR) -> np.ndarray:
    x = konum(N, hbar)
    return expm(1j * gamma / (3.0 * hbar) * (x @ x @ x))


def vakum(N: int) -> np.ndarray:
    v = np.zeros(N, dtype=complex)
    v[0] = 1.0
    return v


def fock(n: int, N: int) -> np.ndarray:
    v = np.zeros(N, dtype=complex)
    v[n] = 1.0
    return v


def tutarli_durum(alpha: complex, N: int) -> np.ndarray:
    n = np.arange(N)
    log_c = n * np.log(abs(alpha) + 1e-300) - 0.5 * _log_faktoriyel(n)
    faz = np.exp(1j * np.angle(alpha) * n)
    v = np.exp(log_c - abs(alpha) ** 2 / 2.0) * faz
    if abs(alpha) == 0:
        v = vakum(N)
    return v.astype(complex)


def _log_faktoriyel(n: np.ndarray) -> np.ndarray:
    return np.array([math.lgamma(float(k) + 1.0) for k in n])


def foton_dagilimi(psi: np.ndarray) -> np.ndarray:
    return np.abs(psi) ** 2


def kuadratur_belirsizligi(psi: np.ndarray, hbar: float = HBAR
                           ) -> Dict[str, float]:
    N = len(psi)
    x, p = konum(N, hbar), momentum(N, hbar)

    def mom(A):
        o1 = complex(psi.conj() @ (A @ psi)).real
        o2 = complex(psi.conj() @ (A @ A @ psi)).real
        return math.sqrt(max(o2 - o1 * o1, 0.0))

    dx, dp = mom(x), mom(p)
    return {"Δx": dx, "Δp": dp, "çarpım": dx * dp,
            "alt_sınır": hbar / 2.0, "sağlanıyor": dx * dp >= hbar / 2 - 1e-9}


def uniterlik_sapmasi(U: np.ndarray, alt: Optional[int] = None) -> float:
    V = U if alt is None else U[:alt, :alt]
    W = U.conj().T @ U
    W = W if alt is None else W[:alt, :alt]
    return float(np.abs(W - np.eye(W.shape[0])).max())


def kesme_hatasi(uret, N: int, kat: int = 2, alt: Optional[int] = None
                 ) -> Dict[str, float]:
    k = alt if alt is not None else N // 2
    A = np.asarray(uret(N))[:k, :k]
    B = np.asarray(uret(kat * N))[:k, :k]
    return {
        "alt_blok": k, "N": N, "büyük_N": kat * N,
        "azamî_fark": float(np.abs(A - B).max()),
        "bağıl_fark": float(np.abs(A - B).max()
                            / max(np.abs(B).max(), 1e-300)),
    }


def _gosterim() -> str:
    s = []
    s.append("=== [a,a†] = I kesmede SAĞLANMAZ ===")
    for N in (8, 16, 64):
        r = komutator_sapmasi(N)
        s.append("  N=%3d  alt blok sapma=%.2e   son köşegen=%+.1f "
                 "(beklenen %+.1f)"
                 % (N, r["alt_blok_azamî_sapma"], r["son_köşegen"].real,
                    r["beklenen_son_köşegen"].real))
    s.append("  Kesme hatası son satırda toplanıyor; hüküm hep")
    s.append("  düşük foton bloğunda veriliyor.")

    s.append("\n=== D(α)|0⟩ kapalı tutarlı durumla uyuşuyor mu? ===")
    N = 60
    for al in (0.5, 1.0, 2.0, 4.0):
        psi = yer_degistirme(al, N) @ vakum(N)
        fark = float(np.abs(psi - tutarli_durum(al, N)).max())
        pd = foton_dagilimi(psi)
        s.append("  α=%.1f  azamî fark=%.2e   ⟨n⟩=%.4f (|α|²=%.4f)"
                 % (al, fark, float(pd @ np.arange(N)), al * al))
    s.append("  Foton sayısı Poisson: ⟨n⟩ = |α|², iki yol da aynı yere varıyor.")

    s.append("\n=== Üniterlik kesmede BOZULMUYOR (yanlış yazmıştım) ===")
    for N in (20, 40, 80):
        U = yer_degistirme(3.0, N)
        s.append("  α=3, N=%3d  ‖U†U−I‖=%.2e" % (N, uniterlik_sapmasi(U)))
    s.append("  Üreteç ters-Hermityen olduğundan üsteli her boyutta")
    s.append("  üniterdir. Kesmenin bedeli üniterlik değil, operatörün")
    s.append("  kendisidir; o da aşağıda iki kesme kıyaslanarak ölçülüyor.")

    s.append("\n=== Sıkıştırma: S†(r) x̂ S(r) = e^{−r} x̂ ===")
    k = 12
    s.append("  (bağıl hata, ilk %d×%d blokta; N yeterli değilse BOZULUR)" % (k, k))
    s.append("  r      N=40      N=80     N=160     N=320   Δx(N=320)  e^{−r}/√2")
    for r in (0.5, 1.0, 1.5, 2.0):
        hat = []
        for N in (40, 80, 160, 320):
            S = sikistirma(r, N)
            sol = (S.conj().T @ konum(N) @ S)[:k, :k]
            sag = (math.exp(-r) * konum(N))[:k, :k]
            hat.append(float(np.abs(sol - sag).max() / np.abs(sag).max()))
        b = kuadratur_belirsizligi(sikistirma(r, 320) @ vakum(320))
        s.append("  %.1f  %8.1e  %8.1e  %8.1e  %8.1e   %.6f   %.6f"
                 % (r, hat[0], hat[1], hat[2], hat[3], b["Δx"],
                    math.exp(-r) / math.sqrt(2)))
    s.append("  Gereken N, r ile hızla büyüyor: r=0.5'te 80 yeter,")
    s.append("  r=1.5'te 320 gerekir, r=2.0'de 320 bile yetmez.")
    b = kuadratur_belirsizligi(sikistirma(1.0, 320) @ vakum(320))
    s.append("  Sıkıştırma belirsizlik ÇARPIMINI değiştirmiyor:")
    s.append("  r=1.0, N=320: ΔxΔp=%.6f (alt sınır ħ/2=%.6f)"
             % (b["çarpım"], b["alt_sınır"]))

    s.append("\n=== Işık bölücü: foton sayısı korunuyor ===")
    N = 12
    a = yok_et(N)
    I = np.eye(N, dtype=complex)
    Ntop = np.kron(a.conj().T @ a, I) + np.kron(I, a.conj().T @ a)
    for th in (0.3, math.pi / 4, 1.2):
        B = isik_bolucu(th, 0.4, N)
        psi = np.kron(fock(1, N), fock(0, N))
        out = B @ psi
        n_once = complex(psi.conj() @ (Ntop @ psi)).real
        n_sonra = complex(out.conj() @ (Ntop @ out)).real
        p2 = abs(out[np.ravel_multi_index((0, 1), (N, N))]) ** 2
        s.append("  θ=%.3f  ⟨n⟩ %.6f → %.6f   |⟨0,1|out⟩|²=%.6f "
                 "(sin²θ=%.6f)"
                 % (th, n_once, n_sonra, p2, math.sin(th) ** 2))

    s.append("\n=== Kerr KÖŞEGEN: kesme hatası YOK ===")
    for N in (8, 32, 128):
        s.append("  N=%3d  ‖K†K−I‖=%.2e" % (N, uniterlik_sapmasi(kerr(0.7, N))))
    s.append("  Kesme hatası operatörün BİÇİMİNE bağlı, tek bir sayıya değil.")

    s.append("\n=== Kübik faz: yakınsama γ'ya bağlı (ölçülerek) ===")
    s.append("  γ      N=20→40   N=40→80  N=80→160   (ilk 6×6 blok)")
    for g in (0.1, 0.5, 2.0):
        h = [kesme_hatasi(lambda n, g=g: kubik_faz(g, n), N, alt=6)["azamî_fark"]
             for N in (20, 40, 80)]
        s.append("  %.1f  %8.1e  %8.1e  %8.1e" % (g, h[0], h[1], h[2]))
    s.append("  Küçük γ ucuz, büyük γ pahalı: γ=2'de N=160 bile yetmiyor.")
    s.append("  Kıyas için D(1.0) aynı ölçütle:")
    h = [kesme_hatasi(lambda n: yer_degistirme(1.0, n), N, alt=6)["azamî_fark"]
         for N in (20, 40, 80)]
    s.append("       %8.1e  %8.1e  %8.1e" % (h[0], h[1], h[2]))

    s.append("\n=== Kesirsel Fourier: grup özelliği TAM ===")
    N = 64
    for a1, b1 in ((0.3, 0.7), (1.0, 1.0), (2.5, -0.5)):
        L = kesirsel_fourier(a1, N) @ kesirsel_fourier(b1, N)
        R = kesirsel_fourier(a1 + b1, N)
        s.append("  F^%.1f F^%.1f vs F^%.1f : azamî fark=%.2e"
                 % (a1, b1, a1 + b1, float(np.abs(L - R).max())))
    F = kesirsel_fourier(1.0, N)
    k = 32
    sol = (F.conj().T @ konum(N) @ F)[:k, :k]
    s.append("  a=1'de F† x̂ F = p̂ mi? azamî fark=%.2e"
             % float(np.abs(sol - momentum(N)[:k, :k]).max()))
    return "\n".join(s)
