def _dallari_act(dallar, s):
    yeni = []
    for dal in dallar:
        k = Kofibrasyon([dal[0]]).yerine_koy(s)
        if k.bos_mu():
            continue
        geri = tuple(_act(x, s) for x in dal[1:])
        for f in k.yuzler:
            yeni.append((f,) + geri)
    return tuple(yeni)


