# ==== BAŞLIYOR: nefs/belirtec.py ====
from __future__ import annotations

import hashlib
import os
import shutil
import subprocess
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np

__all__ = ["Kodlama", "KODLAMALAR", "belirtec_kapisi", "belirtec_sozlugu",
           "basamak_sayisi", "tip_vektoru", "tipten", "belirtec_beyani",
           "BPE_DEPOSU", "onbellek_dizini"]

BPE_DEPOSU = "zurawiki/tiktoken-rs"
BPE_YOLU = "tiktoken-rs/assets"


@dataclass(frozen=True)
class Kodlama:

    ad: str
    blobpath: str
    ozet: str
    dosya: str


KODLAMALAR: Tuple[Kodlama, ...] = (
    Kodlama(ad="o200k_base",
            blobpath="https://openaipublic.blob.core.windows.net/"
                     "encodings/o200k_base.tiktoken",
            ozet="446a9538cb6c348e3516120d7c08b09f57c36495"
                 "e2acfffe59a5bf8b0cfb1a2d",
            dosya="o200k_base.tiktoken"),
    Kodlama(ad="cl100k_base",
            blobpath="https://openaipublic.blob.core.windows.net/"
                     "encodings/cl100k_base.tiktoken",
            ozet="223921b76ee99bde995b7ff738513eef100fb51d"
                 "18c93597a113bcffe865b2a7",
            dosya="cl100k_base.tiktoken"),
)

_KAPI_SABIT: Dict[str, Any] = {}
_SAYAC: Dict[str, float] = {"kodlama": 0.0, "coz": 0.0, "belirtec": 0.0,
                            "yerlestirme": 0.0}


def onbellek_dizini() -> str:
    d = os.environ.get("TIKTOKEN_CACHE_DIR") \
        or os.environ.get("DATA_GYM_CACHE_DIR")
    if not d:
        d = os.path.join(os.environ.get("MUCIT_KULLIYAT", "depo/kulliyat"),
                         "tiktoken")
        os.environ["TIKTOKEN_CACHE_DIR"] = d
    os.makedirs(d, exist_ok=True)
    return d


def _kodlama(ad: str) -> Kodlama:
    for k in KODLAMALAR:
        if k.ad == ad:
            return k
    raise ValueError(
        "bilinmeyen kodlama %r; yoklanmışlar: %s"
        % (ad, ", ".join(k.ad for k in KODLAMALAR)))


def bpe_yerlestir(ad: str) -> Dict[str, Any]:
    k = _kodlama(ad)
    onb = onbellek_dizini()
    anahtar = hashlib.sha1(k.blobpath.encode()).hexdigest()
    hedef = os.path.join(onb, anahtar)
    if os.path.isfile(hedef) and os.path.getsize(hedef) > 0:
        return {"kodlama": ad, "yol": hedef, "yerleştirildi": False,
                "bayt": os.path.getsize(hedef)}
    kok = os.path.join(onb, "_bpe_deposu")
    if not os.path.isdir(os.path.join(kok, ".git")):
        shutil.rmtree(kok, ignore_errors=True)
        r = subprocess.run(
            ["git", "clone", "--depth", "1", "--filter=blob:none",
             "https://github.com/" + BPE_DEPOSU, kok],
            capture_output=True, text=True,
            env=dict(os.environ, GIT_LFS_SKIP_SMUDGE="1"), timeout=1800)
        assert r.returncode == 0, (
            "BPE tablosu alınamadı -- belirteçleyici olmadan tâlim "
            "başlayamaz.\n  depo : %s\n  sebep: %s\n"
            "  (tiktoken'in kendi adresi bu kapta kapalı: "
            "openaipublic.blob.core.windows.net → 000)"
            % (BPE_DEPOSU, (r.stderr or "").strip()[-300:]))
    kaynak = os.path.join(kok, BPE_YOLU, k.dosya)
    if not os.path.isfile(kaynak):
        r = subprocess.run(["git", "-C", kok, "checkout", "HEAD", "--",
                            os.path.join(BPE_YOLU, k.dosya)],
                           capture_output=True, text=True, timeout=900)
        assert r.returncode == 0 and os.path.isfile(kaynak), (
            "BPE dosyası depoda bulunamadı: %s/%s/%s -- %s"
            % (BPE_DEPOSU, BPE_YOLU, k.dosya, (r.stderr or "").strip()[-200:]))
    with open(kaynak, "rb") as f:
        ham = f.read()
    olculen = hashlib.sha256(ham).hexdigest()
    assert olculen == k.ozet, (
        "BPE tablosunun özeti tutmuyor -- bu, tiktoken'in beklediği "
        "tablo DEĞİLDİR.\n  beklenen: %s\n  ölçülen : %s\n  dosya   : %s"
        % (k.ozet, olculen, kaynak))
    gecici = hedef + ".yaz"
    with open(gecici, "wb") as f:
        f.write(ham)
    os.replace(gecici, hedef)
    _SAYAC["yerlestirme"] += 1.0
    return {"kodlama": ad, "yol": hedef, "yerleştirildi": True,
            "bayt": len(ham), "sha256": olculen}


def belirtec_kapisi(ad: str = "o200k_base"):
    if ad in _KAPI_SABIT:
        return _KAPI_SABIT[ad]
    bpe_yerlestir(ad)
    import tiktoken

    kod = tiktoken.get_encoding(ad)
    _KAPI_SABIT[ad] = kod
    return kod


def belirtec_sozlugu(ad: str = "o200k_base") -> int:
    return int(belirtec_kapisi(ad).n_vocab)


def basamak_sayisi(sozluk: int, taban: int) -> int:
    t, n, kap = max(2, int(taban)), 1, max(2, int(taban))
    while kap < int(sozluk):
        kap *= t
        n += 1
    return int(n)


def tip_vektoru(belirtecler: Sequence[int], taban: int, basamak: int
                ) -> np.ndarray:
    t = np.asarray(belirtecler, np.int64).reshape(-1)
    b, n = max(2, int(taban)), max(1, int(basamak))
    out = np.empty((t.size, n), np.int64)
    kalan = t.copy()
    for i in range(n):
        out[:, i] = kalan % b
        kalan //= b
    return out.reshape(-1)


def tipten(basamaklar: Sequence[int], taban: int, basamak: int
           ) -> np.ndarray:
    a = np.asarray(basamaklar, np.int64).reshape(-1, max(1, int(basamak)))
    b = max(2, int(taban))
    carp = b ** np.arange(a.shape[1], dtype=np.int64)
    return (a * carp[None, :]).sum(axis=1)


def belirtecle(metin, ad: str = "o200k_base") -> List[int]:
    kod = belirtec_kapisi(ad)
    if isinstance(metin, (bytes, bytearray)):
        metin = bytes(metin).decode("utf-8", "replace")
    t = kod.encode(str(metin), disallowed_special=())
    _SAYAC["kodlama"] += 1.0
    _SAYAC["belirtec"] += float(len(t))
    return list(t)


def coz(belirtecler: Sequence[int], ad: str = "o200k_base") -> str:
    _SAYAC["coz"] += 1.0
    n = int(belirtec_sozlugu(ad))
    ham = [int(x) for x in belirtecler]
    tasan = [t for t in ham if not (0 <= t < n)]
    _SAYAC["cozulen"] = _SAYAC.get("cozulen", 0.0) + float(len(ham))
    _SAYAC["tasan"] = _SAYAC.get("tasan", 0.0) + float(len(tasan))
    return belirtec_kapisi(ad).decode([t for t in ham if 0 <= t < n])


def belirtec_metni(b: Dict[str, Any]) -> str:
    if not b:
        return "  BELİRTEÇ: beyan yok -- ölçü kırmızı (ferman 5)"
    n = float(b.get("taşma_nispeti", 0.0))
    hal = ("taşma yok" if n <= 0.0 else
           "⚠ HER KİMLİK TAŞIYOR -- üretim kod uzayının dışında"
           if n >= 0.999 else "⚠ taşma var")
    return "\n".join([
        "  BELİRTEÇ -- TEK KAPI TİKTOKEN (ferman 1-N)",
        "    kodlama            : %s   (açık: %s)"
        % (b.get("kodlama"), b.get("açık")),
        "    sözlük (n_vocab)   : %d   ← yoklandı, elle yazılmadı"
        % int(b.get("sözlük", 0)),
        "    kodlanan belirteç  : %d   (çağrı %d)"
        % (int(b.get("belirteç", 0)), int(b.get("kodlama_çağrısı", 0))),
        "    KOD UZAYINA TAŞMA (ferman 1-I üçüncü hudut, 2-L):",
        "      çözülen kimlik   : %d" % int(b.get("çözülen_kimlik", 0)),
        "      taşan kimlik     : %d   nispet %.4f  → %s"
        % (int(b.get("taşan_kimlik", 0)), n, hal),
        "      Taşan kimlik artık SUSTURULMUYOR (evvelce sözlük",
        "      mertebesine göre katlanıyordu -- ferman 5 ihlâli); sayılıyor."])


def belirtec_beyani(ad: str = "o200k_base") -> Dict[str, Any]:
    acik = ad in _KAPI_SABIT
    return {"kodlama": ad, "açık": acik,
            "sözlük": int(_KAPI_SABIT[ad].n_vocab) if acik else 0,
            "kodlama_çağrısı": int(_SAYAC["kodlama"]),
            "çözme_çağrısı": int(_SAYAC["coz"]),
            "belirteç": int(_SAYAC["belirtec"]),
            "bpe_yerleştirme": int(_SAYAC["yerlestirme"]),
            "çözülen_kimlik": int(_SAYAC.get("cozulen", 0.0)),
            "taşan_kimlik": int(_SAYAC.get("tasan", 0.0)),
            "taşma_nispeti": float(_SAYAC.get("tasan", 0.0)
                                   / max(_SAYAC.get("cozulen", 0.0), 1.0)),
            "önbellek": onbellek_dizini()}
# ==== BİTTİ: nefs/belirtec.py ====

# ==== BAŞLIYOR: nefs/casimir.py ====
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np

__all__ = ["CasimirAyari", "casimir_yukleri", "dhr_ayrismasi",
           "gelfand_tsetlin_araya_girme", "kartan_fazi",
           "casimir_beyani", "casimir_sifirla"]


_CASIMIR: Dict[str, float] = {}


def casimir_sifirla() -> None:
    _CASIMIR.clear()
    _CASIMIR.update({"çağrı": 0.0, "sektör": 0.0, "azamî_sektör_payı": 0.0,
                     "sızıntı": 0.0, "araya_girme_ihlâli": 0.0,
                     "blok_köşegen_artığı": 0.0, "kartan_çağrısı": 0.0})


casimir_sifirla()


@dataclass
class CasimirAyari:
    acik: int = 1
    esik_payi: float = 0.0


def casimir_yukleri(lif: Sequence[int]) -> np.ndarray:
    lif = tuple(int(x) for x in lif)
    d = int(np.prod(lif))
    yuk = np.zeros(d, np.int64)
    ard = d
    for n in lif:
        ard //= int(n)
        eksen = (np.arange(d) // ard) % int(n)
        yuk += np.array([bin(int(v)).count("1") for v in range(int(n))],
                        np.int64)[eksen]
    return yuk


def dhr_ayrismasi(psi: np.ndarray, lif: Sequence[int],
                  ayar: Optional[CasimirAyari] = None) -> Dict[str, Any]:
    a = ayar or CasimirAyari()
    yuk = casimir_yukleri(lif)
    P = np.abs(np.asarray(psi, complex)) ** 2
    P = P / np.maximum(P.sum(axis=1, keepdims=True), 1e-300)
    q = np.unique(yuk)
    pay = np.stack([P[:, yuk == int(v)].sum(axis=1) for v in q], axis=1)
    ort = pay.mean(axis=0)
    _CASIMIR["çağrı"] += 1.0
    _CASIMIR["sektör"] = float(q.size)
    _CASIMIR["azamî_sektör_payı"] = float(ort.max()) if ort.size else 0.0
    sizinti = float(1.0 - ort.sum())
    _CASIMIR["sızıntı"] = abs(sizinti)
    return {"yük": q, "pay": pay, "ortalama_pay": ort,
            "sektör": int(q.size), "sızıntı": float(abs(sizinti)),
            "açık": bool(int(a.acik))}


def gelfand_tsetlin_araya_girme(pay: np.ndarray) -> Dict[str, Any]:
    m = np.asarray(pay, float)
    if m.ndim == 1:
        m = m[None, :]
    if m.shape[1] < 2:
        return {"ihlâl": 0, "denenen": 0, "nispet": 0.0}
    sirali = -np.sort(-m, axis=1)
    ihlal = 0
    denenen = 0
    for b in range(sirali.shape[0]):
        s = sirali[b]
        for i in range(s.size - 1):
            denenen += 1
            if s[i] + 1e-15 < s[i + 1]:
                ihlal += 1
    n = float(max(1, denenen))
    _CASIMIR["araya_girme_ihlâli"] = float(ihlal) / n
    return {"ihlâl": int(ihlal), "denenen": int(denenen),
            "nispet": float(ihlal) / n}


def kartan_fazi(lif: Sequence[int], acilar: Sequence[float]) -> np.ndarray:
    yuk = casimir_yukleri(lif)
    a = np.asarray(list(acilar), float).reshape(-1)
    if a.size == 0:
        return np.zeros(yuk.size, float)
    q = np.unique(yuk)
    tablo = np.zeros(int(q.max()) + 1, float)
    for i, v in enumerate(q):
        tablo[int(v)] = float(a[i % a.size])
    _CASIMIR["kartan_çağrısı"] += 1.0
    return -tablo[yuk]


def blok_kosegen_artigi(psi: np.ndarray, lif: Sequence[int]) -> float:
    yuk = casimir_yukleri(lif)
    v = np.asarray(psi, complex)
    q = np.unique(yuk)
    rho_ic = 0.0
    for s in q:
        m = yuk == int(s)
        rho_ic += float(np.sum(np.abs(v[:, m]) ** 2) ** 2)
    top = float(np.sum(np.abs(v) ** 2) ** 2)
    art = float(max(0.0, 1.0 - rho_ic / max(top, 1e-300)))
    _CASIMIR["blok_köşegen_artığı"] = art
    return art


def casimir_beyani() -> Dict[str, float]:
    return dict(_CASIMIR)
# ==== BİTTİ: nefs/casimir.py ====

# ==== BAŞLIYOR: nefs/derleyici.py ====
from __future__ import annotations

import hashlib
import os
import subprocess
import tempfile
from typing import Any, Dict, List, Optional, Sequence

__all__ = ["DERLEME_DIZINI", "ORTAK_BAYRAK", "ozet", "derle"]

DERLEME_DIZINI = os.environ.get(
    "MUCIT_DERLEME", os.path.join(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))), "depo", "derleme"))

ORTAK_BAYRAK: List[str] = ["-O3", "-fPIC"]

_ONBELLEK: Dict[str, Dict[str, Any]] = {}


def ozet(kaynak: str, bayrak: Sequence[str], ek: str = "") -> str:
    h = hashlib.sha256()
    h.update(kaynak.encode("utf-8"))
    h.update(" ".join(bayrak).encode("utf-8"))
    if ek:
        h.update(ek.encode("utf-8"))
    return h.hexdigest()[:16]


def derle(ad: str, kaynak: str, bayrak: Sequence[str],
          yoklama_kaynagi: Optional[str] = None) -> Dict[str, Any]:
    anahtar = ad
    c = _ONBELLEK.get(anahtar)
    if c is not None:
        return c
    os.makedirs(DERLEME_DIZINI, exist_ok=True)
    oz = ozet(kaynak, bayrak, yoklama_kaynagi or "")
    so = os.path.join(DERLEME_DIZINI, "%s_%s.so" % (ad, oz))
    prob = (os.path.join(DERLEME_DIZINI, "%s_%s.yokla" % (ad, oz))
            if yoklama_kaynagi else "")
    cc = os.environ.get("CC", "cc")
    o: Dict[str, Any] = {"ad": ad, "kaynak_özeti": oz, "so": so,
                         "yoklama_ikilisi": prob, "derleyici": cc,
                         "bayrak": " ".join(bayrak)}
    hazir = os.path.exists(so) and (not prob or os.path.exists(prob))
    if hazir:
        o["derlendi"] = True
        o["önbellekten"] = True
        _ONBELLEK[anahtar] = o
        return o
    ciktilar: List[str] = []
    kod = 0
    with tempfile.TemporaryDirectory() as td:
        kay = os.path.join(td, "%s.c" % ad)
        with open(kay, "w", encoding="utf-8") as f:
            f.write(kaynak)
        r = subprocess.run([cc] + list(bayrak) + ["-shared", "-o", so, kay],
                           capture_output=True, text=True)
        ciktilar.append(r.stderr or "")
        kod |= r.returncode
        if yoklama_kaynagi:
            yok = os.path.join(td, "yokla.c")
            with open(yok, "w", encoding="utf-8") as f:
                f.write(yoklama_kaynagi)
            r2 = subprocess.run([cc] + list(bayrak) + ["-o", prob, yok, kay],
                                capture_output=True, text=True)
            ciktilar.append(r2.stderr or "")
            kod |= r2.returncode
    o["derlendi"] = bool(kod == 0)
    o["derleyici_çıktısı"] = "".join(ciktilar)
    o["önbellekten"] = False
    _ONBELLEK[anahtar] = o
    return o
# ==== BİTTİ: nefs/derleyici.py ====

# ==== BAŞLIYOR: nefs/donanim.py ====
from __future__ import annotations

import os
import re
import subprocess
import time
from typing import Any, Dict, List, Optional

import numpy as np

__all__ = ["cekirdek_sayisi", "onbellekler", "saat_ghz", "simd_bilgisi",
           "bellek_bandi", "bellek_baytlari", "tamsayi_hizi",
           "bellek_haddi", "gpu_var_mi", "gpu_olcu", "hesap",
           "donanim", "rapor"]

_ONBELLEK: Dict[str, Any] = {}


def cekirdek_sayisi() -> int:
    try:
        return max(1, len(os.sched_getaffinity(0)))
    except AttributeError:
        return max(1, int(os.cpu_count() or 1))


def onbellekler() -> Dict[str, Optional[int]]:
    kok = "/sys/devices/system/cpu/cpu0/cache"
    o: Dict[str, Optional[int]] = {"L1d": None, "L2": None, "L3": None}
    if not os.path.isdir(kok):
        return o
    for d in sorted(os.listdir(kok)):
        yol = os.path.join(kok, d)
        if not d.startswith("index"):
            continue
        try:
            with open(os.path.join(yol, "level")) as f:
                sev = int(f.read().strip())
            with open(os.path.join(yol, "type")) as f:
                tip = f.read().strip()
            with open(os.path.join(yol, "size")) as f:
                ham = f.read().strip()
        except OSError:
            continue
        m = re.match(r"(\d+)([KMG]?)", ham)
        if not m:
            continue
        bayt = int(m.group(1)) * {"": 1, "K": 1024, "M": 1024 ** 2,
                                  "G": 1024 ** 3}[m.group(2)]
        ad = ("L1d" if sev == 1 and tip.startswith("Data")
              else ("L%d" % sev if sev > 1 else None))
        if ad in o and o[ad] is None:
            o[ad] = bayt
    return o


def saat_ghz() -> Dict[str, Optional[float]]:
    ilan: Optional[float] = None
    try:
        with open("/proc/cpuinfo") as f:
            met = f.read()
        m = re.search(r"model name.*?@\s*([\d.]+)\s*GHz", met)
        if m:
            ilan = float(m.group(1))
        else:
            m = re.search(r"cpu MHz\s*:\s*([\d.]+)", met)
            if m:
                ilan = float(m.group(1)) / 1000.0
    except OSError:
        pass
    x = np.uint64(1)
    n = 3_000_000
    t0 = time.perf_counter()
    for _ in range(n):
        x = x + np.uint64(1)
    sure = time.perf_counter() - t0
    return {"ilan_ghz": ilan, "tur_ns": float(sure / n * 1e9)}


def simd_bilgisi() -> Dict[str, Any]:
    from .gfni import cpuid, olc, yoklama
    y = yoklama()
    o: Dict[str, Any] = {
        "gfni_koşuyor": bool(y.get("koşuyor")),
        "gfni_sebep": y.get("sebep"),
        "cpuid_bayrağı": (y.get("cpuid") or {}),
        "derlendi": bool(y.get("derlendi")),
        "bayrak": y.get("bayrak"),
    }
    o["cpuid_ayrıştı"] = bool(
        o["gfni_koşuyor"] and not (o["cpuid_bayrağı"] or {}).get("GFNI", False))
    o["genişlik_bit"] = 512 if o["gfni_koşuyor"] else None
    g = olc() if o["gfni_koşuyor"] else {}
    o["gfni_gb"] = g.get("gfni_gb")
    o["tablo_gb"] = g.get("tablo_gb")
    o["gfni_hızı"] = g.get("hız")
    return o


def bellek_bandi(bayt: int = 1 << 26, tekrar: int = 5) -> Dict[str, float]:
    n = max(1 << 16, int(bayt) // 8)
    b = np.ones(n, np.float64)
    c = np.full(n, 2.0)
    a = np.empty(n, np.float64)
    s = 3.0
    np.add(b, s * c, out=a)
    t0 = time.perf_counter()
    for _ in range(int(tekrar)):
        np.add(b, s * c, out=a)
    sure = (time.perf_counter() - t0) / int(tekrar)
    trafik = 3.0 * n * 8.0
    return {"bayt": float(trafik), "sn": float(sure),
            "bant_gb": float(trafik / sure / 1e9)}


def bellek_baytlari() -> Dict[str, Optional[int]]:
    o: Dict[str, Optional[int]] = {"toplam": None, "erişilebilir": None,
                                   "kap_haddi": None, "kaynak": None}
    try:
        with open("/proc/meminfo") as f:
            m = {}
            for satir in f:
                ad, _, kalan = satir.partition(":")
                p = kalan.split()
                if p:
                    m[ad.strip()] = int(p[0]) * 1024
    except OSError:
        return o
    o["toplam"] = m.get("MemTotal")
    o["erişilebilir"] = m.get("MemAvailable", m.get("MemFree"))
    o["kaynak"] = "/proc/meminfo"
    for yol in ("/sys/fs/cgroup/memory.max",
                "/sys/fs/cgroup/memory/memory.limit_in_bytes"):
        try:
            with open(yol) as f:
                v = f.read().strip()
        except OSError:
            continue
        if v.isdigit() and int(v) < (1 << 62):
            o["kap_haddi"] = int(v)
            o["kaynak"] = yol
        break
    return o


def bellek_haddi() -> Optional[int]:
    b = bellek_baytlari()
    aday = [x for x in (b["erişilebilir"], b["kap_haddi"]) if x]
    return int(min(aday)) if aday else None


def tamsayi_hizi(satir: int = 4096, kelime: int = 64,
                 tekrar: int = 20) -> Dict[str, Any]:
    from .gfni import symplectic_gfni, yoklama
    r = np.random.default_rng(0)
    X = r.integers(0, 1 << 62, size=(satir, kelime), dtype=np.uint64)
    Z = r.integers(0, 1 << 62, size=(satir, kelime), dtype=np.uint64)
    m = r.integers(0, 1 << 62, size=kelime, dtype=np.uint64)
    f = r.integers(0, 1 << 62, size=kelime, dtype=np.uint64)
    bayt = float(X.nbytes + Z.nbytes) * 2.0
    donanim_var = bool(yoklama().get("koşuyor"))
    if donanim_var:
        symplectic_gfni(X, Z, m, f)
        t0 = time.perf_counter()
        for _ in range(int(tekrar)):
            symplectic_gfni(X, Z, m, f)
        sure = (time.perf_counter() - t0) / int(tekrar)
        usul = "AVX-512 XOR/AND/POPCNT (C, ctypes)"
    else:
        t0 = time.perf_counter()
        for _ in range(int(tekrar)):
            X ^= m[None, :]
            Z ^= (X & f[None, :])
        sure = (time.perf_counter() - t0) / int(tekrar)
        usul = "numpy bit ameliyeleri"
    return {"usul": usul, "donanım": donanim_var, "bayt": bayt,
            "sn": float(sure), "bant_gb": float(bayt / sure / 1e9),
            "satır": int(satir), "kelime": int(kelime)}


def hesap(ne: str = "oto"):
    ne = str(ne)
    if ne in ("oto", "cupy"):
        try:
            import cupy as cp
            return cp, "cupy", True
        except Exception:
            if ne == "cupy":
                raise RuntimeError("cupy istendi fakat kurulu değil")
    if ne in ("oto", "torch"):
        try:
            import torch
            if torch.cuda.is_available():
                return torch, "torch-cuda", True
            if ne == "torch":
                return torch, "torch-cpu", False
        except Exception:
            if ne == "torch":
                raise RuntimeError("torch istendi fakat kurulu değil")
    if ne in ("oto", "numpy"):
        return np, "numpy", False
    raise ValueError("çekirdek bilinmiyor: %r" % (ne,))


def gpu_var_mi() -> Dict[str, Any]:
    o: Dict[str, Any] = {"cupy": False, "torch": False, "nvidia_smi": False,
                         "cihaz": [], "sebep": ""}
    try:
        import cupy
        o["cupy"] = True
    except Exception as e:
        o["sebep"] += "cupy: %s; " % type(e).__name__
    try:
        import torch
        o["torch"] = bool(torch.cuda.is_available())
    except Exception as e:
        o["sebep"] += "torch: %s; " % type(e).__name__
    try:
        r = subprocess.run(
            ["nvidia-smi", "--query-gpu=name,memory.total,pcie.link.gen.max,"
             "pcie.link.width.max", "--format=csv,noheader"],
            capture_output=True, text=True, timeout=20)
        if r.returncode == 0 and r.stdout.strip():
            o["nvidia_smi"] = True
            o["cihaz"] = [x.strip() for x in r.stdout.strip().splitlines()]
    except Exception as e:
        o["sebep"] += "nvidia-smi: %s; " % type(e).__name__
    o["var"] = bool(o["cupy"] or o["torch"] or o["nvidia_smi"])
    return o


def gpu_olcu(bayt: int = 1 << 26, tekrar: int = 10) -> Dict[str, Any]:
    v = gpu_var_mi()
    o: Dict[str, Any] = {
        "var": bool(v["var"]), "yoklama": v, "kart": None,
        "vram_bant_gb": None, "pcie_bant_gb": None,
        "tamsayı_bant_gb": None, "vram_bayt": None, "ad": None,
        "kütüphane": None}
    if not v["var"]:
        o["sebep"] = ("GPU YOK -- bu makinede VRAM/PCIe ölçülemez. "
                      "Zabıtın rakamları iddiadır, ölçü değildir.")
        return o
    try:
        import cupy as cp
    except Exception:
        o["sebep"] = ("GPU görünüyor fakat ``cupy`` yok: cihaz-içi ölçü "
                      "yapılamadı. Kart listesi ``yoklama``dadır.")
        o["kart"] = len(v["cihaz"]) or None
        return o
    o["kütüphane"] = "cupy"
    o["kart"] = int(cp.cuda.runtime.getDeviceCount())
    ozellik = cp.cuda.runtime.getDeviceProperties(0)
    o["ad"] = ozellik["name"].decode() if isinstance(
        ozellik["name"], bytes) else str(ozellik["name"])
    o["vram_bayt"] = int(ozellik["totalGlobalMem"])
    n = max(1 << 20, int(bayt) // 8)
    a = cp.ones(n, cp.float64)
    b = cp.empty(n, cp.float64)
    cp.cuda.Stream.null.synchronize()
    b[:] = a
    cp.cuda.Stream.null.synchronize()
    t0 = time.perf_counter()
    for _ in range(int(tekrar)):
        b[:] = a
    cp.cuda.Stream.null.synchronize()
    sure = (time.perf_counter() - t0) / int(tekrar)
    o["vram_bant_gb"] = float(2.0 * n * 8 / sure / 1e9)
    h = np.ones(n, np.float64)
    d = cp.empty(n, cp.float64)
    d.set(h)
    cp.cuda.Stream.null.synchronize()
    t0 = time.perf_counter()
    for _ in range(int(tekrar)):
        d.set(h)
    cp.cuda.Stream.null.synchronize()
    o["pcie_bant_gb"] = float(n * 8 / ((time.perf_counter() - t0)
                                       / int(tekrar)) / 1e9)
    X = cp.asarray(np.random.default_rng(0).integers(
        0, 1 << 62, size=(4096, 64), dtype=np.uint64))
    M = cp.asarray(np.random.default_rng(1).integers(
        0, 1 << 62, size=64, dtype=np.uint64))
    X ^= M[None, :]
    cp.cuda.Stream.null.synchronize()
    t0 = time.perf_counter()
    for _ in range(int(tekrar)):
        X ^= M[None, :]
    cp.cuda.Stream.null.synchronize()
    sure = (time.perf_counter() - t0) / int(tekrar)
    o["tamsayı_bant_gb"] = float(2.0 * X.nbytes / sure / 1e9)
    return o


def donanim(yeniden: bool = False) -> Dict[str, Any]:
    if not yeniden and "hepsi" in _ONBELLEK:
        return _ONBELLEK["hepsi"]
    o = {
        "cpu": {
            "çekirdek": cekirdek_sayisi(),
            "önbellek": onbellekler(),
            "saat": saat_ghz(),
            "simd": simd_bilgisi(),
            "bant": bellek_bandi(),
            "bellek": bellek_baytlari(),
            "tamsayı": tamsayi_hizi(),
        },
        "gpu": gpu_olcu(),
    }
    _ONBELLEK["hepsi"] = o
    return o


def rapor() -> str:
    d = donanim()
    c, g = d["cpu"], d["gpu"]
    ob = c["önbellek"]
    sm = c["simd"]
    s = ["=== DONANIM -- HEPSİ YOKLANDI, HİÇBİRİ ELLE YAZILMADI ===", "",
         "  --- CPU ---",
         "    kullanılabilir çekirdek : %d" % c["çekirdek"],
         "    L1d / L2 / L3           : %s / %s / %s"
         % tuple("%d KB" % (v // 1024) if v else "?"
                 for v in (ob["L1d"], ob["L2"], ob["L3"])),
         "    ilan edilen saat        : %s"
         % ("%.2f GHz" % c["saat"]["ilan_ghz"] if c["saat"]["ilan_ghz"]
            else "okunamadı"),
         "    bellek bandı (STREAM)   : %.2f GB/s   (ÖLÇÜLDÜ)"
         % c["bant"]["bant_gb"],
         "    symplectic tamsayı bandı: %.2f GB/s   (%s)"
         % (c["tamsayı"]["bant_gb"], c["tamsayı"]["usul"]),
         "",
         "  --- GALOIS KOMUTLARI (icra ile tayin, bayrakla DEĞİL) ---",
         "    GFNI koşuyor mu : %s   (%s)"
         % (sm["gfni_koşuyor"], sm["gfni_sebep"]),
         "    SIMD genişliği  : %s bit"
         % (sm["genişlik_bit"] or "?"),
         "    GFNI / tablo    : %s"
         % ("%.2f GB/s  vs  %.2f GB/s  →  %.1f× hızlı"
            % (sm["gfni_gb"], sm["tablo_gb"], sm["gfni_hızı"])
            if sm["gfni_gb"] else "ölçülemedi")]
    if sm["cpuid_ayrıştı"]:
        s += ["    ⚠ CPUID 'GFNI yok' diyor, komut KOŞUYOR: bayrak",
              "      maskelenmiş. Karar icradan çıktı, bayraktan değil."]
    s += ["", "  --- GPU ---"]
    if not g["var"]:
        s += ["    GPU YOK. VRAM, PCIe ve cihaz-içi hız **ölçülemedi**.",
              "    Bu makinede o sayılar ``None``dur ve None kalır;",
              "    zabıttaki 300 GB/s / 31,5 GB/s birer **iddiadır**,",
              "    ölçü değildir ve ölçü yerine geçirilmez.",
              "    yoklama: %s" % (g["yoklama"]["sebep"] or "-")]
    else:
        s += ["    kart            : %s × %s" % (g["kart"], g["ad"]),
              "    VRAM            : %s"
              % ("%.1f GB" % (g["vram_bayt"] / 1e9) if g["vram_bayt"]
                 else "?"),
              "    VRAM bandı      : %s   (ÖLÇÜLDÜ)"
              % ("%.1f GB/s" % g["vram_bant_gb"] if g["vram_bant_gb"]
                 else "ölçülemedi"),
              "    PCIe bandı      : %s   (ÖLÇÜLDÜ)"
              % ("%.1f GB/s" % g["pcie_bant_gb"] if g["pcie_bant_gb"]
                 else "ölçülemedi"),
              "    tamsayı bandı   : %s"
              % ("%.1f GB/s" % g["tamsayı_bant_gb"]
                 if g["tamsayı_bant_gb"] else "ölçülemedi")]
    return "\n".join(s)
