from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any, Dict, List, Mapping, Optional, Tuple

import numpy as np

__all__ = ["Kayit", "Hafiza", "TASDIK", "TEVAKKUF", "CERH", "rapor",
           "tertip_beyani", "tertip_metni"]

_TERTIP: Dict[str, float] = {
    "çağrı": 0.0, "yırtıktan": 0.0, "kapıdan": 0.0, "alâkalı": 0.0,
    "taşınan": 0.0, "silinen": 0.0, "kök": 0.0, "ayırt": 0.0,
    "vecih": 0.0, "açık": 1.0}

_VECIH_ADI: List[str] = []


def tertip_beyani() -> Dict[str, Any]:
    b: Dict[str, Any] = dict(_TERTIP)
    b["vecih_adı"] = list(_VECIH_ADI)
    return b


def tertip_metni(b: Optional[Dict[str, Any]] = None) -> str:
    d = dict(b or tertip_beyani())
    if not d.get("çağrı"):
        return ("  HAFIZA YENİDEN TERTİBİ: HİÇ KOŞMADI -- kırmızı "
                "(ferman 2-Ú)")
    return "\n".join([
        "  HAFIZA YENİDEN TERTİBİ -- SİLİNMEZ, TERFİ EDER (ferman 2-Ú)",
        "    çağrı %d   (Sorites yırtığından %d · veri kapısından %d)"
        % (int(d["çağrı"]), int(d["yırtıktan"]), int(d["kapıdan"])),
        "    alâka taramasında parlayan kayıt %d   taşınan %d"
        "   SİLİNEN %d"
        % (int(d["alâkalı"]), int(d["taşınan"]), int(d["silinen"])),
        "    Silinen SIFIR olmalıdır: çizip geçmek amnezidir.",
        "    modalite vechi AYIRT ETME nispetiyle ölçüldü: %.6f   açılan"
        " Cartan kökü %d" % (d.get("ayırt", 0.0), int(d["kök"])),
        "    açılan yapraklar: %s"
        % (", ".join(d.get("vecih_adı") or []) or "yok"),
        "    Yaprak adı ELLE YAZILMAZ (ferman 6): çelişen iki kaydı",
        "    ayıran vecih, ŞAHİTSİZ olarak ikisini en çok ayıran,",
        "    yâni örtüşmesi en düşük olan vecihtir (ferman 2-Ú).",
        "    (ölçü %s)" % ("açık" if d.get("açık") else "KAPALI"),
    ])

TASDIK = 1.0
TEVAKKUF = 0.5
CERH = 0.0

_SONUM_PAYI: Dict[float, float] = {TASDIK: 0.25, TEVAKKUF: 1.0, CERH: 0.10}


@dataclass
class Kayit:

    x: np.ndarray
    omega: float
    hukum: float
    mu: float
    dogum: int = 0
    yaprak: str = ""

    def __post_init__(self) -> None:
        self.x = np.asarray(self.x).reshape(-1)
        nrm = float(np.linalg.norm(self.x))
        assert nrm > 0.0, "BOŞ kavram hafızaya nakşedilemez"
        self.x = self.x / nrm
        assert self.hukum in (TASDIK, TEVAKKUF, CERH), (
            "hüküm damgası üçünden biri olmalı: %r" % (self.hukum,))
        assert -1.0000001 <= self.omega <= 1.0000001, (
            "holonomi izi [−1,1] dışında: %r" % (self.omega,))


class Hafiza:

    def __init__(self, kapasite: int = 256, yazma: float = 0.05,
                 sonum: float = 0.02, zeno_esigi: float = 0.35,
                 zeno_tepe: float = 0.9, ayniyet: float = 0.98,
                 buhar: float = 1e-4, mu_asgari: float = 1e-3,
                 tohum: int = 0) -> None:
        assert int(kapasite) >= 1, "hafıza kapasitesi en az 1 olmalı"
        assert 0.0 < float(yazma) <= 1.0, "yazma oranı (0,1] olmalı"
        assert 0.0 <= float(sonum) < 1.0, "sönüm [0,1) olmalı"
        self.kapasite = int(kapasite)
        self.yazma = float(yazma)
        self.sonum = float(sonum)
        self.zeno_esigi = float(zeno_esigi)
        self.zeno_tepe = float(zeno_tepe)
        self.ayniyet = float(ayniyet)
        self.buhar = float(buhar)
        self.mu_asgari = float(mu_asgari)
        assert 0.0 < self.zeno_tepe <= 1.0, "zeno tepe nispeti (0,1]"
        assert 0.0 < self.ayniyet <= 1.0, "ayniyet eşiği (0,1]"
        self.tohum = int(tohum)
        self.kayitlar: List[Kayit] = []
        self.budama = 0
        self.tertip = 0
        self.adim = 0

    def klon(self) -> "Hafiza":
        import copy
        y = copy.copy(self)
        y.kayitlar = [copy.copy(k) for k in self.kayitlar]
        return y

    def yaz(self, x, omega: float, hukum: float,
            cartan_koku: Optional[str] = None) -> Kayit:
        self.adim += 1
        e = self.yazma
        for k in self.kayitlar:
            k.mu *= (1.0 - e)
        y = Kayit(x=x, omega=float(omega), hukum=float(hukum), mu=e,
                  dogum=self.adim, yaprak=cartan_koku or "")
        for k in self.kayitlar:
            if (k.hukum == y.hukum
                    and abs(complex(np.vdot(k.x, y.x))) > self.ayniyet):
                k.mu += y.mu
                return k
        self.kayitlar.append(y)
        self._tasfiye()
        return y

    def _tasfiye(self) -> None:
        if self.sonum > 0.0:
            for k in self.kayitlar:
                k.mu *= (1.0 - self.sonum * _SONUM_PAYI[k.hukum])
        buharlasan = [k for k in self.kayitlar if k.mu <= self.buhar]
        kalan = [k for k in self.kayitlar if k.mu > self.buhar]
        self.kayitlar = kalan
        if buharlasan:
            self._balyala(buharlasan)
        if len(self.kayitlar) > self.kapasite:
            self.kayitlar.sort(key=lambda k: -k.mu)
            tas = len(self.kayitlar) - self.kapasite
            tasinanlar = self.kayitlar[-tas:]
            self.kayitlar = self.kayitlar[:-tas]
            self._balyala(tasinanlar)
            if len(self.kayitlar) > self.kapasite:
                self.kayitlar.sort(key=lambda k: -k.mu)
                self.kayitlar = self.kayitlar[:self.kapasite]
        assert len(self.kayitlar) <= self.kapasite

    def _balyala(self, kayitlar: List["Kayit"]) -> None:
        if not kayitlar:
            return
        x_ort = np.mean([k.x for k in kayitlar], axis=0)
        nrm = float(np.linalg.norm(x_ort))
        if nrm > 1e-12:
            x_ort = x_ort / nrm
        else:
            x_ort = kayitlar[0].x
        balya = Kayit(x=x_ort,
                      omega=float(np.clip(
                          np.mean([k.omega for k in kayitlar]), -1.0, 1.0)),
                      hukum=TEVAKKUF,
                      mu=float(sum(k.mu for k in kayitlar) * 0.5),
                      dogum=self.adim, yaprak="balya_%d" % self.adim)
        self.kayitlar.append(balya)

    def oku(self, x) -> Dict[str, float]:
        v = np.asarray(x).reshape(-1)
        nrm = float(np.linalg.norm(v))
        assert nrm > 0.0, "boş durumla hafıza okunamaz"
        v = v / nrm
        out = {"tasdik": 0.0, "tevakkuf": 0.0, "cerh": 0.0, "toplam": 0.0}
        ad = {TASDIK: "tasdik", TEVAKKUF: "tevakkuf", CERH: "cerh"}
        for k in self.kayitlar:
            if k.x.size != v.size:
                continue
            ort = float(abs(np.vdot(k.x, v)) ** 2) * k.mu
            out[ad[k.hukum]] += ort
            out["toplam"] += ort
        return out

    def taban_degistir(self, x, yaprak: str, omega: float = 0.0
                       ) -> Dict[str, Any]:
        from .mukayese import swap_testi
        v = np.asarray(x).reshape(-1)
        nrm = float(np.linalg.norm(v))
        assert nrm > 0.0, "boş durumla taban değiştirilemez"
        v = v / nrm
        tasinan = 0
        for k in self.kayitlar:
            if k.x.size != v.size:
                continue
            s = swap_testi(k.x.astype(complex), v.astype(complex))
            if float(s["örtüşme"]) < self.zeno_esigi:
                continue
            eski = k.yaprak
            k.yaprak = (eski + "|" + str(yaprak)) if eski else str(yaprak)
            k.omega = float(omega) if omega else k.omega
            tasinan += 1
        self.tertip += 1
        return {"yaprak": str(yaprak), "taşınan": int(tasinan),
                "tertip": int(self.tertip), "silinen": 0}

    def yeniden_tertiple(self, capraz, sahit=None, mahalli=None,
                         kapi: str = "yırtık") -> Dict[str, Any]:
        from .mukayese import swap_testi, vecihleri_istihrac
        _TERTIP["çağrı"] += 1.0
        _TERTIP["yırtıktan" if kapi == "yırtık" else "kapıdan"] += 1.0
        if not _TERTIP.get("açık"):
            return {"vecih": "", "taşınan": 0, "silinen": 0, "Φ₃": 0.0}
        A = np.asarray(capraz[0], complex).reshape(-1)
        B = np.asarray(capraz[1], complex).reshape(-1)
        assert A.size == B.size, (
            "yeniden tertip iki eşit boyda kutup ister: %d, %d"
            % (A.size, B.size))
        en_iyi = None
        for v in vecihleri_istihrac([A, B]):
            s = swap_testi(A, B, v)
            ayirt = float(1.0 - float(s["örtüşme"]))
            if en_iyi is None or ayirt > en_iyi[1]:
                en_iyi = (str(v.ad), ayirt)
        assert en_iyi is not None, (
            "hiçbir vecih ayırt etmedi -- modalite lifi ölçülemedi")
        yaprak, fi = en_iyi
        _TERTIP["ayırt"] = float(fi)
        if yaprak not in _VECIH_ADI:
            _VECIH_ADI.append(yaprak)
        _TERTIP["vecih"] = float(len(_VECIH_ADI))
        if mahalli is not None:
            _TERTIP["kök"] = float(
                mahalli.cartan_ekle("modalite." + yaprak, float(fi)) + 1)
        P = (A + B)
        nrm = float(np.linalg.norm(P))
        assert nrm > 0.0, (
            "çelişen iki kutup birbirini tamamen söndürdü -- alâka "
            "izdüşümü kurulamıyor")
        d = self.taban_degistir(P / nrm, yaprak=yaprak,
                                omega=float(1.0 - float(fi)))
        _TERTIP["alâkalı"] += float(d["taşınan"])
        _TERTIP["taşınan"] += float(d["taşınan"])
        _TERTIP["silinen"] += float(d["silinen"])
        return {"vecih": yaprak, "ayırt": float(fi),
                "taşınan": int(d["taşınan"]), "silinen": int(d["silinen"]),
                "kapı": kapi}

    def zeno(self, x) -> Optional[np.ndarray]:
        v = np.asarray(x, float).reshape(-1)
        nrm = float(np.linalg.norm(v))
        if nrm <= 0.0:
            return None
        v = v / nrm
        maske = np.ones(v.size, bool)
        vuran = False
        for k in self.kayitlar:
            if k.hukum != CERH or k.x.size != v.size:
                continue
            ort = float(abs(np.vdot(k.x, v)) ** 2)
            if ort < self.zeno_esigi or k.mu < self.mu_asgari:
                continue
            g = np.abs(np.asarray(k.x)).astype(float)
            maske &= ~(g >= g.max() * self.zeno_tepe)
            vuran = True
        if not vuran or maske.all():
            return None
        self.budama += int(np.count_nonzero(~maske))
        return maske

    def beyan(self) -> Dict[str, Any]:
        say = {TASDIK: 0, TEVAKKUF: 0, CERH: 0}
        for k in self.kayitlar:
            say[k.hukum] += 1
        return {"kayıt": len(self.kayitlar), "tasdik": say[TASDIK],
                "tevakkuf": say[TEVAKKUF], "cerh": say[CERH],
                "budama": int(self.budama), "adım": int(self.adim),
                "tertip": int(self.tertip),
                "yapraklı": sum(1 for k in self.kayitlar if k.yaprak),
                "kütle": float(sum(k.mu for k in self.kayitlar))}

    def hazineye(self) -> Dict[str, np.ndarray]:
        if not self.kayitlar:
            return {}
        m = max(k.x.size for k in self.kayitlar)
        X = np.zeros((len(self.kayitlar), m), complex)
        for i, k in enumerate(self.kayitlar):
            X[i, :k.x.size] = k.x
        return {
            "hafıza.x": X,
            "hafıza.omega": np.array([k.omega for k in self.kayitlar], float),
            "hafıza.hüküm": np.array([k.hukum for k in self.kayitlar], float),
            "hafıza.mu": np.array([k.mu for k in self.kayitlar], float),
            "hafıza.doğum": np.array([k.dogum for k in self.kayitlar],
                                     np.int64)}

    @classmethod
    def hazineden(cls, agirlik: Mapping[str, Any],
                  ust_veri: Optional[Mapping[str, Any]] = None) -> "Hafiza":
        u = dict(ust_veri or {})
        h = cls(kapasite=int(float(u.get("hafıza_kapasitesi", 256))),
                yazma=float(u.get("hafıza_yazma", 0.05)),
                sonum=float(u.get("hafıza_sönümü", 0.02)),
                zeno_esigi=float(u.get("zeno_eşiği", 0.35)),
                zeno_tepe=float(u.get("zeno_tepe", 0.9)))
        if "hafıza.x" not in agirlik:
            return h
        X = np.asarray(agirlik["hafıza.x"])
        om = np.asarray(agirlik["hafıza.omega"], float).reshape(-1)
        hk = np.asarray(agirlik["hafıza.hüküm"], float).reshape(-1)
        mu = np.asarray(agirlik["hafıza.mu"], float).reshape(-1)
        dg = np.asarray(agirlik.get(
            "hafıza.doğum", np.zeros(om.size)), np.int64).reshape(-1)
        assert X.shape[0] == om.size == hk.size == mu.size, (
            "hafıza tensörlerinin boyları tutmuyor")
        for i in range(X.shape[0]):
            h.kayitlar.append(Kayit(x=X[i], omega=float(om[i]),
                                    hukum=float(hk[i]), mu=float(mu[i]),
                                    dogum=int(dg[i])))
        h.adim = int(dg.max()) if dg.size else 0
        return h


def rapor(tohum: int = 0) -> str:
    r = np.random.default_rng(int(tohum))
    m = 16
    h = Hafiza(kapasite=64, yazma=0.2, sonum=0.02)

    safsata = np.zeros(m)
    safsata[3] = 1.0
    safsata[7] = 0.95
    h.yaz(safsata, omega=-1.0, hukum=CERH)
    mesru = np.zeros(m)
    mesru[1] = 1.0
    h.yaz(mesru, omega=0.2, hukum=TASDIK)

    P = np.full(m, 1.0 / m)
    P[3] = 0.5
    P[7] = 0.4
    P = P / P.sum()
    mask = h.zeno(np.sqrt(P))
    kesik = 0 if mask is None else int(np.count_nonzero(~mask))

    Q = np.full(m, 1.0 / m)
    Q[11] = 0.6
    Q = Q / Q.sum()
    mask2 = h.zeno(np.sqrt(Q))
    kesik2 = 0 if mask2 is None else int(np.count_nonzero(~mask2))

    k = h.oku(np.sqrt(P))
    zan = np.zeros(m)
    zan[5] = 1.0
    h.yaz(zan, omega=1.0, hukum=TEVAKKUF)
    mu0 = [x.mu for x in h.kayitlar if x.hukum == TEVAKKUF][0]
    for _ in range(50):
        h._tasfiye()
    kalan = [x.mu for x in h.kayitlar if x.hukum == TEVAKKUF]
    mu1 = kalan[0] if kalan else 0.0

    return "\n".join([
        "=== KUANTUM ASOSİYATİF HAFIZA (ρ) ===", "",
        "  kayıt : %r" % (h.beyan(),), "",
        "  ZENO BUDAMASI",
        "    cerhedilmiş yola girildi : %d belirteç kesildi  %s"
        % (kesik, "ÇALIŞTI" if kesik > 0 else "⚠ HİÇ KESMEDİ"),
        "    alâkasız yola girildi    : %d belirteç kesildi  %s"
        % (kesik2, "doğru (kesmemeli)" if kesik2 == 0
           else "⚠ KÖR KESİYOR"),
        "",
        "  ASOSİYATİF ÇAĞRIŞIM (𝒦 = Tr ρ|ψ⟩⟨ψ|)",
        "    cerh=%.4f  tasdik=%.4f  tevakkuf=%.4f"
        % (k["cerh"], k["tasdik"], k["tevakkuf"]),
        "",
        "  LIOUVILLE SÖNÜMÜ (delilsiz zan buharlaşır)",
        "    tevakkuf μ: %.6f → %.6f  (50 tasfiye sonra)" % (mu0, mu1),
    ])
# ==== BİTTİ: nefs/hafiza.py ====

# ==== BAŞLIYOR: nefs/illet.py ====
from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Set, Tuple

from matematik.fitrat import Cizge, gecer_mi

__all__ = ["alan_cizgesi", "zaman_cizgesi", "cevrimler", "kelam_ayrismasi",
           "rapor"]

HUKUM_ALANLARI: Tuple[str, ...] = (
    "yerel", "makam", "mizan", "tenakuz", "tasdik", "sukut", "nakz",
    "gaye", "tertip",
)


def _melekelerin_bolgeleri() -> List[Tuple[int, Tuple[str, ...]]]:
    from .melekeler import QAKIS
    from .kulli_kayip import SOZLESME
    return [(no, SOZLESME[no][0]) for no in QAKIS]


def alan_cizgesi() -> Tuple[List[str], List[Tuple[str, str]], bool]:
    adimlar = _melekelerin_bolgeleri()
    dugumler: List[str] = []
    kenarlar: Set[Tuple[str, str]] = set()
    for _, bolg in adimlar:
        for a in bolg:
            if a not in dugumler:
                dugumler.append(a)
        for a in bolg:
            for b in bolg:
                if a != b:
                    kenarlar.add((a, b))
    ken = sorted(kenarlar)
    try:
        Cizge(tuple(dugumler), tuple(ken))
        kabul = True
    except ValueError:
        kabul = False
    return dugumler, ken, kabul


def zaman_cizgesi() -> Tuple[Cizge, Dict[str, List[str]]]:
    adimlar = _melekelerin_bolgeleri()
    alanlar = sorted({a for _, b in adimlar for a in b})
    T = len(adimlar)
    dug: List[str] = []
    yer: Dict[str, List[str]] = {a: [] for a in alanlar}
    for t in range(T + 1):
        for a in alanlar:
            ad = "%s@%d" % (a, t)
            dug.append(ad)
            yer[a].append(ad)
    ken: Set[Tuple[str, str]] = set()
    for t in range(T):
        for a in alanlar:
            ken.add(("%s@%d" % (a, t), "%s@%d" % (a, t + 1)))
        bolg = adimlar[t][1]
        for a in bolg:
            for b in bolg:
                if a != b:
                    ken.add(("%s@%d" % (a, t), "%s@%d" % (b, t + 1)))
    return Cizge(tuple(dug), tuple(sorted(ken))), yer


def cevrimler(dugumler: Sequence[str],
              kenarlar: Sequence[Tuple[str, str]]) -> List[List[str]]:
    cocuk: Dict[str, Set[str]] = {}
    for a, b in kenarlar:
        cocuk.setdefault(a, set()).add(b)
    beyaz, gri, siyah = set(dugumler), set(), set()
    bulunan: List[List[str]] = []

    def git(u: str, yol: List[str]) -> None:
        beyaz.discard(u)
        gri.add(u)
        for v in sorted(cocuk.get(u, ())):
            if v in gri:
                bulunan.append(yol[yol.index(v):] + [v] if v in yol
                               else [u, v])
            elif v in beyaz:
                git(v, yol + [v])
        gri.discard(u)
        siyah.add(u)

    for u in sorted(dugumler):
        if u in beyaz:
            git(u, [u])
    return bulunan


def kelam_ayrismasi() -> Dict[str, object]:
    g, yer = zaman_cizgesi()
    if "kelam" not in yer or "veri" not in yer:
        return {"kurulabilir": False}
    T = len(yer["kelam"]) - 1
    Z: List[str] = []
    for a in HUKUM_ALANLARI:
        Z += yer.get(a, [])
    ayrik = bool(gecer_mi(g, [yer["veri"][0]], [yer["kelam"][T]], Z))
    ayrik_sartsiz = bool(gecer_mi(g, [yer["veri"][0]],
                                    [yer["kelam"][T]], []))
    from .melekeler import QAKIS, qsicil
    from .kulli_kayip import SOZLESME
    sic = qsicil()
    dogrudan = [(no, sic[no].ad) for no in dict.fromkeys(QAKIS)
                if "veri" in SOZLESME[no][0] and "kelam" in SOZLESME[no][0]]
    return {"kurulabilir": True, "adım": T,
            "doğrudan_melekeler": dogrudan,
            "hüküm_şartıyla_ayrık": ayrik,
            "şartsız_ayrık": ayrik_sartsiz,
            "şart_kümesi": len(Z)}


def rapor() -> str:
    dug, ken, kabul = alan_cizgesi()
    ac = cevrimler(dug, ken)
    zg, yer = zaman_cizgesi()
    zc = cevrimler(zg.dugumler, zg.kenarlar)
    ka = kelam_ayrismasi()

    s = ["=== İLLET -- akışın sebep çizgesi (fitrat/ayrisma.py ile) ===",
         "",
         "Çizge `nefs/sozlesme.py`nin ÖLÇÜLMÜŞ bölge ilanlarından ve",
         "``QAKIS`` sırasından kuruldu; uydurulmadı.",
         "",
         "𝒪₂₂'nin iddiası: *'Asiklik şartı inşa gereği sağlanır.'*",
         "Bu tek bir meleke için doğrudur. Bütün akış için iki ayrı",
         "sual vardır ve ikisi de ölçülür:",
         "",
         "  ALAN seviyesinde (hangi alan hangisini etkiliyor):",
         "    düğüm %d, kenar %d, çevrim: %d"
         % (len(dug), len(ken), len(ac)),
         "    fitrat/ayrisma.Cizge kabul etti mi: %s" % kabul,
         "    → çevrim VAR ve olması normaldir: akış aynı alana",
         "      defalarca döner. 'Akış asikliktir' demek burada YANLIŞ",
         "      olurdu." if ac else
         "    → çevrim yok.",
         "",
         "  ZAMAN açılımında (her adımda alanın ayrı düğümü):",
         "    düğüm %d, kenar %d, çevrim: %d"
         % (len(zg.dugumler), len(zg.kenarlar), len(zc)),
         "    → asiklik CEBREN sağlanır (zaman ileri akar); bu bir",
         "      ispat değil bir tariftir ve öyle sayılır.",
         ""]

    s.append("KELAM AYRIŞMASI -- mimarînin gerekçesi tutuyor mu?")
    if not ka.get("kurulabilir"):
        s.append("  çizge kurulamadı")
    else:
        s += ["  `kelam` ayrı bir alandır çünkü veri kübitlerinin",
              "  marjinali dolaşıklık yüzünden düzgündür (H43). Şart:",
              "  beyan, veriden HÜKÜM ÜZERİNDEN beslensin.",
              "",
              "    adım sayısı              : %d" % ka["adım"],
              "    şart kümesi (hüküm@t)    : %d düğüm" % ka["şart_kümesi"],
              "    hüküm şartıyla d-ayrık   : %s" % ka["hüküm_şartıyla_ayrık"],
              "    şartsız d-ayrık          : %s  (False olmalı -- ölçüt kör değil)"
              % ka["şartsız_ayrık"],
              ""]
        if ka["hüküm_şartıyla_ayrık"]:
            s += ["  NETİCE: veriden kelama giden her yol hükümden geçiyor;",
                  "  beyan hükmü atlayamıyor."]
        else:
            s += ["  NETİCE: veriden kelama, hüküm alanlarını ATLAYAN bir",
                  "  yol var. Sebebi tek tek izlenebilir:"]
            for no, ad in ka.get("doğrudan_melekeler", ()):
                s.append("    𝒪%-3d %s -- aynı ünitede hem veri hem kelam"
                         % (no, ad))
            s += ["",
                  "  **Bu bir KUSUR değildir ve öyle denmiyor.** Mimarînin",
                  "  kelam hakkındaki iddiası *'yalnız beyan melekeleri",
                  "  yazar'*dır ve o iddia DOĞRU. 'Yol hükümden geçmeli'",
                  "  şartını ben koydum; mimarî onu iddia etmemişti.",
                  "  Ölçüm tasarım hakikatini görünür kılar, hükmü vermez --",
                  "  beyanın hükme uğramadan veriden beslenmesi istenir mi,",
                  "  bu kullanıcının kararıdır."]
    return "\n".join(s)
# ==== BİTTİ: nefs/illet.py ====

# ==== BAŞLIYOR: nefs/kararname.py ====
from __future__ import annotations

import math
from typing import Any, Dict, List, Optional

import numpy as np

__all__ = ["kararname", "rapor"]


def kararname(psi, mertebe: int = 8, esik: float = 1e-3,
              tohum: int = 0) -> Dict[str, Any]:
    v = np.asarray(psi, complex).reshape(-1)
    d = int(v.size)
    assert d >= 2, "karar verilecek durum en az iki genlikli olmalı"
    nrm = float(np.linalg.norm(v))
    assert nrm > 0.0, "BOŞ durum hakkında karar verilemez"
    v = v / nrm
    if int(mertebe) <= 0:
        return {"chi": 0, "örtüşme": 0.0, "üst_sınır": True,
                "clifforda_yakın": False, "kalıntı": 1.0,
                "aday": 0, "kapalı": True}

    kalinti = v.copy()
    secilen: List[int] = []
    kats: List[complex] = []
    jj = np.arange(d)
    for _ in range(int(mertebe)):
        iz = int(np.argmax(np.abs(kalinti)))
        c_z = complex(kalinti[iz])
        F = np.fft.fft(kalinti) / math.sqrt(d)
        ix = int(np.argmax(np.abs(F)))
        c_x = complex(np.conj(F[ix]))
        if abs(c_z) >= abs(c_x):
            if abs(c_z) < 1e-12:
                break
            taban = np.zeros(d, complex)
            taban[iz] = 1.0
            kat = c_z
        else:
            if abs(c_x) < 1e-12:
                break
            taban = np.exp(2j * math.pi * ix * jj / d) / math.sqrt(d)
            kat = complex(np.vdot(taban, kalinti))
        secilen.append(iz if abs(c_z) >= abs(c_x) else (d + ix))
        kats.append(kat)
        kalinti = kalinti - kat * taban
        if float(np.linalg.norm(kalinti)) < float(esik):
            break
    kal = float(np.linalg.norm(kalinti))
    ortusme = float(max(0.0, 1.0 - kal ** 2))
    return {"chi": len(secilen), "örtüşme": ortusme,
            "kalıntı": kal, "aday": 2 * d,
            "üst_sınır": True, "kapalı": False,
            "clifforda_yakın": bool(kal < float(esik)),
            "katsayı": np.asarray(kats, complex)}


def rapor(d: int = 256, tohum: int = 0) -> str:
    r = np.random.default_rng(int(tohum))
    j = np.arange(d)
    haller = {
        "taban |5⟩ (stabilizer)": np.eye(1, d, 5, dtype=complex).reshape(-1),
        "Fourier |+⟩ (stabilizer)": np.exp(2j * math.pi * 3 * j / d)
        / math.sqrt(d),
        "iki stabilizer toplamı": (np.eye(1, d, 5, dtype=complex).reshape(-1)
                                   + np.exp(2j * math.pi * 3 * j / d)
                                   / math.sqrt(d)),
        "gürültü (Haar)": r.normal(size=d) + 1j * r.normal(size=d),
    }
    s = ["=== KARARNAME -- stabilizer rank üst sınırı ===", "",
         "  d = %d   mertebe haddi = 8" % d, ""]
    for ad, v in haller.items():
        v = np.asarray(v, complex).reshape(-1)
        v = v / (np.linalg.norm(v) or 1.0)
        k = kararname(v, mertebe=8, tohum=tohum)
        s.append("  %-26s χ ≤ %2d   örtüşme %.6f   kalıntı %.2e   "
                 "Clifford'a yakın: %s"
                 % (ad, k["chi"], k["örtüşme"], k["kalıntı"],
                    k["clifforda_yakın"]))
    s += ["", "  Gürültüde χ küçük ÇIKMAZ ve bu gizlenmiyor: keyfî bir",
          "  durum Clifford çerçevesine oturmaz. χ bir vaat değil,",
          "  durumun yapısının neticesidir. Ayrıca dönen sayı χ'nin",
          "  kendisi değil ÜST SINIRIDIR (açgözlü seçim, sabit aile)."]
    return "\n".join(s)
# ==== BİTTİ: nefs/kararname.py ====

# ==== BAŞLIYOR: nefs/keyfiyet.py ====
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

import numpy as np

__all__ = ["KeyfiyetAyari", "keyfiyet", "esik", "keyfiyet_beyani", "keyfiyet_metni",
           "keyfiyet_son", "keyfiyet_sifirla"]


@dataclass
class KeyfiyetAyari:

    acik: int = 1
    azami_tur: int = 8
    taban: float = 0.25


_HAL: Dict[str, float] = {"en_iyi": 0.0, "çağrı": 0.0, "toplam": 0.0,
                          "temiz": 0.0, "kirli": 0.0}
_GECMIS: List[float] = []


def keyfiyet(kefeler: Dict[str, Any],
             sadakat: Optional[Dict[str, Any]] = None,
             ayar: Optional[KeyfiyetAyari] = None) -> Dict[str, Any]:
    a = ayar or KeyfiyetAyari()
    _HAL["çağrı"] += 1.0

    cevrim = max(1, int(kefeler.get("meşru", 0)) + int(kefeler.get("kısır", 0))
                 + int(kefeler.get("tenakuz", 0)) + int(kefeler.get("engel", 0)))
    n_ten = int(kefeler.get("tenakuz", 0))
    n_kis = int(kefeler.get("kısır", 0))
    assert sadakat is None or "artık_nispeti" in sadakat, (
        "sadakat beyanında ``artık_nispeti`` yok -- mantıksızlık hududu "
        "gelen taşmadan okunamaz (ferman 5)")
    tasma = float((sadakat or {}).get("artık_nispeti", 0.0))
    bel_tasma = float(kefeler.get("taşma", 0.0))

    nis_ten = 1.0 - float(n_ten) / cevrim
    nis_kis = 1.0 - float(n_kis) / cevrim
    nis_par = max(0.0, 1.0 - tasma)
    nis_bel = max(0.0, 1.0 - bel_tasma)
    nis_man = nis_par * nis_bel
    nispet = float(nis_ten * nis_kis * nis_man)
    assert 0.0 <= nispet <= 1.0 + 1e-9, "nispet [0,1] dışına çıktı"

    cozunurluk = float(np.finfo(float).eps)
    hudut = {"tenakuz": n_ten, "kısırdöngü": n_kis,
             "mantıksızlık": (int(tasma > cozunurluk)
                              + int(bel_tasma > cozunurluk))}
    temiz = all(v == 0 for v in hudut.values())

    _HAL["toplam"] += nispet
    _HAL["en_iyi"] = max(_HAL["en_iyi"], nispet)
    _HAL["temiz" if temiz else "kirli"] += 1.0
    _GECMIS.append(nispet)
    for ad, v in (("ten", nis_ten), ("kis", nis_kis), ("man", nis_man)):
        _HAL["n_" + ad] = _HAL.get("n_" + ad, 0.0) + float(v)
        _HAL["en_kotu_" + ad] = min(
            _HAL.get("en_kotu_" + ad, 1.0), float(v))
    return {"hudut": hudut, "hudut_temiz": bool(temiz), "nispet": nispet,
            "nispet_tenakuz": nis_ten, "nispet_kısır": nis_kis,
            "nispet_mantık": nis_man, "çevrim": cevrim,
            "parite_taşması": tasma, "belirteç_taşması": bel_tasma,
            "nispet_parite": nis_par, "nispet_belirteç": nis_bel,
            "açık": bool(int(a.acik))}


def esik(tur: int, azami_tur: int,
         ayar: Optional[KeyfiyetAyari] = None) -> float:
    a = ayar or KeyfiyetAyari()
    T = max(1, int(azami_tur))
    kalan = max(0.0, 1.0 - float(tur) / T)
    t = float(a.taban)
    return float(_HAL["en_iyi"] * (t + (1.0 - t) * kalan))


def keyfiyet_beyani() -> Dict[str, Any]:
    c = max(1.0, _HAL["çağrı"])
    g = np.asarray(_GECMIS, float) if _GECMIS else np.zeros(1)
    return {"çağrı": int(_HAL["çağrı"]),
            "en_iyi": float(_HAL["en_iyi"]),
            "ortalama": float(_HAL["toplam"] / c),
            "ortanca": float(np.median(g)),
            "temiz": int(_HAL["temiz"]), "kirli": int(_HAL["kirli"]),
            "temiz_nispeti": float(_HAL["temiz"] / c),
            "son_eşik": float(esik(0, 1)),
            "ort_tenakuz": float(_HAL.get("n_ten", 0.0) / c),
            "ort_kısır": float(_HAL.get("n_kis", 0.0) / c),
            "ort_mantık": float(_HAL.get("n_man", 0.0) / c),
            "en_kötü_tenakuz": float(_HAL.get("en_kotu_ten", 1.0)),
            "en_kötü_kısır": float(_HAL.get("en_kotu_kis", 1.0)),
            "en_kötü_mantık": float(_HAL.get("en_kotu_man", 1.0))}


def keyfiyet_son() -> float:
    return float(_GECMIS[-1]) if _GECMIS else 0.0


def keyfiyet_sifirla() -> None:
    for k in _HAL:
        _HAL[k] = 0.0
    _GECMIS.clear()


def keyfiyet_metni(b=None) -> str:
    d = dict(b if b is not None else keyfiyet_beyani())
    return "\n".join([
        "  KEYFİYET -- ÜÇ KAT'Î HUDUT (ferman 1-I) ve EŞİK FONKSİYONU (1-J)",
        "    ölçüm       : %d      temiz: %d   kirli: %d   (nispet %.4f)"
        % (d["çağrı"], d["temiz"], d["kirli"], d["temiz_nispeti"]),
        "    nispet      : en iyi %.4f   ortanca %.4f   ortalama %.4f"
        % (d["en_iyi"], d["ortanca"], d["ortalama"]),
        "    çarpanlar   : tenakuz %.4f   kısır %.4f   mantık %.4f "
        "(ortalama; 1 = o hudut temiz)"
        % (d.get("ort_tenakuz", 0.0), d.get("ort_kısır", 0.0),
           d.get("ort_mantık", 0.0)),
        "    en kötü hâli: tenakuz %.4f   kısır %.4f   mantık %.4f "
        "← HANGİSİ SIFIRA YAKINSA HUDUT ONDAN KİRLİ"
        % (d.get("en_kötü_tenakuz", 1.0), d.get("en_kötü_kısır", 1.0),
           d.get("en_kötü_mantık", 1.0)),
        "    nispet = (1−tenakuz/çevrim)·(1−kısır/çevrim)·(1−artık) "
        "-- ÇARPIM, ortalama değil: bir hudut kirliyse nispet sıfırdır."])
