def sozunde_mi(no: int = 0, n_satir: int = 4, chi: int = 32,
                        tohum: int = 0, esik: float = ESIK,
                        ne: str = "dokundu") -> object:
    if ne == "hepsi":
        return [sozunde_mi(m.no, n_satir, chi, tohum, esik)
                for m in qmelekeler()]
    if ne != "dokundu":
        raise ValueError("sözleşme ölçüsünün kipi bilinmiyor: %r" % (ne,))

    def yuva_bolgeleri(q):
        return {"veri": list(q.veri_izgara()), "yerel": q.yereller()}

    def nufuslar(q):
        d = np.asarray(q.y.tekil_yogunluklar(list(range(q.n))), complex)[0]
        return np.abs(np.stack([d[:, 0, 0], d[:, 1, 1]], axis=-1))

    rng = np.random.default_rng(tohum)
    q = QYazmac(n_satir, QAyar(tohum=tohum))
    from kuantum.mahalli_yazmac import MahalliYazmac
    mahalli = MahalliYazmac(int(q.ayar.veri_lifi))
    q.mahalli = mahalli
    q.y.mahalli = mahalli
    q.kodla(rng.normal(size=(n_satir, 12)))
    q.superpozisyon()
    q.harman()
    kok_adlari = kulli_sektor_adlari()
    for a in kok_adlari:
        q.sektor_donmesi(a, 0.4)
    from .donanim import bellek_haddi
    from kuantum.parametre_yazmaci import ParametreAyari, ParametreYazmaci
    p = ParametreYazmaci(64, 1, bellek_haddi(),
                         ParametreAyari(tohum=int(tohum)))

    once_yuva = nufuslar(q)
    once_kok = {a: float(mahalli.cartan_oku(a)) for a in kok_adlari}
    qsicil()[int(no)].kosu(q, p)
    sonra_yuva = nufuslar(q)
    sonra_kok = {a: float(mahalli.cartan_oku(a)) for a in kok_adlari}
    sapma_yuva = np.max(np.abs(sonra_yuva - once_yuva), axis=1)
    sapma_kok = {a: abs(sonra_kok[a] - once_kok[a]) for a in kok_adlari}

    yuv = yuva_bolgeleri(q)
    olculen, en_buyuk = [], {}
    for a in ("veri", "yerel"):
        if not yuv.get(a):
            continue
        sv = float(np.max(sapma_yuva[np.asarray(yuv[a], np.intp)]))
        en_buyuk[a] = sv
        if sv > esik:
            olculen.append(a)
    for a in kok_adlari:
        en_buyuk[a] = sapma_kok[a]
        if sapma_kok[a] > esik:
            olculen.append(a)

    ilan = set(SOZLESME[int(no)][0])
    hepsi_yuva = []
    for a in ilan & {"veri", "yerel"}:
        hepsi_yuva += yuv.get(a, [])
    if not hepsi_yuva:
        guz = ilan & {"veri", "yerel"}
    else:
        bas, son = min(hepsi_yuva), max(hepsi_yuva)
        guz = {a for a, y in yuv.items()
               if y and any(bas <= i <= son for i in y)}
    guz |= ilan & set(kok_adlari)

    return {
        "no": int(no),
        "ilan": tuple(sorted(ilan)),
        "güzergâh": tuple(sorted(guz - ilan)),
        "ölçülen": tuple(sorted(olculen)),
        "ihlâl": tuple(sorted(set(olculen) - guz)),
        "kullanılmayan": tuple(sorted(ilan - set(olculen))),
        "sapma": en_buyuk,
        "sadakat": float(q.y.sadakat()),
    }


