    tenakuz_eps: float = 1e-5
    dislama_tau: float = 8.0
    lam_kategori: float = 0.5
    lam_nokta: float = 0.25
    lam_meleke: float = 0.5
    lam_zirh: float = 0.5
    lam_kaide: float = 0.5
    lam_tasma: float = 0.5
