NIZAM_ACIK: bool = False


def nizami_ac(acik: bool = True) -> bool:
    global NIZAM_ACIK
    eski = NIZAM_ACIK
    NIZAM_ACIK = bool(acik)
    return eski


KANONIK_ACIK: bool = False


def kanoniklestir(acik: bool = True) -> bool:
    global KANONIK_ACIK
    eski = KANONIK_ACIK
    KANONIK_ACIK = bool(acik)
    return eski

_QSICIL: Dict[int, "QMeleke"] = {}


def qkaydet(sinif):
    ornek = sinif()
    if ornek.no in _QSICIL:
        raise ValueError("𝒪%d iki kere kaydedildi" % ornek.no)
    _QSICIL[ornek.no] = ornek
    return sinif


def qsicil() -> Dict[int, "QMeleke"]:
    return dict(_QSICIL)


def qmelekeler() -> List["QMeleke"]:
    return [_QSICIL[i] for i in sorted(_QSICIL)]


def nizam_cetveli() -> List[Tuple[int, str, str, Optional[int]]]:
    return [(m.no, m.ad, m.SINIF, m.CHI) for m in qmelekeler()]


def harman_uretecleri(lif) -> "list":
    out = []
    for f, n in enumerate(tuple(int(x) for x in lif)):
        for alt in range(max(1, int(n).bit_length() - 1)):
            out.append((int(f), int(alt)))
    return out


def harman_anahtari(q, ayar) -> "tuple":
    azami = tuple(int(x) for x in (getattr(ayar, "lif_yapisi", None)
                                   or q.y.ayar.lif))
    kademe = max(1, int(getattr(ayar, "harman_kademesi", 1)))
    n = kademe * len(harman_uretecleri(azami))
    assert n >= kademe * len(harman_uretecleri(
        tuple(int(x) for x in q.y.ayar.lif))), (
        "harman yazmacı azamî liften küçük çıktı: azamî %r, fiilî %r "
        "-- yazmaç bir tanedir (ferman 1-M)" % (azami, q.y.ayar.lif))
    return ("harman", int(n))


class QMeleke:

    no: int = 0
    ad: str = ""
    BIRIKIM_ACI: int = 8

    SINIF: str = "koruyucu"
    CHI: Optional[int] = None

    def aci(self, p, n: int, olcek: float = 0.6) -> np.ndarray:
        anahtar = "q%d.%s/%d" % (self.no, self.ad, int(n))
        assert hasattr(p, "al"), (
            "açı yalnız parametre yazmacından okunur; çıplak parametre "
            "yasaktır (ferman 2-R). Verilen: %s" % type(p).__name__)
        return olcek * p.al(anahtar, n)

    def yay(self, p, n_sabit: int, hedef: int, olcek: float = 0.6
            ) -> np.ndarray:
        g = max(1, int(getattr(p, "genislik", 1)))
        a = self.aci(p, int(n_sabit) * g, olcek)
        if hedef <= 0:
            return np.zeros(0)
        return np.resize(a, int(hedef))

    def birikim(self, p, n: int, olcek: float = 0.6) -> np.ndarray:
        return self.yay(p, self.BIRIKIM_ACI, n, olcek) / max(float(n), 1.0)

    def dik_bagi(self, p, a, olcek: float = 0.6, devrik: bool = False):
        from kuantum.kapilar import dik_iki_kubit_turevi
        a = np.asarray(a, float).reshape(-1)
        bas = self.aci_yeri(p, int(a.size))
        if bas < 0:
            return None
        dG = dik_iki_kubit_turevi(a)
        kat = self.aci_katsayisi(p)
        return [(int(bas) + j, float(olcek) * kat,
                 np.asarray(dG[j]).T if devrik else dG[j])
                for j in range(len(dG))]

    def donme_baglari(self, par, olcek: float, acilar, egim=None,
                      kontrollu: bool = False):
        if par is None:
            return None
        t = np.asarray(acilar, float).reshape(-1)
        e = (np.ones(t.size) if egim is None
             else np.asarray(egim, float).reshape(-1))
        pid = np.asarray(par, np.int64).reshape(-1)
        assert pid.size == t.size and e.size == t.size, (
            "her açının kendi parametresi ve eğimi olmalı: %d/%d/%d"
            % (t.size, pid.size, e.size))
        tur = kontrollu_donme_turevi if kontrollu else donme_turevi
        return [(int(pid[i]), float(olcek),
                 float(e[i]) * tur(float(t[i]))) for i in range(t.size)]

    def yay_bagi(self, p, n_sabit: int, hedef: int, olcek: float = 0.6):
        g = max(1, int(getattr(p, "genislik", 1)))
        blok = int(n_sabit) * g
        bas = self.aci_yeri(p, blok)
        if bas < 0 or int(hedef) <= 0:
            return None, 0.0
        return (bas + (np.arange(int(hedef), dtype=np.int64) % blok),
                float(olcek) * self.aci_katsayisi(p))

    def aci_bagi(self, p, n: int, olcek: float = 0.6):
        bas = self.aci_yeri(p, int(n))
        if bas < 0:
            return None, 0.0
        return (bas + np.arange(int(n), dtype=np.int64),
                float(olcek) * self.aci_katsayisi(p))

    def birikim_bagi(self, p, n: int, olcek: float = 0.6):
        g = max(1, int(getattr(p, "genislik", 1)))
        blok = int(self.BIRIKIM_ACI) * g
        bas = self.aci_yeri(p, blok)
        if bas < 0:
            return None, 0.0
        return (bas + (np.arange(int(n), dtype=np.int64) % blok),
                float(olcek) * self.aci_katsayisi(p) / max(float(n), 1.0))

    def uygula(self, q: QYazmac, p) -> None:
        raise NotImplementedError

    def kosu(self, q: QYazmac, p) -> None:
        n0 = q.iz.kapi
        if KANONIK_ACIK:
            q.y.kanonikle()
        self.uygula(q, p)
        q.iz.not_dus("𝒪%d %s" % (self.no, self.ad),
                     "%d kapı" % (q.iz.kapi - n0))

    def tugla(self, q: QYazmac, p, ofset: int = 0,
              olcek: float = 0.5) -> None:
        from kuantum.kapilar import dik_iki_kubit_turevi
        a = self.aci(p, 6, olcek)
        G = dik_iki_kubit(a)
        k = q.veri_yuvasi
        sol = q.veri_izgara(range(ofset, k - 1, 2))
        bas = self.aci_yeri(p, 6)
        baglar = None
        if q.iz.senet_acik and bas >= 0:
            dG = dik_iki_kubit_turevi(a)
            baglar = [(bas + j, float(olcek), dG[j]) for j in range(6)]
        q.cift_yigin(sol, G, baglar=baglar)

    def aci_yeri(self, p, n: int) -> int:
        anahtar = "q%d.%s/%d" % (self.no, self.ad, int(n))
        assert hasattr(p, "aci_adresi"), (
            "açının parametre adresi yalnız yazmaçtan alınır "
            "(ferman 2-R): %s" % type(p).__name__)
        return int(p.aci_adresi(anahtar, int(n))[0])

    def aci_katsayisi(self, p) -> float:
        return float(p.aci_katsayisi())

    def yuva_donmesi(self, q: QYazmac, p, yuvalar,
                     olcek: float = 0.6, kayma: float = 0.0,
                     n: int = 0) -> None:
        yv = [int(y) for y in yuvalar]
        if not yv:
            return
        kac = int(n) if int(n) > 0 else len(yv)
        a = self.aci(p, kac, olcek)
        bas = self.aci_yeri(p, kac)
        for i, y in enumerate(yv):
            j = i % a.size
            if not q.y.gecerli(int(y)) or bas < 0:
                q.y._dusen_kapi += 1
                continue
            t = float(kayma) + float(a[j])
            kk, aa = q.y._lif_no(int(y))
            q.tek(int(y), donme(t))
            c, sn = math.cos(t), math.sin(t)
            q.iz.bag_yaz(q.iz.son_senet, bas + j, float(olcek),
                         ("bit", int(kk), int(aa),
                          np.array([[-sn, -c], [c, -sn]], complex)))

    def satir_donmesi(self, q: QYazmac, p,
                      olcek: float = 0.6) -> None:
        k = q.veri_yuvasi
        self.yuva_donmesi(q, p, list(q.veri_izgara()), olcek=olcek, n=k)


