class Usul:

    def __init__(self, ad: str, kur: Callable[[Dict[str, Onerme]], Onerme],
                 izah: str = "") -> None:
        self.ad = ad
        self.izah = izah
        self.formul = kur({a: deg(a) for a, _ in ALANLAR})


