# ==== BAŞLIYOR: tanilama/hiz_teftisi.py ====
from __future__ import annotations

import time
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

import numpy as np

__all__ = ["HEDEF", "had", "had_sifirla", "BUTCE_SANIYESI",
           "olc", "teftis", "rapor"]

HEDEF: float = 1_000_000.0
_HAD: list = []


def had(yazmac_boyu: int = 0, kapi: int = 0) -> float:
    if _HAD:
        return float(_HAD[0])
    from nefs.donanim import tamsayi_hizi
    t = tamsayi_hizi()
    sn = float(t["sn"])
    assert sn > 0.0, (
        "tamsayı hızı yoklanamadı -- had ölçüsüz konamaz (ferman 5-B)")
    kelime = float(t["satır"]) * float(t["kelime"])
    d = float(yazmac_boyu) if int(yazmac_boyu) > 0 else kelime
    k = float(kapi) if int(kapi) > 0 else 1.0
    _HAD.append(kelime / sn / max(d / kelime, 1.0) / k)
    return float(_HAD[0])


def had_sifirla() -> None:
    _HAD.clear()

BUTCE_SANIYESI: float = 86_400.0


@dataclass
class Kalem:

    ad: str
    cagri: int
    sure: float

    @property
    def basina(self) -> float:
        return self.sure / max(1, self.cagri)


def _saat(f, *a, **k) -> Tuple[Any, float]:
    t = time.perf_counter()
    r = f(*a, **k)
    return r, time.perf_counter() - t


def olc(ayar=None, ornek: int = 0, tekrar: int = 1) -> Dict[str, Any]:
    from main.egitim import KISA_CPU, mizan_ayari
    from nefs.hafiza import Hafiza
    from nefs.kulli_mizan import kulli_mizan
    from nefs.melekeler import QNefs
    from nefs.musahede import gorevleri_getir
    from kuantum.qegitim import belirtecleri_kodla, ornekler

    a = ayar or KISA_CPU
    ornek = int(ornek) if int(ornek) > 0 else int(a.ornek_sayisi)
    g = list(gorevleri_getir("training"))
    veri = ornekler(g, azami=int(ornek), pencere=int(a.pencere),
                    sozluk=int(a.sozluk), tohum=int(a.tohum),
                    taban=int(a.veri_lifi),
                    basamak=int(getattr(a, "belirtec_basamak", 0)))
    assert veri, "hız teftişi için veri BOŞ"
    from kuantum.qegitim import ornek_bol
    nefs = QNefs(a.tohum, a.qayar())
    nefs.idrak_et(belirtecleri_kodla(list(ornek_bol(veri[0])[0]),
                                     a.veri_lifi, a.veri_lifi))
    p = nefs.vektor()

    kalem: List[Kalem] = []

    t = 0.0
    for bag, _h, _c, _m in (ornek_bol(o) for o in veri):
        _, s = _saat(belirtecleri_kodla, list(bag), a.veri_lifi, a.sozluk)
        t += s
    kalem.append(Kalem("belirteç kodlaması", len(veri), t))

    E = belirtecleri_kodla(list(veri[0][0]), a.veri_lifi,
                           a.veri_lifi)
    t = 0.0
    _boy = {}
    for _o in veri:
        _boy.setdefault(len(_o[0]), []).append(_o)
    _esit = _boy[max(_boy, key=lambda k: len(_boy[k]))]
    Ey = np.stack([belirtecleri_kodla(list(bag), a.veri_lifi,
                                          a.veri_lifi)
                   for bag, _h, _c, _m in (ornek_bol(o) for o in _esit)])
    for _ in range(int(tekrar)):
        _, s = _saat(nefs.idrak_et, Ey)
        t += s
    kalem.append(Kalem("ileri geçiş (idrak_et)", int(tekrar), t))

    q = nefs.idrak_et(E)
    tek: List[Tuple[str, float]] = []
    for no in list(nefs.sira)[:41]:
        _, s = _saat(nefs.s[no].kosu, q, nefs.p)
        tek.append((getattr(nefs.s[no], "ad", str(no)), s))
    tek.sort(key=lambda x: -x[1])

    _, s_harman = _saat(q.harman)
    _, s_olc = _saat(q.olcumler)
    _, s_ent = _saat(q.y.dolasiklik_entropisi)
    _, s_bey = _saat(q.beyan, 0)
    kalem.append(Kalem("harman", 1, s_harman))
    kalem.append(Kalem("olcumler", 1, s_olc))
    kalem.append(Kalem("dolaşıklık entropisi", 1, s_ent))
    kalem.append(Kalem("beyan", 1, s_bey))

    mz = mizan_ayari(a)
    haf = Hafiza(kapasite=32)
    _, s_mizan = _saat(kulli_mizan, nefs, veri, p, a.sozluk,
                       ayar=mz, hafiza=haf, adim=0)
    kalem.append(Kalem("kulli_mizan (tam çağrı)", 1, s_mizan))

    belirtec = len(veri) * int(a.pencere)
    ileri = [k for k in kalem if k.ad.startswith("ileri")][0]
    return {
        "kalem": kalem, "tek_meleke": tek,
        "belirteç": belirtec,
        "d": int(np.prod(q.y.ayar.lif)), "lif": tuple(q.y.ayar.lif),
        "parametre": len(nefs),
        "kayıp_süresi": s_mizan,
        "ileri_payı": ileri.sure / max(1e-12, s_mizan)
        * (1.0 / max(1, int(tekrar))),
        "belirteç_sn": belirtec / max(1e-12, s_mizan),
        "meleke_sayısı": len(tek),
    }


def teftis(ayar=None, had_degeri: float = 0.0, sert: bool = True) -> Dict[str, Any]:
    o = olc(ayar)
    h = float(had_degeri) if float(had_degeri) > 0.0 else had()
    o["had"] = h
    o["hedef"] = float(HEDEF)
    o["hedefe_kat"] = float(HEDEF) / max(1e-9, o["belirteç_sn"])
    o["geçti"] = bool(o["belirteç_sn"] >= h)
    if sert:
        assert o["geçti"], (
            "HIZ HADDİ TUTMUYOR: %.1f belirteç/sn ölçüldü, %.0f lâzım "
            "(%.1f kat eksik). Had ELLE YAZILMADI, donanımdan ÖLÇÜLDÜ "
            "(ferman 5-B). Hedef %.0f'e uzaklık: %.1f kat. "
            "En pahalı uzuv: %s"
            % (o["belirteç_sn"], h, h / max(1e-9, o["belirteç_sn"]),
               HEDEF, o["hedefe_kat"],
               o["tek_meleke"][0][0] if o["tek_meleke"] else "?"))
    return o


def rapor(ayar=None) -> str:
    o = olc(ayar)
    s = ["=== HIZ TEFTİŞİ -- belirteç/sn haddi ===", "",
         "  yazmaç: d=%d  lif=%r  parametre=%d"
         % (o["d"], o["lif"], o["parametre"]),
         "  ölçülen: %d belirteç, %.3f sn → **%.1f belirteç/sn**"
         % (o["belirteç"], o["kayıp_süresi"], o["belirteç_sn"]),
         "  HAD    : %.0f belirteç/sn   →  %s  (%.1f kat eksik)"
         "   [ÖLÇÜLDÜ, elle yazılmadı -- ferman 5-B]"
         % (had(), "GEÇTİ" if o["belirteç_sn"] >= had() else "KALDI",
            had() / max(1e-9, o["belirteç_sn"])),
         "  HEDEF  : %.0f belirteç/sn   →  %.1f kat uzakta"
         % (HEDEF, HEDEF / max(1e-9, o["belirteç_sn"])),
         "", "  --- KALEM KALEM (tahmin yok, saatlendi) ---"]
    for k in o["kalem"]:
        s.append("    %-26s %5d çağrı  %8.3f sn  (%8.4f sn/çağrı)"
                 % (k.ad, k.cagri, k.sure, k.basina))
    s += ["", "  --- EN PAHALI 10 MELEKE ---"]
    for ad, sn in o["tek_meleke"][:10]:
        s.append("    %-40s %8.4f sn" % (ad[:40], sn))
    s += ["", "  ileri geçişin kayıp içindeki payı: %%%.1f"
          % (100.0 * o["ileri_payı"])]
    return "\n".join(s)
# ==== BİTTİ: tanilama/hiz_teftisi.py ====

# ==== BAŞLIYOR: tanilama/hizolcer.py ====
from __future__ import annotations

import time
from contextlib import contextmanager
from typing import Any, Dict, List, Optional

__all__ = ["Hizolcer", "hizolcer_bagla", "hizolcer_al", "hizolcer_beyani",
           "hizolcer_coz", "hiz_asimi", "hiz_metni"]

_BAGLI: Optional["Hizolcer"] = None


class Hizolcer:

    __slots__ = ("ad", "belirtec_basina", "had", "sert", "sure",
                 "baslangic", "belirtec", "canli_saniye", "_son_bildirim")

    def __init__(self, belirtec_basina: int, had: Optional[float] = None,
                 ad: str = "hat", sert: bool = False,
                 canli_saniye: float = 0.0) -> None:
        assert int(belirtec_basina) > 0, (
            "çağrı başına belirteç sıfır olamaz -- ölçü bölünemez")
        self.ad = str(ad)
        self.belirtec_basina = int(belirtec_basina)
        self.belirtec: list = []
        self.had = None if had is None else float(had)
        self.sert = bool(sert)
        self.sure: List[float] = []
        self.baslangic = time.perf_counter()
        self.canli_saniye = float(canli_saniye)
        self._son_bildirim = time.perf_counter()

    @contextmanager
    def saat(self, belirtec: int = 0):
        t0 = time.perf_counter()
        try:
            yield self
        finally:
            self.sure.append(time.perf_counter() - t0)
            self.belirtec.append(int(belirtec) if belirtec > 0
                                 else int(self.belirtec_basina))
            self._canli()
            if self.sert:
                t = self.tavan()
                assert not t["aşıldı"], (
                    "HIZ TAVANI AŞILDI (%s): toplam hız %.0f belirteç/sn, "
                    "hattın EN KÖTÜ tek çağrısının (%.0f) bile altında. "
                    "Tek çağrıların hiçbiri bu kadar yavaş değilken "
                    "toplamın altına düşmesi, saatlenmeyen yerde tıkanma "
                    "demektir (en iyi %.0f). Ferman 2-G."
                    % (self.ad, t["hız"], t["en_kötü"], t["en_iyi"]))

    def _canli(self) -> None:
        if self.canli_saniye <= 0.0:
            return
        t = time.perf_counter()
        if t - self._son_bildirim < self.canli_saniye:
            return
        self._son_bildirim = t
        sn = sum(self.sure) or 1e-12
        bel = sum(self.belirtec)
        from nefs.munasebet import munasebet_beyani
        from nefs.keyfiyet import keyfiyet_beyani
        from ogrenme.mecz import (mecz_beyani, yetim_bloklar,
                                  adres_beyani)
        from nefs.kulli_mizan import kefe_kimiltisi
        from kuantum.qyazmac import sektor_beyani
        s = sektor_beyani()
        m = munasebet_beyani()
        k = keyfiyet_beyani()
        z = mecz_beyani()
        print("  [%7.1f sn] çağrı %4d | belirteç %10d | %9.0f bel/sn | "
              "küme %d temiz / %d kirli / %d geri dönen | "
              "keyfiyet en_iyi %.4f ort %.4f | "
              "mecz r %.3e · iz_g %.3e · ‖eğim‖ %.3e · κ %.3e · "
              "kabul %d/%d · hissedilmeyen %d · r* %.3e · "
              "ΔV %.3e vs lineer %.3e | kımıldayan kefe %s %+.3e, "
              "%s %+.3e | yetim blok %s | küllî tarama: iç çarpım %d · "
              "faz yazması %d · kapı dizeyi %d (kenet %d) | adres %s"
              % (t - self.baslangic, len(self.sure), bel, bel / sn,
                 m["temizlenen"], m["kirli_kalan"], m.get("geri_dönen", 0),
                 k["en_iyi"], k["ortalama"],
                 z["yarıçap"], z["iz_g"], z["eğim_normu"], z["κ"],
                 int(z["kabul"]), int(z["tur"]),
                 int(z["hissedilmeyen_adım"]), z["r_kullanılan"],
                 z["ΔV_gerçek"], z["ΔV_lineer"],
                 kefe_kimiltisi()["ad"], kefe_kimiltisi()["Δ"],
                 kefe_kimiltisi()["ikinci"], kefe_kimiltisi()["Δ2"],
                 " · ".join("%s %d" % (ad, n)
                            for n, ad in yetim_bloklar()) or "yok",
                 int(s.get("küllî_iç_çarpım", 0)),
                 int(s.get("küllî_faz_yazması", 0)),
                 int(s.get("kapı_dizeyi", 0)), int(s.get("kenet", 0)),
                 adres_beyani() or "yoklanmadı"),
              flush=True)

    def asim(self) -> float:
        b = self.beyan()
        if self.had is None or int(b["çağrı"]) == 0:
            return 0.0
        return max(0.0, 1.0 - float(b["belirteç_sn"]) / float(self.had))

    def tavan(self) -> Dict[str, Any]:
        b = self.beyan()
        hiz = float(b.get("belirteç_sn", 0.0))
        en_iyi = float(b.get("en_iyi", 0.0))
        son = float(b.get("son", 0.0))
        o = {"aşıldı": False, "kat": 0.0, "ısınma": 0.0, "hız": hiz,
             "had": float(self.had or 0.0), "en_iyi": en_iyi, "son": son}
        if int(b["çağrı"]) < 4 or en_iyi <= 0.0 or son <= 0.0:
            o["sebep"] = "tavan için en az dört saatlenmiş çağrı gerekir"
            return o
        en_kotu = float(b.get("en_kötü", 0.0))
        o["en_kötü"] = en_kotu
        o["kat"] = en_iyi / max(hiz, 1e-300)
        o["ısınma"] = max(float(b.get("ısınma", 1.0)), 1.0)
        o["aşıldı"] = bool(en_kotu > 0.0 and hiz < en_kotu)
        return o

    def ekle(self, sn: float) -> None:
        self.sure.append(float(sn))

    def beyan(self) -> Dict[str, Any]:
        n = len(self.sure)
        o: Dict[str, Any] = {
            "ad": self.ad, "çağrı": n,
            "had": (0 if self.had is None else self.had),
            "çağrı_belirteci": self.belirtec_basina,
        }
        if n == 0:
            o.update({"toplam_sn": 0.0, "belirteç": 0, "belirteç_sn": 0.0,
                      "en_iyi": 0.0, "en_kötü": 0.0, "ilk": 0.0, "son": 0.0,
                      "ısınma": 0.0,
                      "hüküm": "ÖLÇÜLMEDİ -- hiç çağrı saatlenmedi"})
            return o
        toplam = float(sum(self.sure))
        bel = (self.belirtec if len(self.belirtec) == n
               else [self.belirtec_basina] * n)
        belirtec = int(sum(bel))
        hiz = [b / max(s, 1e-12) for b, s in zip(bel, self.sure)]
        o.update({
            "toplam_sn": toplam,
            "belirteç": int(belirtec),
            "belirteç_sn": float(belirtec / max(toplam, 1e-12)),
            "en_iyi": float(max(hiz)), "en_kötü": float(min(hiz)),
            "ilk": float(hiz[0]), "son": float(hiz[-1]),
            "ısınma": float(hiz[-1] / max(hiz[0], 1e-12)),
        })
        if self.had is None:
            o["hüküm"] = "had konmadı (ölçü yalnız görülüyor)"
        else:
            kat = self.had / max(o["belirteç_sn"], 1e-12)
            o["hüküm"] = ("TUTUYOR" if o["belirteç_sn"] >= self.had
                          else "TUTMUYOR (%.1f kat eksik)" % kat)
        return o


def hizolcer_bagla(olcer: Optional[Hizolcer]) -> None:
    global _BAGLI
    _BAGLI = olcer


def hizolcer_coz() -> None:
    global _BAGLI
    _BAGLI = None


def hizolcer_al() -> Optional[Hizolcer]:
    return _BAGLI


def hizolcer_beyani() -> Dict[str, Any]:
    if _BAGLI is None:
        return {"ad": "-", "çağrı": 0, "had": 0, "çağrı_belirteci": 0,
                "toplam_sn": 0.0, "belirteç": 0, "belirteç_sn": 0.0,
                "en_iyi": 0.0, "en_kötü": 0.0, "ilk": 0.0, "son": 0.0,
                "ısınma": 0.0, "hüküm": "HIZÖLÇER BAĞLI DEĞİL"}
    return _BAGLI.beyan()


def hiz_asimi() -> float:
    return 0.0 if _BAGLI is None else float(_BAGLI.asim())


def hiz_metni() -> str:
    if _BAGLI is None:
        return "  HIZ: hızölçer bağlı değil -- ölçü hiçbir şey ölçmüyor."
    b = _BAGLI.beyan()
    t = _BAGLI.tavan()
    return "\n".join([
        "  HIZ HADDİ (ferman 5: kırmızı yanabilir)",
        "    ölçülen %.0f belirteç/sn   had %.0f   hüküm: %s"
        % (b["belirteç_sn"], b["had"], b["hüküm"]),
        "    aşım kefesi : %.6f   (0 = had tutuyor)" % _BAGLI.asim(),
        "    tavan       : %s   (toplam %.0f · en iyi %.0f · en kötü %.0f)"
        % ("AŞILDI" if t["aşıldı"] else "aşılmadı", t.get("hız", 0.0),
           t.get("en_iyi", 0.0), t.get("en_kötü", 0.0)),
        "    TAVAN HADDE GÖRE DEĞİL, HATTIN KENDİ DAĞILIMINA GÖREDİR:",
        "    toplam hız, en kötü TEK çağrının altına düşerse tıkanma var",
        "    demektir. Sabit bir sayı yok; hudut ölçülenden çıkıyor (1-J).",
        "    Aşım kefesi p'ye zayıf bağlıdır; payı ölçülünce sıfıra yakın",
        "    çıkarsa bu bir kusur değil, ferman 1-S'nin beklediği neticedir."])
# ==== BİTTİ: tanilama/hizolcer.py ====

# ==== BAŞLIYOR: tanilama/sabit_teftisi.py ====
from __future__ import annotations

import ast
import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple

__all__ = ["Sabit", "KOK", "ATLANAN", "tara", "ozet", "rapor"]

KOK = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

ATLANAN = frozenset({0, 1, -1, 2, -2, 0.0, 1.0, -1.0, 2.0, 0.5})

_HARIC = ("__pycache__", ".git", "depo", "yedek")

_KOD_DEGIL = (os.path.join("idrak", "veri"), "docs")


@dataclass
class Sabit:

    dosya: str
    satir: int
    kap: str
    ad: str
    deger: str
    cins: str
    serh: bool


def _deger(d: ast.AST) -> Optional[str]:
    if isinstance(d, ast.Constant) and isinstance(
            d.value, (int, float, str, bool)) and not isinstance(
            d.value, bool):
        return repr(d.value)
    if isinstance(d, ast.UnaryOp) and isinstance(d.op, ast.USub):
        i = _deger(d.operand)
        return None if i is None else "-" + i
    if isinstance(d, (ast.Tuple, ast.List)):
        parcalar = [_deger(x) for x in d.elts]
        if all(x is not None for x in parcalar):
            return "(" + ", ".join(p for p in parcalar if p) + ")"
    if isinstance(d, ast.Call):
        f = getattr(d.func, "id", None) or getattr(d.func, "attr", None)
        if f in ("field", "frozenset", "dict"):
            return f + "(…)"
    return None


def _sayi_mi(d: ast.AST) -> bool:
    if isinstance(d, ast.Constant) and isinstance(d.value, (int, float)):
        return not isinstance(d.value, bool) and d.value not in ATLANAN
    if isinstance(d, ast.UnaryOp) and isinstance(d.op, ast.USub):
        return _sayi_mi(d.operand)
    return False


def _dosyalar(alt: Optional[str] = None) -> List[str]:
    out: List[str] = []
    kok = os.path.join(KOK, alt) if alt else KOK
    for dizin, alt_dizinler, adlar in os.walk(kok):
        alt_dizinler[:] = [d for d in alt_dizinler if d not in _HARIC]
        for ad in sorted(adlar):
            if not ad.endswith(".py") or ad.startswith("test_"):
                continue
            yol = os.path.join(dizin, ad)
            bagil = os.path.relpath(yol, KOK)
            if any(bagil.startswith(x) for x in _KOD_DEGIL):
                continue
            out.append(yol)
    return sorted(out)


def tara(alt: Optional[str] = None) -> List[Sabit]:
    cikti: List[Sabit] = []
    for yol in _dosyalar(alt):
        bagil = os.path.relpath(yol, KOK)
        kaynak = open(yol, encoding="utf-8").read()
        satirlar = kaynak.split("\n")
        agac = ast.parse(kaynak, filename=bagil)

        def serhli(no: int) -> bool:
            i = no - 2
            while i >= 0 and satirlar[i].strip().startswith("#"):
                return True
            return False

        def gez(dugum: ast.AST, kap: str, sinif: bool) -> None:
            for c in ast.iter_child_nodes(dugum):
                if isinstance(c, ast.ClassDef):
                    gez(c, c.name, True)
                elif isinstance(c, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    for arg, var in zip(
                            c.args.args[len(c.args.args)
                                        - len(c.args.defaults):],
                            c.args.defaults):
                        if _sayi_mi(var):
                            cikti.append(Sabit(
                                bagil, var.lineno, c.name, arg.arg,
                                _deger(var) or "?", "İLAN", False))
                    gez(c, ("%s.%s" % (kap, c.name)) if kap else c.name,
                        False)
                elif isinstance(c, (ast.Assign, ast.AnnAssign)):
                    hedefler = ([c.target] if isinstance(c, ast.AnnAssign)
                                else c.targets)
                    d = c.value
                    for t in hedefler:
                        ad = getattr(t, "id", None)
                        if ad is None or ad.startswith("__"):
                            continue
                        v = _deger(d) if d is not None else None
                        if sinif:
                            if v is not None:
                                cikti.append(Sabit(bagil, c.lineno, kap, ad,
                                                   v, "AYARDA",
                                                   serhli(c.lineno)))
                        elif ad.isupper():
                            if v is not None:
                                cikti.append(Sabit(bagil, c.lineno, kap, ad,
                                                   v, "İLAN",
                                                   serhli(c.lineno)))
                        elif kap and d is not None and _sayi_mi(d):
                            cikti.append(Sabit(bagil, c.lineno, kap, ad,
                                               _deger(d) or "?", "GÖMÜLÜ",
                                               serhli(c.lineno)))
                    gez(c, kap, False)
                elif isinstance(c, ast.Compare) and kap:
                    for k in c.comparators:
                        if _sayi_mi(k):
                            cikti.append(Sabit(bagil, k.lineno, kap,
                                               "(kıyas eşiği)",
                                               _deger(k) or "?", "GÖMÜLÜ",
                                               False))
                    gez(c, kap, False)
                else:
                    gez(c, kap, sinif)

        gez(agac, "", False)
    return cikti


def ozet(alt: Optional[str] = None) -> Dict[str, Any]:
    s = tara(alt)
    say = {"AYARDA": 0, "İLAN": 0, "GÖMÜLÜ": 0}
    for x in s:
        say[x.cins] += 1
    dosya: Dict[str, int] = {}
    for x in s:
        if x.cins == "GÖMÜLÜ":
            dosya[x.dosya] = dosya.get(x.dosya, 0) + 1
    return {"sabit": s, "sayım": say,
            "gömülü_dosya": sorted(dosya.items(), key=lambda t: -t[1])}


def rapor(alt: Optional[str] = None, hadd: int = 60) -> str:
    o = ozet(alt)
    s: List[Sabit] = o["sabit"]
    say = o["sayım"]
    y = ["=== SABİT TEFTİŞİ -- elle tayin edilmiş her sayı ===", "",
         "  AYARDA : %4d   (dataclass alanı -- dışarıdan değiştirilebilir)"
         % say["AYARDA"],
         "  İLAN   : %4d   (modül sabiti / varsayılan argüman -- görünür)"
         % say["İLAN"],
         "  GÖMÜLÜ : %4d   (fonksiyon gövdesinde çıplak -- **TEHLİKELİ**)"
         % say["GÖMÜLÜ"], ""]

    y.append("  --- 1. AYARDA (meşru; değeri değiştirilebilir) ---")
    ayar_kap: Dict[str, List[Sabit]] = {}
    for x in s:
        if x.cins == "AYARDA":
            ayar_kap.setdefault("%s :: %s" % (x.dosya, x.kap), []).append(x)
    for k in sorted(ayar_kap):
        y.append("    %s" % k)
        for x in ayar_kap[k]:
            y.append("      %-24s = %-22s %s"
                     % (x.ad, x.deger[:22], "şerhli" if x.serh else "ŞERHSİZ"))
    y.append("")

    y.append("  --- 2. İLAN (modül sabiti; koda gömülü fakat görünür) ---")
    for x in s:
        if x.cins == "İLAN" and x.ad.isupper():
            y.append("    %-34s %-22s %s:%d"
                     % (x.ad, x.deger[:22], x.dosya, x.satir))
    y.append("")

    y.append("  --- 3. GÖMÜLÜ (en tehlikeli; dosya dosya sayım) ---")
    for dosya, kac in o["gömülü_dosya"][:20]:
        y.append("    %-40s %4d" % (dosya, kac))
    y.append("")
    y.append("  --- GÖMÜLÜ SABİTLERİN İLK %d TANESİ ---" % hadd)
    n = 0
    for x in s:
        if x.cins != "GÖMÜLÜ":
            continue
        n += 1
        if n > hadd:
            break
        y.append("    %-30s %-18s %-16s %s:%d"
                 % (x.kap[:30], x.ad[:18], x.deger[:16], x.dosya, x.satir))
    return "\n".join(y)
# ==== BİTTİ: tanilama/sabit_teftisi.py ====

